import{v as e}from"./index-BHD4RmLx.js";var t={id:`applications-of-derivatives`,courseId:`calculus-1`,courseTitle:`Calculus I`,title:`Applications of derivatives`,concepts:[{id:`max-min`,title:`Maximum and minimum values`,objective:`Find critical numbers and the absolute maximum and minimum of a function on a closed interval.`,prerequisites:[],source:{title:`OpenStax Calculus Volume 1`,section:`4.3 Maxima and Minima`,url:`https://openstax.org/books/calculus-volume-1/pages/4-3-maxima-and-minima`},status:`unverified`,explanation:[`A critical number of $f$ is a number $c$ in its domain where $f'(c) = 0$ or $f'(c)$ does not exist. Local maxima and minima can only happen at critical numbers.`,`A continuous function on a closed interval $[a, b]$ always has an absolute maximum and an absolute minimum, and each one is at a critical number or at an endpoint.`,`The closed interval method: find the critical numbers inside $(a, b)$, evaluate $f$ at each of them and at $a$ and $b$, then pick the largest and smallest values.`,`$f'(c) = 0$ does not guarantee an extremum. For $f(x) = x^3$, $f'(0) = 0$, but the graph keeps rising through $x = 0$.`],takeaways:[`Critical number: $f'(c) = 0$ or $f'(c)$ undefined.`,`On $[a, b]$, compare $f$ at the critical numbers and at both endpoints.`,`The answer is a value of $f$; say where it happens separately.`],example:{problem:`Find the absolute maximum and minimum of $f(x) = x^3 - 3x$ on $[0, 2]$.`,steps:[`$f'(x) = 3x^2 - 3 = 0$ gives $x = \\pm 1$. Only $x = 1$ is in $[0, 2]$.`,`Evaluate: $f(0) = 0$, $f(1) = -2$, $f(2) = 2$.`,`The absolute maximum is 2, at $x = 2$, and the absolute minimum is $-2$, at $x = 1$.`]},questions:[{id:`max-min-1`,level:1,kind:`numeric`,status:`unverified`,prompt:`Find the critical number of $f(x) = x^2 - 6x + 5$.`,answer:3,criticalPointOf:`x^2 - 6x + 5`,hint:`Set $f'(x) = 2x - 6$ equal to 0.`,solutionSteps:[`Critical numbers are where $f'(x) = 0$ or $f'(x)$ does not exist.`,`$f'(x) = 2x - 6$, which exists everywhere.`,`$2x - 6 = 0$ gives $x = 3$.`],mistakes:[{answer:1,tag:`critical-number-root`,feedback:`That is where $f(x) = 0$. A critical number is where $f'(x) = 0$.`},{answer:5,tag:`critical-number-root`,feedback:`That is where $f(x) = 0$. A critical number is where $f'(x) = 0$.`}]},{id:`max-min-2`,level:1,kind:`multiple-choice`,status:`unverified`,prompt:`What is a critical number of $f$?`,solutionSteps:[`A critical number must be in the domain of $f$.`,`At it, the derivative is either 0 or does not exist.`,`So: a number $c$ in the domain of $f$ where $f'(c) = 0$ or $f'(c)$ does not exist.`],options:[{text:`A number $c$ in the domain where $f'(c) = 0$ or $f'(c)$ does not exist`,correct:!0},{text:`A number $c$ where $f(c) = 0$`,tag:`critical-number-root`,feedback:`That is a zero of $f$. Critical numbers are about the derivative.`},{text:`A number $c$ where $f''(c) = 0$`,tag:`critical-number-definition`,feedback:`$f''(c) = 0$ is where an inflection point might be. Critical numbers use the first derivative.`},{text:`The $x$ where $f$ is largest`,tag:`critical-number-definition`,feedback:`The largest value often happens at a critical number, but not every critical number is a maximum, and a maximum can be at an endpoint.`}]},{id:`max-min-3`,level:2,kind:`numeric`,status:`unverified`,prompt:`Find the absolute minimum value of $f(x) = x^3 - 12x$ on $[0, 3]$.`,answer:-16,extremum:{of:`x^3 - 12x`,from:0,to:3,kind:`min`,report:`value`},hint:`Find the critical numbers in $(0, 3)$, then compare $f$ there and at both endpoints.`,solutionSteps:[`Find the critical numbers: $f'(x) = 3x^2 - 12 = 0$ gives $x = \\pm 2$.`,`Only $x = 2$ is in $[0, 3]$.`,`Evaluate $f$ at the critical number and both endpoints: $f(0) = 0$, $f(2) = 8 - 24 = -16$, $f(3) = 27 - 36 = -9$.`,`The smallest value is the absolute minimum: $-16$.`],mistakes:[{answer:-9,tag:`closed-interval-missed-critical`,feedback:`$-9$ is $f(3)$, an endpoint. Check the critical number $x = 2$ as well.`},{answer:2,tag:`extremum-location-not-value`,feedback:`2 is where the minimum happens. The question asks for the value, $f(2)$.`}]},{id:`max-min-4`,level:2,kind:`numeric`,status:`unverified`,prompt:`Find the absolute maximum value of $f(x) = x^3 - 3x^2 + 1$ on $[-1, 4]$.`,answer:17,extremum:{of:`x^3 - 3x^2 + 1`,from:-1,to:4,kind:`max`,report:`value`},hint:`The critical numbers are where $3x^2 - 6x = 0$. Don't forget the endpoints.`,solutionSteps:[`Find the critical numbers: $f'(x) = 3x^2 - 6x = 3x(x - 2) = 0$ gives $x = 0$ and $x = 2$.`,`Both are in $[-1, 4]$.`,`Evaluate $f$: $f(-1) = -3$, $f(0) = 1$, $f(2) = -3$, $f(4) = 64 - 48 + 1 = 17$.`,`The largest value is the absolute maximum: 17, at the endpoint $x = 4$.`],mistakes:[{answer:1,tag:`closed-interval-missed-endpoint`,feedback:`1 is a local maximum, at $x = 0$. On a closed interval, the endpoints can be higher: check $f(4)$.`},{answer:4,tag:`extremum-location-not-value`,feedback:`4 is where the maximum happens. The question asks for the value, $f(4)$.`}]},{id:`max-min-5`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`If $f'(c) = 0$, what can you conclude about $f$ at $c$?`,solutionSteps:[`$f'(c) = 0$ makes $c$ a critical number, which is only a candidate for a maximum or minimum.`,`Counterexample: $f(x) = x^3$ has $f'(0) = 0$, but $f$ keeps increasing through 0.`,`So nothing can be concluded yet without another test.`],options:[{text:`Nothing yet: $c$ is only a candidate, as $f(x) = x^3$ at $x = 0$ shows`,correct:!0},{text:`$f$ has a local maximum at $c$`,tag:`critical-number-not-extremum`,feedback:`It could be a maximum, a minimum or neither. $f(x) = x^3$ has $f'(0) = 0$ and keeps rising through 0.`},{text:`$f$ has a local minimum at $c$`,tag:`critical-number-not-extremum`,feedback:`It could be a maximum, a minimum or neither. $f(x) = x^3$ has $f'(0) = 0$ and keeps rising through 0.`},{text:`$f(c)$ is the absolute maximum or minimum`,tag:`critical-number-not-extremum`,feedback:`Even a real local extremum need not be absolute, and $f(x) = x^3$ at 0 is not an extremum at all.`}]},{id:`max-min-6`,level:3,kind:`numeric`,status:`unverified`,prompt:`Where is the absolute minimum of $f(x) = |x - 2|$ on $[0, 5]$? Give the $x$-value.`,answer:2,extremum:{of:`abs(x - 2)`,from:0,to:5,kind:`min`,report:`x`},hint:`$f'(x)$ is never 0 here. Where does $f'(x)$ fail to exist?`,solutionSteps:[`The graph of $|x - 2|$ is a V with its corner at $x = 2$.`,`At the corner $f'$ does not exist, so $x = 2$ is a critical number.`,`Evaluate: $f(0) = 2$, $f(2) = 0$, $f(5) = 3$.`,`The smallest value, 0, is at $x = 2$.`],mistakes:[{answer:5,tag:`closed-interval-max-min-swap`,feedback:`$f(5) = 3$ is the largest value on the interval, the maximum.`},{answer:0,tag:`extremum-location-not-value`,feedback:`0 is the minimum value, $f(2)$. The question asks where it happens.`}]}]},{id:`mean-value-theorem`,title:`The Mean Value Theorem`,objective:`Use the Mean Value Theorem to find where the instantaneous rate of change equals the average rate of change.`,prerequisites:[],source:{title:`OpenStax Calculus Volume 1`,section:`4.4 The Mean Value Theorem`,url:`https://openstax.org/books/calculus-volume-1/pages/4-4-the-mean-value-theorem`},status:`unverified`,explanation:[`The average rate of change of $f$ on $[a, b]$ is $\\frac{f(b) - f(a)}{b - a}$, the slope of the secant line through the endpoints.`,`The Mean Value Theorem: if $f$ is continuous on $[a, b]$ and differentiable on $(a, b)$, there is at least one $c$ in $(a, b)$ with $f'(c) = \\frac{f(b) - f(a)}{b - a}$. Somewhere, the tangent line is parallel to the secant line.`,`To find $c$: compute the average rate of change, set $f'(c)$ equal to it, solve, and keep only solutions inside $(a, b)$.`,`Both conditions matter. If $f$ has a break or a corner in the interval, the theorem says nothing.`],takeaways:[`$f'(c) = \\frac{f(b) - f(a)}{b - a}$ for some $c$ in $(a, b)$.`,`Check continuity on $[a, b]$ and differentiability on $(a, b)$ first.`,`Keep only the $c$ values inside the interval.`],example:{problem:`Find the $c$ from the Mean Value Theorem for $f(x) = x^2$ on $[0, 2]$.`,steps:[`Average rate of change: $\\frac{f(2) - f(0)}{2 - 0} = \\frac{4}{2} = 2$.`,`$f'(c) = 2c = 2$ gives $c = 1$, which is in $(0, 2)$.`]},questions:[{id:`mean-value-theorem-1`,level:1,kind:`numeric`,status:`unverified`,prompt:`Find the average rate of change of $f(x) = x^3$ on $[0, 2]$.`,answer:4,hint:`Divide $f(2) - f(0)$ by $2 - 0$.`,solutionSteps:[`Average rate of change: $\\frac{f(b) - f(a)}{b - a}$.`,`$f(2) = 8$ and $f(0) = 0$.`,`$\\frac{8 - 0}{2 - 0} = 4$.`],mistakes:[{answer:8,tag:`average-rate-no-divide`,feedback:`8 is the change in $f$. Divide by the change in $x$, 2.`},{answer:12,tag:`average-rate-used-derivative`,feedback:`12 is $f'(2)$, the instantaneous rate at $x = 2$. The average rate uses only the endpoint values.`}]},{id:`mean-value-theorem-2`,level:1,kind:`multiple-choice`,status:`unverified`,prompt:`$f$ is continuous on $[a, b]$ and differentiable on $(a, b)$. What does the Mean Value Theorem guarantee?`,solutionSteps:[`$\\frac{f(b) - f(a)}{b - a}$ is the slope of the line through the two endpoints.`,`The theorem says the graph has a tangent line with that same slope somewhere inside.`,`So some $c$ in $(a, b)$ has $f'(c) = \\frac{f(b) - f(a)}{b - a}$.`],options:[{text:`Some $c$ in $(a, b)$ has $f'(c) = \\frac{f(b) - f(a)}{b - a}$`,correct:!0},{text:`Some $c$ in $(a, b)$ has $f'(c) = 0$`,tag:`mvt-rolle`,feedback:`That is Rolle's Theorem, which also needs $f(a) = f(b)$. In general the slope matches the secant line.`},{text:`Some $c$ in $(a, b)$ has $f(c) = \\frac{f(b) - f(a)}{b - a}$`,tag:`mvt-statement`,feedback:`The theorem is about the slope $f'(c)$, not the value $f(c)$.`},{text:`$f'(x) = \\frac{f(b) - f(a)}{b - a}$ for every $x$ in $(a, b)$`,tag:`mvt-statement`,feedback:`Only some $c$ is guaranteed, not every $x$. That would only happen for a straight line.`}]},{id:`mean-value-theorem-3`,level:2,kind:`numeric`,status:`unverified`,prompt:`Find the $c$ that satisfies the Mean Value Theorem for $f(x) = x^2 + 3x$ on $[1, 4]$.`,answer:2.5,criticalPointOf:`x^2 + 3x - 8x`,hint:`The average rate of change is $\\frac{28 - 4}{3} = 8$. Solve $f'(c) = 2c + 3 = 8$.`,solutionSteps:[`Average rate of change: $\\frac{f(4) - f(1)}{4 - 1} = \\frac{28 - 4}{3} = 8$.`,`Derivative: $f'(c) = 2c + 3$.`,`Set them equal: $2c + 3 = 8$ gives $c = 2.5$.`,`$2.5$ is in $(1, 4)$, so $c = 2.5$.`],mistakes:[{answer:8,tag:`mvt-slope-not-c`,feedback:`8 is the average rate of change. Now find the $c$ where $f'(c) = 8$.`}]},{id:`mean-value-theorem-4`,level:2,kind:`numeric`,status:`unverified`,prompt:`Find the $c$ that satisfies the Mean Value Theorem for $f(x) = x^3$ on $[0, 3]$.`,answer:1.7320508075688772,criticalPointOf:`x^3 - 9x`,hint:`The average rate of change is $\\frac{27}{3} = 9$. Solve $3c^2 = 9$ and keep the solution in $(0, 3)$.`,solutionSteps:[`Average rate of change: $\\frac{f(3) - f(0)}{3 - 0} = \\frac{27}{3} = 9$.`,`Derivative: $f'(c) = 3c^2$.`,`Set them equal: $3c^2 = 9$, so $c^2 = 3$ and $c = \\pm\\sqrt{3}$.`,`Only $c = \\sqrt{3} \\approx 1.732$ is in $(0, 3)$.`],mistakes:[{answer:9,tag:`mvt-slope-not-c`,feedback:`9 is the average rate of change. Now find the $c$ where $f'(c) = 9$.`},{answer:-1.7320508075688772,tag:`mvt-outside-interval`,feedback:`$-\\sqrt{3}$ solves $3c^2 = 9$ but is not in $(0, 3)$.`},{answer:3,tag:`mvt-solve`,feedback:`That solves $c^2 = 9$. The equation is $3c^2 = 9$, so $c^2 = 3$.`}]},{id:`mean-value-theorem-5`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`Why does the Mean Value Theorem not apply to $f(x) = \\frac{1}{x}$ on $[-1, 1]$?`,solutionSteps:[`The theorem needs $f$ continuous on the whole closed interval $[-1, 1]$.`,`$\\frac{1}{x}$ is undefined at $x = 0$, which is inside the interval.`,`So the hypothesis fails and the theorem does not apply.`],options:[{text:`It is not continuous on $[-1, 1]$: it is undefined at $x = 0$`,correct:!0},{text:`$f(-1) \\ne f(1)$`,tag:`mvt-rolle`,feedback:`Equal endpoint values are needed for Rolle's Theorem, not for the Mean Value Theorem.`},{text:`It is not differentiable at the endpoints`,tag:`mvt-conditions`,feedback:`Differentiability is only needed inside the interval, and $\\frac{1}{x}$ is differentiable at $\\pm 1$. The problem is at $x = 0$.`},{text:`It does apply, with $c = 0$`,tag:`mvt-conditions`,feedback:`$f$ is not even defined at 0. A break in the interval means the theorem guarantees nothing.`}]},{id:`mean-value-theorem-6`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`A car travels 120 miles in 2 hours. What does the Mean Value Theorem say about its speed?`,solutionSteps:[`Position is continuous and differentiable, so the theorem applies on the 2-hour interval.`,`Average speed: $\\frac{120}{2} = 60$ mph.`,`So at some moment the instantaneous speed was exactly 60 mph.`],options:[{text:`At some moment the car was going exactly 60 mph`,correct:!0},{text:`The car went 60 mph the whole time`,tag:`mvt-statement`,feedback:`The theorem guarantees one moment, not every moment. The car could have sped up and slowed down.`},{text:`The car never went faster than 60 mph`,tag:`mvt-statement`,feedback:`If it was slower at times, it must have been faster at others. The theorem only promises 60 mph at some moment.`},{text:`Nothing, because speed is not a function`,tag:`mvt-conditions`,feedback:`Position is a function of time, and its derivative is velocity. The theorem applies to it.`}]}]},{id:`shape-of-graph`,title:`How derivatives shape a graph`,objective:`Use the first and second derivatives to find where a function rises, falls and bends, and to classify critical numbers.`,prerequisites:[`max-min`],source:{title:`OpenStax Calculus Volume 1`,section:`4.5 Derivatives and the Shape of a Graph`,url:`https://openstax.org/books/calculus-volume-1/pages/4-5-derivatives-and-the-shape-of-a-graph`},status:`unverified`,explanation:[`Where $f'(x) > 0$, $f$ is increasing; where $f'(x) < 0$, $f$ is decreasing.`,`First derivative test: at a critical number $c$, if $f'$ changes from positive to negative, $f$ has a local maximum; from negative to positive, a local minimum; if the sign does not change, neither.`,`Where $f''(x) > 0$, $f$ is concave up (bends upward); where $f''(x) < 0$, concave down. An inflection point is where the concavity changes.`,`Second derivative test: if $f'(c) = 0$ and $f''(c) < 0$, local maximum; if $f''(c) > 0$, local minimum; if $f''(c) = 0$, the test gives no answer.`],takeaways:[`$f' > 0$: increasing. $f' < 0$: decreasing.`,`$f'' > 0$: concave up. $f'' < 0$: concave down.`,`$f''(c) = 0$ alone does not make an inflection point; the sign of $f''$ must change.`],example:{problem:`Classify the critical numbers of $f(x) = x^3 - 3x$ and find its inflection point.`,steps:[`$f'(x) = 3x^2 - 3 = 0$ gives $x = -1$ and $x = 1$.`,`$f''(x) = 6x$. $f''(-1) = -6 < 0$, so local maximum at $x = -1$; $f''(1) = 6 > 0$, so local minimum at $x = 1$.`,`$f''$ changes sign at $x = 0$, so $(0, 0)$ is an inflection point.`]},questions:[{id:`shape-of-graph-1`,level:1,kind:`multiple-choice`,status:`unverified`,prompt:`If $f'(x) > 0$ for every $x$ in an interval, what is true of $f$ there?`,solutionSteps:[`$f'(x)$ is the slope of the graph at $x$.`,`Positive slope everywhere on the interval means the graph rises as $x$ increases.`,`So $f$ is increasing there.`],options:[{text:`$f$ is increasing`,correct:!0},{text:`$f$ is concave up`,tag:`first-vs-second-derivative`,feedback:`Concavity comes from the second derivative, $f''$. The sign of $f'$ tells whether $f$ rises or falls.`},{text:`$f(x) > 0$`,tag:`derivative-sign-vs-value`,feedback:`$f$ can be negative while rising. $f' > 0$ is about direction, not the values of $f$.`},{text:`$f$ is decreasing`,tag:`derivative-sign`,feedback:`A positive slope goes up from left to right, so $f$ is increasing.`}]},{id:`shape-of-graph-2`,level:1,kind:`numeric`,status:`unverified`,prompt:`Find the $x$-value of the inflection point of $f(x) = x^3 - 6x^2 + 1$.`,answer:2,criticalPointOf:`3x^2 - 12x`,hint:`Find $f''(x)$ and set it equal to 0.`,solutionSteps:[`$f'(x) = 3x^2 - 12x$.`,`$f''(x) = 6x - 12$, which is 0 at $x = 2$.`,`$f''$ is negative for $x < 2$ and positive for $x > 2$, so concavity changes there.`,`The inflection point is at $x = 2$.`],mistakes:[{answer:0,tag:`inflection-used-first-derivative`,feedback:`That is where $f'(x) = 0$, a critical number. Inflection points come from $f''(x)$.`},{answer:4,tag:`inflection-used-first-derivative`,feedback:`That is where $f'(x) = 0$, a critical number. Inflection points come from $f''(x)$.`}]},{id:`shape-of-graph-3`,level:2,kind:`numeric`,status:`unverified`,prompt:`$f(x) = x^3 - 3x^2 - 9x + 2$ has one local maximum. At what $x$?`,answer:-1,criticalPointOf:`x^3 - 3x^2 - 9x + 2`,hint:`$f'(x) = 3(x - 3)(x + 1)$. Use $f''(x) = 6x - 6$ to tell the two critical numbers apart.`,solutionSteps:[`$f'(x) = 3x^2 - 6x - 9 = 3(x - 3)(x + 1)$, so the critical numbers are $x = -1$ and $x = 3$.`,`$f''(x) = 6x - 6$.`,`$f''(-1) = -12 < 0$: concave down, so $x = -1$ is a local maximum.`,`$f''(3) = 12 > 0$, so $x = 3$ is the local minimum.`],mistakes:[{answer:3,tag:`second-derivative-test-sign`,feedback:`$f''(3) = 12 > 0$, so the graph is concave up there: that is the local minimum.`}]},{id:`shape-of-graph-4`,level:2,kind:`numeric`,status:`unverified`,prompt:`Find the local minimum value of $f(x) = x^4 - 8x^2$ for $x > 0$.`,answer:-16,extremum:{of:`x^4 - 8x^2`,from:0,to:3,kind:`min`,report:`value`},hint:`$f'(x) = 4x(x^2 - 4)$. Which critical number is positive, and what is $f$ there?`,solutionSteps:[`$f'(x) = 4x^3 - 16x = 4x(x^2 - 4)$, so the critical numbers are $x = 0$ and $x = \\pm 2$.`,`For $x > 0$ the only one is $x = 2$.`,`$f''(x) = 12x^2 - 16$, and $f''(2) = 48 - 16 = 32 > 0$, so $x = 2$ is a local minimum.`,`Its value is $f(2) = 16 - 32 = -16$.`],mistakes:[{answer:2,tag:`extremum-location-not-value`,feedback:`2 is where the minimum happens. The question asks for the value, $f(2)$.`},{answer:0,tag:`second-derivative-test-sign`,feedback:`0 is $f(0)$, and $f''(0) = -16 < 0$ makes $x = 0$ a local maximum.`}]},{id:`shape-of-graph-5`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`$f'(c) = 0$ and $f''(c) < 0$. What does the second derivative test say?`,solutionSteps:[`$f'(c) = 0$: the graph is flat at $c$.`,`$f''(c) < 0$: the graph is concave down there, bending like the top of a hill.`,`So $f$ has a local maximum at $c$.`],options:[{text:`$f$ has a local maximum at $c$`,correct:!0},{text:`$f$ has a local minimum at $c$`,tag:`second-derivative-test-sign`,feedback:`$f'' < 0$ means concave down, like the top of a hill. That is a maximum.`},{text:`$f$ has an inflection point at $c$`,tag:`second-derivative-test-sign`,feedback:`An inflection point needs $f''$ to change sign. Here $f''(c)$ is negative, not 0.`},{text:`The test gives no conclusion`,tag:`second-derivative-test-sign`,feedback:`The test fails only when $f''(c) = 0$. A negative $f''(c)$ gives a clear answer.`}]},{id:`shape-of-graph-6`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`$f''(c) = 0$. Must $f$ have an inflection point at $c$?`,solutionSteps:[`An inflection point needs concavity to change, not just $f''(c) = 0$.`,`Counterexample: $f(x) = x^4$ has $f''(x) = 12x^2$, so $f''(0) = 0$.`,`But $12x^2 \\ge 0$ on both sides of 0, so the graph is concave up on both sides.`,`So no: there is no inflection point at 0.`],options:[{text:`No: concavity must change, and $f(x) = x^4$ at 0 is concave up on both sides`,correct:!0},{text:`Yes, always`,tag:`inflection-needs-sign-change`,feedback:`$f(x) = x^4$ has $f''(0) = 0$ but is concave up on both sides of 0. The sign of $f''$ has to change.`},{text:`Only if $f'(c) = 0$ too`,tag:`inflection-needs-sign-change`,feedback:`$f'(c)$ does not decide this. What matters is whether $f''$ changes sign at $c$.`},{text:`No, $f$ has a local maximum there instead`,tag:`inflection-needs-sign-change`,feedback:`$f''(c) = 0$ says nothing about a maximum by itself. The point is that concavity may not change.`}]}]},{id:`lhospitals-rule`,title:`L'Hospital's rule`,objective:`Evaluate limits of the forms 0/0 and infinity/infinity by differentiating the top and bottom.`,prerequisites:[],source:{title:`OpenStax Calculus Volume 1`,section:`4.8 L'Hôpital's Rule`,url:`https://openstax.org/books/calculus-volume-1/pages/4-8-lhopitals-rule`},status:`unverified`,explanation:[`If $\\lim \\frac{f(x)}{g(x)}$ has the form $\\frac{0}{0}$ or $\\frac{\\infty}{\\infty}$, then $\\lim \\frac{f(x)}{g(x)} = \\lim \\frac{f'(x)}{g'(x)}$, when the right side exists.`,`Differentiate the top and the bottom separately. This is not the quotient rule.`,`If the new limit is still $\\frac{0}{0}$ or $\\frac{\\infty}{\\infty}$, apply the rule again.`,`Other forms, such as $0 \\cdot \\infty$, must be rewritten as a fraction first: $x \\ln x = \\frac{\\ln x}{1/x}$.`],takeaways:[`Check the form first: only $\\frac{0}{0}$ or $\\frac{\\infty}{\\infty}$.`,`Top over bottom: $\\frac{f'}{g'}$, not the quotient rule.`,`Rewrite $0 \\cdot \\infty$ as a fraction before using the rule.`],example:{problem:`Find $\\lim_{x \\to 0} \\frac{\\sin x}{x}$.`,steps:[`At $x = 0$ the form is $\\frac{0}{0}$, so the rule applies.`,`$\\lim_{x \\to 0} \\frac{\\cos x}{1} = \\cos 0 = 1$.`]},questions:[{id:`lhospitals-rule-1`,level:1,kind:`numeric`,status:`unverified`,prompt:`Find $\\lim_{x \\to 0} \\frac{e^x - 1}{x}$.`,answer:1,limit:{of:`(e^x - 1) / x`,at:0},hint:`The form is $\\frac{0}{0}$. Differentiate the top and the bottom.`,solutionSteps:[`Substitute $x = 0$: $\\frac{e^0 - 1}{0} = \\frac{0}{0}$, so L'Hospital's rule applies.`,`Differentiate the top and the bottom separately: $\\frac{e^x}{1}$.`,`Substitute again: $e^0 = 1$.`],mistakes:[{answer:0,tag:`zero-over-zero-is-zero`,feedback:`$\\frac{0}{0}$ is not 0; it is undetermined. Differentiate the top and bottom to find the limit.`}]},{id:`lhospitals-rule-2`,level:1,kind:`multiple-choice`,status:`unverified`,prompt:`When can L'Hospital's rule be applied to $\\lim \\frac{f(x)}{g(x)}$ directly?`,solutionSteps:[`The rule replaces $\\frac{f}{g}$ with $\\frac{f'}{g'}$, which is only valid for indeterminate quotients.`,`Those are the forms $\\frac{0}{0}$ and $\\frac{\\infty}{\\infty}$.`,`Other forms, like $0 \\cdot \\infty$, must be rewritten as a fraction first.`],options:[{text:`When the form is $\\frac{0}{0}$ or $\\frac{\\infty}{\\infty}$`,correct:!0},{text:`For any limit of a fraction`,tag:`lhospital-wrong-form`,feedback:`For other forms it gives wrong answers. $\\lim_{x \\to 0} \\frac{x + 1}{x + 2} = \\frac{1}{2}$, but the rule would give 1.`},{text:`Whenever the bottom approaches 0`,tag:`lhospital-wrong-form`,feedback:`The top must approach 0 too. $\\frac{1}{0}$ forms do not use the rule.`},{text:`Whenever the top approaches 0`,tag:`lhospital-wrong-form`,feedback:`The bottom must approach 0 too. $\\frac{0}{5}$ is simply 0.`}]},{id:`lhospitals-rule-3`,level:2,kind:`numeric`,status:`unverified`,prompt:`Find $\\lim_{x \\to 2} \\frac{x^2 - 4}{x - 2}$.`,answer:4,limit:{of:`(x^2 - 4) / (x - 2)`,at:2},hint:`At $x = 2$ the form is $\\frac{0}{0}$. The derivatives are $2x$ and $1$.`,solutionSteps:[`Substitute $x = 2$: $\\frac{4 - 4}{2 - 2} = \\frac{0}{0}$.`,`Differentiate the top and the bottom: $\\frac{2x}{1}$.`,`Substitute again: $2(2) = 4$.`,`Factoring works too: $\\frac{(x - 2)(x + 2)}{x - 2} = x + 2 \\to 4$.`],mistakes:[{answer:0,tag:`zero-over-zero-is-zero`,feedback:`$\\frac{0}{0}$ is not 0; it is undetermined. Differentiate the top and bottom to find the limit.`},{answer:2,tag:`lhospital-evaluate`,feedback:`After differentiating you get $\\frac{2x}{1}$. Evaluate it at $x = 2$: $\\frac{4}{1}$.`}]},{id:`lhospitals-rule-4`,level:2,kind:`numeric`,status:`unverified`,prompt:`Find $\\lim_{x \\to 0} \\frac{1 - \\cos x}{x^2}$.`,answer:.5,limit:{of:`(1 - cos(x)) / x^2`,at:0},hint:`After one round you get $\\frac{\\sin x}{2x}$, which is still $\\frac{0}{0}$. Apply the rule again.`,solutionSteps:[`Substitute $x = 0$: $\\frac{1 - 1}{0} = \\frac{0}{0}$.`,`Apply the rule: $\\frac{\\sin x}{2x}$, which is still $\\frac{0}{0}$ at 0.`,`Apply it again: $\\frac{\\cos x}{2}$.`,`Substitute: $\\frac{\\cos 0}{2} = \\frac{1}{2}$.`],mistakes:[{answer:0,tag:`lhospital-stopped-early`,feedback:`$\\frac{\\sin x}{2x}$ is still $\\frac{0}{0}$ at 0, not 0. Apply the rule a second time.`},{answer:1,tag:`lhospital-dropped-constant`,feedback:`The second derivative of $x^2$ is 2, so the limit is $\\frac{\\cos 0}{2}$.`}]},{id:`lhospitals-rule-5`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`To find $\\lim_{x \\to 0^+} x \\ln x$ with L'Hospital's rule, what should you do first?`,solutionSteps:[`As $x \\to 0^+$, $x \\to 0$ and $\\ln x \\to -\\infty$: the form is $0 \\cdot (-\\infty)$, not a fraction.`,`Rewrite the product as a quotient: $x \\ln x = \\frac{\\ln x}{1/x}$, which has the form $\\frac{-\\infty}{\\infty}$.`,`Now the rule applies: $\\frac{1/x}{-1/x^2} = -x \\to 0$.`],options:[{text:`Rewrite it as $\\frac{\\ln x}{1/x}$`,correct:!0},{text:`Differentiate $x \\ln x$`,tag:`lhospital-rewrite`,feedback:`L'Hospital's rule applies to fractions. Differentiating the product gives its slope, not the limit.`},{text:`Nothing: $x \\to 0$, so the limit is 0`,tag:`lhospital-rewrite`,feedback:`$\\ln x \\to -\\infty$ at the same time, so $0 \\cdot \\infty$ could be anything until it is worked out.`},{text:`Apply the rule to $\\frac{x}{\\ln x}$`,tag:`lhospital-rewrite`,feedback:`$\\frac{x}{\\ln x}$ is a different expression from $x \\ln x$. Move one factor into the bottom as its reciprocal.`}]},{id:`lhospitals-rule-6`,level:3,kind:`numeric`,status:`unverified`,prompt:`Find $\\lim_{x \\to \\infty} \\frac{3x^2 + 1}{5x^2 - x}$.`,answer:.6,limit:{of:`(3x^2 + 1) / (5x^2 - x)`,at:`infinity`},hint:`The form is $\\frac{\\infty}{\\infty}$. Apply the rule twice, or divide top and bottom by $x^2$.`,solutionSteps:[`As $x \\to \\infty$ both top and bottom go to $\\infty$: the form is $\\frac{\\infty}{\\infty}$.`,`Apply the rule: $\\frac{6x}{10x - 1}$, still $\\frac{\\infty}{\\infty}$.`,`Apply it again: $\\frac{6}{10}$.`,`The limit is $\\frac{3}{5} = 0.6$.`],mistakes:[{answer:0,tag:`infinity-over-infinity`,feedback:`$\\frac{\\infty}{\\infty}$ is undetermined, not 0. Both parts grow like $x^2$, so compare their leading terms.`},{answer:1,tag:`infinity-over-infinity`,feedback:`$\\frac{\\infty}{\\infty}$ is undetermined, not 1. Apply the rule until it is no longer indeterminate.`}]}]},{id:`optimization`,title:`Optimization problems`,objective:`Turn a word problem into a function of one variable and find its largest or smallest value.`,prerequisites:[`max-min`],source:{title:`OpenStax Calculus Volume 1`,section:`4.7 Applied Optimization Problems`,url:`https://openstax.org/books/calculus-volume-1/pages/4-7-applied-optimization-problems`},status:`unverified`,explanation:[`Name the quantity to make largest or smallest, and write it as a formula.`,`Use the constraint (the fixed perimeter, sum or amount of material) to rewrite it as a function of one variable, and find the interval that variable can take.`,`Find the critical numbers, then confirm which one gives the maximum or minimum: compare with the endpoints, or use the first or second derivative test.`,`Answer the question that was asked. A problem may want the dimensions, the variable or the best value itself.`],takeaways:[`Quantity, constraint, one variable, interval.`,`Critical numbers are candidates; confirm with endpoints or a derivative test.`,`Reread what the question asks for.`],example:{problem:`A rectangle has a perimeter of 100 m. What is its largest possible area?`,steps:[`With width $x$, the length is $50 - x$, so the area is $A(x) = x(50 - x)$ for $0 \\le x \\le 50$.`,`$A'(x) = 50 - 2x = 0$ gives $x = 25$.`,`$A(0) = A(50) = 0$ and $A(25) = 625$, so the largest area is 625 m², a 25 m square.`]},questions:[{id:`optimization-1`,level:1,kind:`multiple-choice`,status:`unverified`,prompt:`In an optimization problem, what comes before taking a derivative?`,solutionSteps:[`Name the quantity to make largest or smallest, and the variables it depends on.`,`Use the constraint to write it in terms of a single variable.`,`Only then take the derivative and find the critical numbers.`],options:[{text:`Write the quantity to optimize as a function of one variable`,correct:!0},{text:`Set the quantity equal to 0`,tag:`optimization-setup`,feedback:`The derivative is set to 0 later. First the quantity needs to be a function of one variable.`},{text:`Evaluate the quantity at the endpoints only`,tag:`optimization-setup`,feedback:`Endpoints are checked at the end, together with the critical numbers.`},{text:`Take the derivative with respect to every variable at once`,tag:`optimization-setup`,feedback:`In Calculus I you first use the constraint to get down to one variable, then differentiate.`}]},{id:`optimization-2`,level:1,kind:`numeric`,status:`unverified`,prompt:`Two positive numbers add up to 20. What is the largest their product can be?`,answer:100,extremum:{of:`x * (20 - x)`,from:0,to:20,kind:`max`,report:`value`},hint:`If one number is $x$, the other is $20 - x$. Maximize $P(x) = x(20 - x)$.`,solutionSteps:[`Call the numbers $x$ and $20 - x$, so the product is $P(x) = x(20 - x) = 20x - x^2$.`,`$P'(x) = 20 - 2x = 0$ gives $x = 10$.`,`$P''(x) = -2 < 0$, so this is a maximum.`,`Both numbers are 10, and the largest product is $10 \\cdot 10 = 100$.`],mistakes:[{answer:10,tag:`extremum-location-not-value`,feedback:`10 is each number. The question asks for the product.`}]},{id:`optimization-3`,level:2,kind:`numeric`,status:`unverified`,prompt:`A farmer has 240 m of fence for a rectangular field along a straight river. No fence is needed along the river. What is the largest area, in m², the field can have?`,answer:7200,extremum:{of:`x * (240 - 2x)`,from:0,to:120,kind:`max`,report:`value`},hint:`With two sides of length $x$ away from the river, the side along the river is $240 - 2x$.`,solutionSteps:[`Let $x$ be each side perpendicular to the river. The side along the river is $240 - 2x$.`,`Area: $A(x) = x(240 - 2x) = 240x - 2x^2$.`,`$A'(x) = 240 - 4x = 0$ gives $x = 60$, and $A''(x) = -4 < 0$, so it is a maximum.`,`The field is 60 m by 120 m, with area $60 \\cdot 120 = 7200$ m².`],mistakes:[{answer:3600,tag:`optimization-constraint`,feedback:`That fences all four sides. The river side needs no fence, so the constraint is $2x + y = 240$.`},{answer:60,tag:`extremum-location-not-value`,feedback:`60 m is the side away from the river. The question asks for the area.`}]},{id:`optimization-4`,level:2,kind:`numeric`,status:`unverified`,prompt:`An open box is made from a 12 cm by 12 cm sheet by cutting an $x$ cm square from each corner and folding up the sides. What $x$ gives the largest volume?`,answer:2,extremum:{of:`x * (12 - 2x)^2`,from:0,to:6,kind:`max`,report:`x`},hint:`The volume is $V(x) = x(12 - 2x)^2$ for $0 \\le x \\le 6$.`,solutionSteps:[`The base is $12 - 2x$ on each side and the height is $x$, so $V(x) = x(12 - 2x)^2$ for $0 \\le x \\le 6$.`,`Product rule: $V'(x) = (12 - 2x)^2 - 4x(12 - 2x) = (12 - 2x)(12 - 6x)$.`,`$V'(x) = 0$ at $x = 6$ and $x = 2$.`,`$V(0) = 0$ and $V(6) = 0$, while $V(2) = 2 \\cdot 8^2 = 128$. The maximum is at $x = 2$.`],mistakes:[{answer:6,tag:`optimization-check-candidates`,feedback:`At $x = 6$ the whole sheet is cut away and the volume is 0. Check the other critical number.`},{answer:128,tag:`extremum-location-not-value`,feedback:`128 cm³ is the largest volume. The question asks for $x$.`}]},{id:`optimization-5`,level:3,kind:`numeric`,status:`unverified`,prompt:`Find the positive $x$ of the point on $y = x^2$ closest to the point $(0, 2)$.`,answer:1.224744871391589,extremum:{of:`x^4 - 3x^2 + 4`,from:0,to:2,kind:`min`,report:`x`},hint:`Minimize the squared distance $D(x) = x^2 + (x^2 - 2)^2$; it has its minimum where the distance does.`,solutionSteps:[`A point on the curve is $(x, x^2)$. Minimize the squared distance to $(0, 2)$ instead of the distance itself.`,`$D(x) = x^2 + (x^2 - 2)^2 = x^4 - 3x^2 + 4$.`,`$D'(x) = 4x^3 - 6x = 2x(2x^2 - 3) = 0$ gives $x = 0$ or $x^2 = \\frac{3}{2}$.`,`$D(0) = 4$ but $D\\left(\\sqrt{3/2}\\right) = \\frac{9}{4} - \\frac{9}{2} + 4 = \\frac{7}{4}$, which is smaller.`,`So $x = \\sqrt{\\frac{3}{2}} \\approx 1.225$.`],mistakes:[{answer:0,tag:`optimization-check-candidates`,feedback:`At $x = 0$ the distance is 2, a local maximum of the distance. Compare it with the other critical number.`},{answer:1.4142135623730951,tag:`optimization-setup`,feedback:`$\\sqrt{2}$ is where the parabola reaches height 2. The closest point is lower, where $D'(x) = 0$.`}]},{id:`optimization-6`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`You found one critical number of the area function $A(x)$ on $[0, 50]$. How do you know it gives the maximum area?`,solutionSteps:[`A critical number is only a candidate.`,`Closed interval check: compare $A$ at the critical number with $A(0)$ and $A(50)$.`,`Or a derivative check: $A'$ changes from positive to negative there, or $A'' < 0$.`],options:[{text:`Compare $A$ there with $A(0)$ and $A(50)$, or check that $A'$ changes from + to −`,correct:!0},{text:`Every critical number is a maximum`,tag:`critical-number-not-extremum`,feedback:`A critical number can be a maximum, a minimum or neither. It needs to be checked.`},{text:`$A'(x) = 0$ means $A$ is as large as possible`,tag:`critical-number-not-extremum`,feedback:`$A' = 0$ means the graph is flat there; the bottom of a valley is flat too.`},{text:`Because the answer is a positive number`,tag:`optimization-check-candidates`,feedback:`A minimum can be positive too. Use the endpoints or a derivative test.`}]}]},{id:`newtons-method`,title:`Newton's method`,objective:`Approximate a solution of f(x) = 0 by following tangent lines.`,prerequisites:[],source:{title:`OpenStax Calculus Volume 1`,section:`4.9 Newton's Method`,url:`https://openstax.org/books/calculus-volume-1/pages/4-9-newtons-method`},status:`unverified`,explanation:[`Newton's method approximates a solution of $f(x) = 0$. Start with a guess $x_0$, follow the tangent line at $x_0$ to where it crosses the $x$-axis, and use that crossing as the next guess.`,`The formula: $x_{n+1} = x_n - \\frac{f(x_n)}{f'(x_n)}$.`,`Repeat until the guesses stop changing in the digits you need. Near a root, the number of correct digits roughly doubles with each step.`,`It can fail: if $f'(x_n) = 0$ the tangent line is flat and never crosses the axis, and a poor first guess can lead to a different root or none.`],takeaways:[`$x_{n+1} = x_n - \\frac{f(x_n)}{f'(x_n)}$.`,`Each step follows a tangent line to the $x$-axis.`,`A flat tangent ($f' = 0$) breaks the method.`],example:{problem:`Approximate $\\sqrt{2}$ with $f(x) = x^2 - 2$ and $x_0 = 1$.`,steps:[`$f'(x) = 2x$. Step 1: $x_1 = 1 - \\frac{1 - 2}{2} = 1.5$.`,`Step 2: $x_2 = 1.5 - \\frac{2.25 - 2}{3} \\approx 1.4167$. The true value is $1.4142\\ldots$`]},questions:[{id:`newtons-method-1`,level:1,kind:`multiple-choice`,status:`unverified`,prompt:`Which formula gives the next guess in Newton's method?`,solutionSteps:[`The tangent line at $x_n$ is $y = f(x_n) + f'(x_n)(x - x_n)$.`,`Set $y = 0$ and solve for $x$: $x = x_n - \\frac{f(x_n)}{f'(x_n)}$.`],options:[{text:`$x_{n+1} = x_n - \\frac{f(x_n)}{f'(x_n)}$`,correct:!0},{text:`$x_{n+1} = x_n + \\frac{f(x_n)}{f'(x_n)}$`,tag:`newton-sign`,feedback:`The step is subtracted. Solving the tangent line for $y = 0$ gives $x_n - \\frac{f}{f'}$.`},{text:`$x_{n+1} = x_n - \\frac{f'(x_n)}{f(x_n)}$`,tag:`newton-flipped`,feedback:`The function value goes on top: the step is height divided by slope.`},{text:`$x_{n+1} = x_n - f(x_n) f'(x_n)$`,tag:`newton-flipped`,feedback:`The step is the height divided by the slope, not multiplied.`}]},{id:`newtons-method-2`,level:1,kind:`numeric`,status:`unverified`,prompt:`Use Newton's method on $f(x) = x^2 - 5$ with $x_0 = 2$. Find $x_1$.`,answer:2.25,newton:{of:`x^2 - 5`,start:2,steps:1},hint:`$f(2) = -1$ and $f'(2) = 4$. Then $x_1 = 2 - \\frac{-1}{4}$.`,solutionSteps:[`$f(2) = 4 - 5 = -1$, and $f'(x) = 2x$ gives $f'(2) = 4$.`,`$x_1 = 2 - \\frac{-1}{4} = 2.25$.`,`The true root is $\\sqrt{5} \\approx 2.236$.`],mistakes:[{answer:1.75,tag:`newton-sign`,feedback:`$f(2)$ is negative, so subtracting $\\frac{-1}{4}$ adds: $2 + 0.25$.`},{answer:6,tag:`newton-flipped`,feedback:`The step is $\\frac{f}{f'} = \\frac{-1}{4}$, not $\\frac{f'}{f}$.`}]},{id:`newtons-method-3`,level:2,kind:`numeric`,status:`unverified`,prompt:`Use Newton's method on $f(x) = x^3 - 2x - 5$ with $x_0 = 2$. Find $x_2$, to four decimal places.`,answer:2.0945681,newton:{of:`x^3 - 2x - 5`,start:2,steps:2},hint:`$f'(x) = 3x^2 - 2$. The first step gives $x_1 = 2.1$; apply the formula once more.`,solutionSteps:[`$f'(x) = 3x^2 - 2$. Step 1: $f(2) = -1$, $f'(2) = 10$, so $x_1 = 2 + 0.1 = 2.1$.`,`Step 2: $f(2.1) = 0.061$, $f'(2.1) = 11.23$, so $x_2 = 2.1 - \\frac{0.061}{11.23} \\approx 2.0946$.`],mistakes:[{answer:2.1,tag:`newton-one-step`,feedback:`That is $x_1$. Apply the formula once more from $x_1 = 2.1$.`},{answer:1.9,tag:`newton-sign`,feedback:`$f(2) = -1$ is negative, so the first step moves right, to 2.1.`}]},{id:`newtons-method-4`,level:2,kind:`numeric`,status:`unverified`,prompt:`Use Newton's method on $f(x) = x^3 - 10$ with $x_0 = 2$ to approximate $\\sqrt[3]{10}$. Find $x_1$, to four decimal places.`,answer:2.1666666666666665,newton:{of:`x^3 - 10`,start:2,steps:1},hint:`$f(2) = -2$ and $f'(2) = 3 \\cdot 2^2 = 12$.`,solutionSteps:[`$f(2) = 8 - 10 = -2$, and $f'(x) = 3x^2$ gives $f'(2) = 12$.`,`$x_1 = 2 - \\frac{-2}{12} = 2 + \\frac{1}{6} \\approx 2.1667$.`,`The true value is $2.1544\\ldots$`],mistakes:[{answer:1.8333333333333333,tag:`newton-sign`,feedback:`$f(2)$ is negative, so the step moves right: $2 + \\frac{1}{6}$.`},{answer:2.5,tag:`newton-derivative`,feedback:`$f'(2) = 3 \\cdot 2^2 = 12$, not 4.`}]},{id:`newtons-method-5`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`Why does Newton's method fail for $f(x) = x^2 - 4$ with $x_0 = 0$?`,solutionSteps:[`$f'(0) = 0$, so the tangent line at $x_0 = 0$ is horizontal.`,`A horizontal line never crosses the $x$-axis, and the formula divides by $f'(0) = 0$.`,`Any other starting guess works here: positive guesses find 2 and negative ones find $-2$.`],options:[{text:`$f'(0) = 0$, so the tangent line is flat and never crosses the $x$-axis`,correct:!0},{text:`0 is too far from the roots`,tag:`newton-flat-tangent`,feedback:`Distance is not the problem: $x_0 = 10$ works. The tangent at 0 is flat.`},{text:`The function has two roots, so the method cannot choose`,tag:`newton-flat-tangent`,feedback:`The method follows the tangent to one root. Here there is no crossing at all, because $f'(0) = 0$.`},{text:`$f(0)$ is negative`,tag:`newton-flat-tangent`,feedback:`A negative $f(x_0)$ is fine, as in $x^2 - 5$ from 2. The trouble is dividing by $f'(0) = 0$.`}]},{id:`newtons-method-6`,level:3,kind:`numeric`,status:`unverified`,prompt:`For $f(x) = x^2 - a$, Newton's method becomes $x_{n+1} = \\frac{1}{2}\\left(x_n + \\frac{a}{x_n}\\right)$. With $a = 9$ and $x_0 = 1$, find $x_2$.`,answer:3.4,newton:{of:`x^2 - 9`,start:1,steps:2},hint:`Apply the formula twice: first from $x_0 = 1$, then from $x_1$.`,solutionSteps:[`Step 1: $x_1 = \\frac{1}{2}(1 + 9) = 5$.`,`Step 2: $x_2 = \\frac{1}{2}\\left(5 + \\frac{9}{5}\\right) = \\frac{1}{2}(6.8) = 3.4$.`,`It is closing in on $\\sqrt{9} = 3$.`],mistakes:[{answer:5,tag:`newton-one-step`,feedback:`That is $x_1$. Apply the formula once more from $x_1 = 5$.`},{answer:3,tag:`newton-exact-root`,feedback:`3 is the root it is approaching, but after two steps the guess is still 3.4.`}]}]}]},n={id:`applications-of-integrals`,courseId:`calculus-1`,courseTitle:`Calculus I`,title:`Applications of integrals`,concepts:[{id:`area-between-curves`,title:`Area between curves`,objective:`Find the area of a region between two curves by integrating the top curve minus the bottom curve.`,prerequisites:[],source:{title:`OpenStax Calculus Volume 1`,section:`6.1 Areas between Curves`,url:`https://openstax.org/books/calculus-volume-1/pages/6-1-areas-between-curves`},status:`unverified`,explanation:[`If $f(x) \\ge g(x)$ for every $x$ in $[a, b]$, the area of the region between the two curves is $\\int_a^b \\left(f(x) - g(x)\\right)dx$: the top curve minus the bottom curve.`,`When the interval is not given, the limits are where the curves meet. Set $f(x) = g(x)$ and solve for $x$.`,`To tell which curve is on top, test one $x$ between the limits. If the curves cross inside the interval, split the integral at the crossing so each piece is top minus bottom.`,`Some regions are easier to describe sideways. Then integrate with respect to $y$: the right curve minus the left curve, with $y$-limits.`],takeaways:[`Area $= \\int_a^b (\\text{top} - \\text{bottom})\\,dx$`,`The limits are the $x$-values where the curves intersect.`,`Where the curves cross, split the integral so the area never cancels.`],example:{problem:`Find the area between $y = x$ and $y = x^2$.`,steps:[`Find where they meet: $x = x^2$ gives $x = 0$ and $x = 1$.`,`Test $x = \\frac{1}{2}$: $\\frac{1}{2} > \\frac{1}{4}$, so $y = x$ is on top.`,`Area $= \\int_0^1 (x - x^2)\\,dx = \\frac{1}{2} - \\frac{1}{3} = \\frac{1}{6}$.`]},questions:[{id:`area-between-curves-1`,level:1,kind:`numeric`,status:`unverified`,prompt:`Find the area of the region between $y = x + 3$ and $y = x$ from $x = 0$ to $x = 2$.`,answer:6,integral:{of:`(x + 3) - x`,from:0,to:2},hint:`Integrate the top curve minus the bottom curve. What is $(x + 3) - x$?`,solutionSteps:[`$x + 3$ is above $x$ everywhere, so the top curve is $y = x + 3$.`,`Area $= \\int_0^2 \\left((x + 3) - x\\right)dx = \\int_0^2 3\\,dx$.`,`$3 \\cdot 2 = 6$.`],mistakes:[{answer:8,tag:`area-between-top-only`,feedback:`8 is the area under the top curve alone. Subtract the bottom curve before integrating.`}]},{id:`area-between-curves-2`,level:1,kind:`multiple-choice`,status:`unverified`,prompt:`On $[a, b]$, $f(x) \\ge g(x)$. Which integral gives the area of the region between the two curves?`,solutionSteps:[`The height of a thin vertical strip at $x$ is top minus bottom: $f(x) - g(x)$.`,`Add up the strips from $a$ to $b$.`,`Area $= \\int_a^b \\left(f(x) - g(x)\\right)dx$.`],options:[{text:`$\\int_a^b \\left(f(x) - g(x)\\right)dx$`,correct:!0},{text:`$\\int_a^b \\left(g(x) - f(x)\\right)dx$`,tag:`area-between-bottom-minus-top`,feedback:`That is bottom minus top, which gives a negative number. Subtract the lower curve from the upper one.`},{text:`$\\int_a^b f(x)\\,g(x)\\,dx$`,tag:`area-between-meaning`,feedback:`The height of each thin rectangle is the gap between the curves, $f(x) - g(x)$, not their product.`},{text:`$\\int_a^b f(x)\\,dx + \\int_a^b g(x)\\,dx$`,tag:`area-between-meaning`,feedback:`Adding counts the area under both curves. The region between them is the area under $f$ minus the area under $g$.`}]},{id:`area-between-curves-3`,level:2,kind:`numeric`,status:`unverified`,prompt:`Find the area of the region between $y = x^2$ and $y = 2x$.`,answer:1.3333333333333333,integral:{of:`2x - x^2`,from:0,to:2},hint:`Solve $x^2 = 2x$ for the limits, then test a point between them to see which curve is on top.`,solutionSteps:[`Find where the curves meet: $x^2 = 2x$ gives $x(x - 2) = 0$, so $x = 0$ and $x = 2$.`,`Test a point between them: at $x = 1$, $2x = 2$ and $x^2 = 1$, so $y = 2x$ is on top.`,`Area $= \\int_0^2 (2x - x^2)\\,dx = \\left(x^2 - \\frac{x^3}{3}\\right)\\Big|_0^2$.`,`$4 - \\frac{8}{3} = \\frac{4}{3}$.`],mistakes:[{answer:-1.3333333333333333,tag:`area-between-bottom-minus-top`,feedback:`An area cannot be negative. Between $x = 0$ and $x = 2$, $2x$ is on top, so integrate $2x - x^2$.`},{answer:4,tag:`area-between-top-only`,feedback:`4 is the area under $y = 2x$ alone. Subtract the area under $y = x^2$.`}]},{id:`area-between-curves-4`,level:2,kind:`numeric`,status:`unverified`,prompt:`Find the area of the region between $y = 4 - x^2$ and $y = x + 2$.`,answer:4.5,integral:{of:`(4 - x^2) - (x + 2)`,from:-2,to:1},hint:`Setting $4 - x^2 = x + 2$ gives $x^2 + x - 2 = 0$. Factor it for the limits.`,solutionSteps:[`Find where the curves meet: $4 - x^2 = x + 2$ gives $x^2 + x - 2 = (x + 2)(x - 1) = 0$, so $x = -2$ and $x = 1$.`,`Test $x = 0$: the parabola gives 4 and the line gives 2, so the parabola is on top.`,`Area $= \\int_{-2}^{1} \\left((4 - x^2) - (x + 2)\\right)dx = \\int_{-2}^{1} (2 - x - x^2)\\,dx$.`,`$\\left(2x - \\frac{x^2}{2} - \\frac{x^3}{3}\\right)\\Big|_{-2}^{1} = \\frac{7}{6} - \\left(-\\frac{10}{3}\\right) = \\frac{9}{2}$.`],mistakes:[{answer:-4.5,tag:`area-between-bottom-minus-top`,feedback:`An area cannot be negative. Test $x = 0$: $4 - 0 = 4$ is above $0 + 2 = 2$, so the parabola is on top.`}]},{id:`area-between-curves-5`,level:3,kind:`numeric`,status:`unverified`,prompt:`Find the area of the region between $y = x$ and $y = x^3$ from $x = -1$ to $x = 1$.`,answer:.5,integral:{of:`abs(x - x^3)`,from:-1,to:1},hint:`The curves cross at $x = 0$. Which one is on top on $[-1, 0]$, and which on $[0, 1]$?`,solutionSteps:[`The curves meet at $x = -1$, $0$ and $1$, so the top curve can switch at 0.`,`On $[0, 1]$, $x \\ge x^3$. On $[-1, 0]$, $x^3 \\ge x$.`,`The two pieces are mirror images, so the area is $2\\int_0^1 (x - x^3)\\,dx$.`,`$2\\left(\\frac{1}{2} - \\frac{1}{4}\\right) = 2 \\cdot \\frac{1}{4} = \\frac{1}{2}$.`],mistakes:[{answer:0,tag:`area-between-crossing`,feedback:`The two pieces cancelled. The curves cross at $x = 0$, so split the integral there and use top minus bottom on each piece.`},{answer:.25,tag:`area-between-half-region`,feedback:`That is only the piece on $[0, 1]$. The piece on $[-1, 0]$ has the same area.`}]},{id:`area-between-curves-6`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`The region between $x = y^2$ and $x = y + 2$ is easiest to measure sideways. Which integral gives its area?`,solutionSteps:[`Both curves give $x$ in terms of $y$, so slice horizontally and integrate in $y$.`,`They meet where $y^2 = y + 2$, which gives $(y - 2)(y + 1) = 0$: $y = -1$ and $y = 2$.`,`At $y = 0$ the line gives $x = 2$ and the parabola gives $x = 0$, so the line is on the right.`,`Right minus left: $\\int_{-1}^{2} \\left((y + 2) - y^2\\right)dy$.`],options:[{text:`$\\int_{-1}^{2} \\left((y + 2) - y^2\\right)dy$`,correct:!0},{text:`$\\int_{-1}^{2} \\left(y^2 - (y + 2)\\right)dy$`,tag:`area-between-bottom-minus-top`,feedback:`Integrating in $y$, subtract left from right. At $y = 0$, $x = y + 2 = 2$ is to the right of $x = y^2 = 0$.`},{text:`$\\int_{-2}^{1} \\left((y + 2) - y^2\\right)dy$`,tag:`area-between-limits`,feedback:`Solve $y^2 = y + 2$: it factors as $(y - 2)(y + 1) = 0$, so the limits are $-1$ and $2$.`},{text:`$\\int_{-1}^{2} \\left((y + 2) - y^2\\right)dx$`,tag:`area-between-variable`,feedback:`The curves are written in terms of $y$ and the limits are $y$-values, so the integral is with respect to $y$.`}]}]},{id:`volumes-disks-washers`,title:`Volumes by disks and washers`,objective:`Find the volume of a solid of revolution by slicing it into disks or washers.`,prerequisites:[`area-between-curves`],source:{title:`OpenStax Calculus Volume 1`,section:`6.2 Determining Volumes by Slicing`,url:`https://openstax.org/books/calculus-volume-1/pages/6-2-determining-volumes-by-slicing`},status:`unverified`,explanation:[`Spin a region around an axis and it sweeps out a solid. Slice the solid perpendicular to the axis: each slice is a thin disk, with volume $\\pi r^2$ times its thickness.`,`Disk method: rotating the region under $y = f(x)$ on $[a, b]$ about the $x$-axis gives $V = \\int_a^b \\pi\\left[f(x)\\right]^2 dx$. The radius of each disk is the height of the curve.`,`Washer method: if the region has a gap next to the axis, each slice is a disk with a hole. With outer radius $R(x)$ and inner radius $r(x)$, $V = \\int_a^b \\pi\\left(R(x)^2 - r(x)^2\\right)dx$. Square each radius first, then subtract.`,`Rotating about another horizontal line, such as $y = -1$, changes the radii: each one is the distance from that line to the curve.`],takeaways:[`Disk: $V = \\int_a^b \\pi\\left[f(x)\\right]^2 dx$`,`Washer: $V = \\int_a^b \\pi\\left(R^2 - r^2\\right)dx$, never $\\pi(R - r)^2$.`,`A radius is a distance from the axis of rotation.`],example:{problem:`Rotate the region under $y = \\sqrt{x}$ for $0 \\le x \\le 4$ about the $x$-axis. Find the volume.`,steps:[`Each slice is a disk of radius $\\sqrt{x}$, so its area is $\\pi(\\sqrt{x})^2 = \\pi x$.`,`$V = \\int_0^4 \\pi x\\,dx = \\pi \\cdot \\frac{x^2}{2}\\Big|_0^4 = 8\\pi$.`]},questions:[{id:`volumes-disks-washers-1`,level:1,kind:`numeric`,status:`unverified`,prompt:`Rotate the region under $y = x$ for $0 \\le x \\le 3$ about the $x$-axis. Find the volume. Answer in terms of pi, such as 8pi/3.`,answer:28.274333882308138,integral:{of:`pi * x^2`,from:0,to:3},hint:`Each slice is a disk of radius $x$. Integrate $\\pi x^2$ from 0 to 3.`,solutionSteps:[`Each slice at $x$ is a disk of radius $y = x$, so its area is $\\pi x^2$.`,`$V = \\int_0^3 \\pi x^2\\,dx = \\pi \\cdot \\frac{x^3}{3}\\Big|_0^3$.`,`$\\pi \\cdot \\frac{27}{3} = 9\\pi$. The solid is a cone.`],mistakes:[{answer:9,tag:`volume-forgot-pi`,feedback:`Each disk's area is $\\pi r^2$, so the volume has a factor of $\\pi$.`},{answer:14.137166941154069,tag:`volume-radius-not-squared`,feedback:`That integrates $\\pi x$. The area of a disk is $\\pi r^2$, so square the radius: $\\pi x^2$.`}]},{id:`volumes-disks-washers-2`,level:1,kind:`multiple-choice`,status:`unverified`,prompt:`The region under $y = f(x)$ is rotated about the $x$-axis. What is the radius of the disk-shaped slice at $x$?`,solutionSteps:[`The slice at $x$ is a disk centered on the $x$-axis.`,`It reaches from the axis up to the curve.`,`So its radius is the height of the curve: $f(x)$.`],options:[{text:`$f(x)$`,correct:!0},{text:`$x$`,tag:`volume-radius`,feedback:`$x$ is where the slice is along the axis. The radius is how far the curve is from the axis: $f(x)$.`},{text:`$\\pi f(x)$`,tag:`volume-radius`,feedback:`The $\\pi$ belongs to the area of the disk, $\\pi r^2$, not to the radius.`},{text:`$\\left[f(x)\\right]^2$`,tag:`volume-radius`,feedback:`That is the radius squared, which appears in the area $\\pi r^2$. The radius itself is $f(x)$.`}]},{id:`volumes-disks-washers-3`,level:2,kind:`numeric`,status:`unverified`,prompt:`Rotate the region under $y = x^2$ for $0 \\le x \\le 2$ about the $x$-axis. Find the volume. Answer in terms of pi.`,answer:20.106192982974676,integral:{of:`pi * (x^2)^2`,from:0,to:2},hint:`The radius is $x^2$, so each disk has area $\\pi (x^2)^2 = \\pi x^4$.`,solutionSteps:[`Each slice at $x$ is a disk of radius $x^2$, so its area is $\\pi (x^2)^2 = \\pi x^4$.`,`$V = \\int_0^2 \\pi x^4\\,dx = \\pi \\cdot \\frac{x^5}{5}\\Big|_0^2$.`,`$\\pi \\cdot \\frac{32}{5} = \\frac{32\\pi}{5}$.`],mistakes:[{answer:8.377580409572781,tag:`volume-radius-not-squared`,feedback:`That integrates $\\pi x^2$, the radius without squaring. The radius is $x^2$, so the area is $\\pi x^4$.`},{answer:6.4,tag:`volume-forgot-pi`,feedback:`Each disk's area is $\\pi r^2$, so the volume has a factor of $\\pi$.`}]},{id:`volumes-disks-washers-4`,level:2,kind:`numeric`,status:`unverified`,prompt:`Rotate the region between $y = x$ and $y = x^2$ (for $0 \\le x \\le 1$) about the $x$-axis. Find the volume. Answer in terms of pi.`,answer:.41887902047863906,integral:{of:`pi * (x^2 - x^4)`,from:0,to:1},hint:`Each slice is a washer. The outer radius is $x$ and the inner radius is $x^2$.`,solutionSteps:[`On $[0, 1]$, $x \\ge x^2$, so each slice is a washer: outer radius $x$, inner radius $x^2$.`,`Washer area: $\\pi\\left(x^2 - (x^2)^2\\right) = \\pi(x^2 - x^4)$.`,`$V = \\int_0^1 \\pi(x^2 - x^4)\\,dx = \\pi\\left(\\frac{1}{3} - \\frac{1}{5}\\right)$.`,`$\\frac{2\\pi}{15}$.`],mistakes:[{answer:.10471975511965977,tag:`washer-squared-difference`,feedback:`That squares the difference, $\\pi(x - x^2)^2$. Square each radius first, then subtract: $\\pi\\left(x^2 - x^4\\right)$.`},{answer:1.0471975511965976,tag:`washer-outer-only`,feedback:`That is the volume using the outer radius alone. Subtract the hole made by the inner radius $x^2$.`}]},{id:`volumes-disks-washers-5`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`The region under $y = \\sqrt{x}$ for $0 \\le x \\le 4$ is rotated about the line $y = -1$. Which integral gives the volume?`,solutionSteps:[`The axis $y = -1$ is 1 below the $x$-axis, so the region does not touch it and each slice is a washer.`,`Outer radius: from $y = -1$ up to the curve, $\\sqrt{x} - (-1) = \\sqrt{x} + 1$.`,`Inner radius: from $y = -1$ up to the $x$-axis, $1$.`,`$V = \\int_0^4 \\pi\\left[(\\sqrt{x} + 1)^2 - 1^2\\right]dx$.`],options:[{text:`$\\int_0^4 \\pi\\left[(\\sqrt{x} + 1)^2 - 1^2\\right]dx$`,correct:!0},{text:`$\\int_0^4 \\pi\\left(\\sqrt{x}\\right)^2 dx$`,tag:`volume-axis-shift`,feedback:`That rotates about the $x$-axis. Measured from $y = -1$, the curve is $\\sqrt{x} + 1$ away, and there is a hole of radius 1.`},{text:`$\\int_0^4 \\pi\\left(\\sqrt{x} + 1\\right)^2 dx$`,tag:`washer-outer-only`,feedback:`The region does not touch the line $y = -1$, so there is a hole. Subtract $\\pi \\cdot 1^2$ for it.`},{text:`$\\int_0^4 \\pi\\left[(\\sqrt{x} - 1)^2 - 1^2\\right]dx$`,tag:`volume-axis-shift`,feedback:`The distance from $y = -1$ up to the curve is $\\sqrt{x} - (-1) = \\sqrt{x} + 1$.`}]},{id:`volumes-disks-washers-6`,level:3,kind:`numeric`,status:`unverified`,prompt:`The region under $y = \\sqrt{x}$ for $0 \\le x \\le 4$ is rotated about the line $y = -1$. Find the volume. Answer in terms of pi.`,answer:58.64306287664799,integral:{of:`pi * ((sqrt(x) + 1)^2 - 1)`,from:0,to:4},hint:`Each slice is a washer with outer radius $\\sqrt{x} + 1$ and inner radius 1.`,solutionSteps:[`Washers: outer radius $\\sqrt{x} + 1$, inner radius $1$, so $V = \\int_0^4 \\pi\\left[(\\sqrt{x} + 1)^2 - 1\\right]dx$.`,`Expand: $(\\sqrt{x} + 1)^2 - 1 = x + 2\\sqrt{x}$.`,`$\\int_0^4 \\left(x + 2x^{1/2}\\right)dx = \\left(\\frac{x^2}{2} + \\frac{4}{3}x^{3/2}\\right)\\Big|_0^4 = 8 + \\frac{32}{3}$.`,`$V = \\pi \\cdot \\frac{56}{3} = \\frac{56\\pi}{3}$.`],mistakes:[{answer:25.132741228718345,tag:`volume-axis-shift`,feedback:`$8\\pi$ is the volume about the $x$-axis. About $y = -1$, both radii grow by 1.`},{answer:71.20943348136863,tag:`washer-outer-only`,feedback:`That leaves out the hole. Subtract $\\pi \\cdot 1^2$ for the inner radius.`}]}]},{id:`cylindrical-shells`,title:`Volumes by cylindrical shells`,objective:`Find the volume of a solid of revolution about a vertical axis with cylindrical shells.`,prerequisites:[`volumes-disks-washers`],source:{title:`OpenStax Calculus Volume 1`,section:`6.3 Volumes of Revolution: Cylindrical Shells`,url:`https://openstax.org/books/calculus-volume-1/pages/6-3-volumes-of-revolution-cylindrical-shells`},status:`unverified`,explanation:[`Rotating the region under $y = f(x)$ about the $y$-axis turns each thin vertical strip into a hollow cylinder, a shell.`,`Unrolled, a shell is almost a flat sheet: its length is the circumference $2\\pi x$, its height is $f(x)$ and its thickness is $dx$. So $V = \\int_a^b 2\\pi x\\,f(x)\\,dx$.`,`Shells are useful when washers would need $x$ written in terms of $y$, which can be hard or split into several pieces.`,`About another vertical line, such as $x = -1$, the radius is the distance to that line: $x - (-1) = x + 1$.`],takeaways:[`About the $y$-axis: $V = \\int_a^b 2\\pi x\\,f(x)\\,dx$`,`Radius $\\times$ height: radius is the distance to the axis, height is the curve.`,`Shells avoid solving the curve for $x$.`],example:{problem:`Rotate the region under $y = x^2$ for $0 \\le x \\le 2$ about the $y$-axis. Find the volume.`,steps:[`The shell at $x$ has radius $x$ and height $x^2$.`,`$V = \\int_0^2 2\\pi x \\cdot x^2\\,dx = 2\\pi \\int_0^2 x^3\\,dx = 2\\pi \\cdot 4 = 8\\pi$.`]},questions:[{id:`cylindrical-shells-1`,level:1,kind:`multiple-choice`,status:`unverified`,prompt:`The region under $y = f(x)$ is rotated about the $y$-axis using shells. What are the radius and height of the shell at $x$?`,solutionSteps:[`A shell at $x$ is a thin cylinder around the $y$-axis.`,`Its radius is its distance from the $y$-axis: $x$.`,`Its height reaches from the $x$-axis up to the curve: $f(x)$.`],options:[{text:`Radius $x$, height $f(x)$`,correct:!0},{text:`Radius $f(x)$, height $x$`,tag:`shell-radius-height`,feedback:`Those are swapped. The radius is the distance to the $y$-axis, $x$; the height is the curve, $f(x)$.`},{text:`Radius $2\\pi x$, height $f(x)$`,tag:`shell-radius-height`,feedback:`$2\\pi x$ is the circumference of the shell. The radius is $x$.`},{text:`Radius $x$, height $\\pi\\left[f(x)\\right]^2$`,tag:`shell-radius-height`,feedback:`$\\pi\\left[f(x)\\right]^2$ is the area of a disk. A shell's height is just the curve, $f(x)$.`}]},{id:`cylindrical-shells-2`,level:1,kind:`numeric`,status:`unverified`,prompt:`Rotate the region under $y = 3$ for $0 \\le x \\le 2$ about the $y$-axis. Use shells to find the volume. Answer in terms of pi.`,answer:37.69911184307752,integral:{of:`2 * pi * x * 3`,from:0,to:2},hint:`The shell at $x$ has radius $x$ and height 3. Integrate $2\\pi x \\cdot 3$.`,solutionSteps:[`Shell at $x$: radius $x$, height $3$, so $V = \\int_0^2 2\\pi x \\cdot 3\\,dx$.`,`$6\\pi\\int_0^2 x\\,dx = 6\\pi \\cdot \\frac{x^2}{2}\\Big|_0^2 = 6\\pi \\cdot 2$.`,`$12\\pi$, which matches a cylinder of radius 2 and height 3: $\\pi \\cdot 2^2 \\cdot 3$.`],mistakes:[{answer:18.84955592153876,tag:`shell-missing-two`,feedback:`A shell's length is its circumference, $2\\pi x$. It looks like the 2 was left out.`},{answer:12,tag:`volume-forgot-pi`,feedback:`The circumference $2\\pi x$ brings a factor of $\\pi$ into the volume.`}]},{id:`cylindrical-shells-3`,level:2,kind:`numeric`,status:`unverified`,prompt:`Rotate the region under $y = 2x - x^2$ for $0 \\le x \\le 2$ about the $y$-axis. Find the volume. Answer in terms of pi.`,answer:8.377580409572781,integral:{of:`2 * pi * x * (2x - x^2)`,from:0,to:2},hint:`Radius $x$, height $2x - x^2$. Multiply them out before integrating.`,solutionSteps:[`Shell at $x$: radius $x$, height $2x - x^2$.`,`$V = \\int_0^2 2\\pi x(2x - x^2)\\,dx = 2\\pi\\int_0^2 (2x^2 - x^3)\\,dx$.`,`$\\left(\\frac{2x^3}{3} - \\frac{x^4}{4}\\right)\\Big|_0^2 = \\frac{16}{3} - 4 = \\frac{4}{3}$.`,`$V = 2\\pi \\cdot \\frac{4}{3} = \\frac{8\\pi}{3}$.`],mistakes:[{answer:4.1887902047863905,tag:`shell-missing-two`,feedback:`A shell's length is its circumference, $2\\pi x$. It looks like the 2 was left out.`},{answer:3.351032163829112,tag:`shell-used-disks`,feedback:`That is the volume about the $x$-axis by disks. About the $y$-axis with shells, integrate $2\\pi x(2x - x^2)$.`}]},{id:`cylindrical-shells-4`,level:2,kind:`numeric`,status:`unverified`,prompt:`Rotate the region under $y = \\sqrt{x}$ for $0 \\le x \\le 4$ about the $y$-axis. Find the volume. Answer in terms of pi.`,answer:80.4247719318987,integral:{of:`2 * pi * x * sqrt(x)`,from:0,to:4},hint:`Radius $x$, height $\\sqrt{x}$, so integrate $2\\pi x^{3/2}$.`,solutionSteps:[`Shell at $x$: radius $x$, height $\\sqrt{x}$, so $V = \\int_0^4 2\\pi x\\sqrt{x}\\,dx = 2\\pi\\int_0^4 x^{3/2}\\,dx$.`,`$\\int x^{3/2}\\,dx = \\frac{2}{5}x^{5/2}$.`,`$\\frac{2}{5} \\cdot 4^{5/2} = \\frac{2}{5} \\cdot 32 = \\frac{64}{5}$.`,`$V = 2\\pi \\cdot \\frac{64}{5} = \\frac{128\\pi}{5}$.`],mistakes:[{answer:25.132741228718345,tag:`shell-used-disks`,feedback:`$8\\pi$ is the volume about the $x$-axis. About the $y$-axis, each shell has radius $x$ and height $\\sqrt{x}$.`}]},{id:`cylindrical-shells-5`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`Why are shells easier than washers for rotating the region under $y = 2x - x^2$ (for $0 \\le x \\le 2$) about the $y$-axis?`,solutionSteps:[`Washers about the $y$-axis slice horizontally, so they need $x$ in terms of $y$.`,`Solving $y = 2x - x^2$ for $x$ gives two expressions, $1 \\pm \\sqrt{1 - y}$: one for each side of the hill.`,`Shells slice vertically and use the curve as written, $y = 2x - x^2$.`],options:[{text:`Washers would need the curve solved for $x$, which gives two expressions, $1 \\pm \\sqrt{1 - y}$`,correct:!0},{text:`Washers only work for rotations about the $x$-axis`,tag:`shell-when-to-use`,feedback:`Washers work about any axis. About the $y$-axis they slice horizontally, which is where the trouble starts.`},{text:`The two methods give different volumes, and shells give the right one`,tag:`shell-when-to-use`,feedback:`Both methods give the same volume when set up correctly. The difference is how much algebra each one needs.`},{text:`Shells do not need limits of integration`,tag:`shell-when-to-use`,feedback:`Shells still need limits: here $x$ runs from 0 to 2.`}]},{id:`cylindrical-shells-6`,level:3,kind:`numeric`,status:`unverified`,prompt:`Rotate the region under $y = x^2$ for $0 \\le x \\le 1$ about the line $x = -1$. Find the volume. Answer in terms of pi.`,answer:3.6651914291880923,integral:{of:`2 * pi * (x + 1) * x^2`,from:0,to:1},hint:`The radius is the distance from $x$ to the line $x = -1$.`,solutionSteps:[`The axis is $x = -1$, so the radius of the shell at $x$ is $x - (-1) = x + 1$.`,`Height: $x^2$. So $V = \\int_0^1 2\\pi(x + 1)x^2\\,dx = 2\\pi\\int_0^1 (x^3 + x^2)\\,dx$.`,`$\\int_0^1 (x^3 + x^2)\\,dx = \\frac{1}{4} + \\frac{1}{3} = \\frac{7}{12}$.`,`$V = 2\\pi \\cdot \\frac{7}{12} = \\frac{7\\pi}{6}$.`],mistakes:[{answer:1.5707963267948966,tag:`shell-axis-shift`,feedback:`$\\frac{\\pi}{2}$ is the volume about the $y$-axis. About $x = -1$, every radius is 1 longer: $x + 1$.`},{answer:-.5235987755982988,tag:`shell-axis-shift`,feedback:`A volume cannot be negative. The distance from $x$ to $-1$ is $x - (-1) = x + 1$, not $x - 1$.`}]}]},{id:`work`,title:`Work`,objective:`Find the work done by a changing force, including stretching springs and lifting cables.`,prerequisites:[],source:{title:`OpenStax Calculus Volume 1`,section:`6.5 Physical Applications`,url:`https://openstax.org/books/calculus-volume-1/pages/6-5-physical-applications`},status:`unverified`,explanation:[`For a constant force, work is force times distance. When the force $F(x)$ changes with position, add up force times a tiny distance: $W = \\int_a^b F(x)\\,dx$. With newtons and meters, work is in joules (J).`,`Hooke's law: the force needed to hold a spring stretched $x$ meters beyond its natural length is $F(x) = kx$. Find $k$ from one known force and stretch, then integrate.`,`The limits are stretches measured from the natural length. Stretching from 0.2 m to 0.5 m beyond natural length means $\\int_{0.2}^{0.5} kx\\,dx$.`,`For lifting a cable or pumping a liquid, different pieces move different distances. Cut it into thin pieces, write weight times distance for one piece, and integrate.`],takeaways:[`$W = \\int_a^b F(x)\\,dx$`,`Spring: $F(x) = kx$, with $x$ measured from the natural length.`,`Lifting: weight of a thin piece $\\times$ how far that piece moves.`],example:{problem:`A spring has $k = 20$ N/m. How much work does it take to stretch it 0.5 m beyond its natural length?`,steps:[`By Hooke's law, $F(x) = 20x$.`,`$W = \\int_0^{0.5} 20x\\,dx = 10x^2\\Big|_0^{0.5} = 10 \\cdot 0.25 = 2.5$ J.`]},questions:[{id:`work-1`,level:1,kind:`numeric`,status:`unverified`,prompt:`A force of $F(x) = 3x^2$ newtons moves an object from $x = 0$ to $x = 2$ meters. How much work is done, in joules?`,answer:8,integral:{of:`3x^2`,from:0,to:2},hint:`Integrate the force over the distance: $\\int_0^2 3x^2\\,dx$.`,solutionSteps:[`Work with a varying force is $W = \\int_a^b F(x)\\,dx$.`,`$W = \\int_0^2 3x^2\\,dx = x^3\\Big|_0^2$.`,`$8 - 0 = 8$ J.`],mistakes:[{answer:24,tag:`work-constant-force`,feedback:`That multiplies the final force, 12 N, by 2 m. The force changes along the way, so integrate it.`}]},{id:`work-2`,level:1,kind:`multiple-choice`,status:`unverified`,prompt:`By Hooke's law, what force holds a spring stretched $x$ meters beyond its natural length?`,solutionSteps:[`Hooke's law: the force is proportional to how far the spring is stretched.`,`Call the constant of proportionality $k$, the spring constant.`,`$F(x) = kx$.`],options:[{text:`$kx$`,correct:!0},{text:`$\\frac{k}{x}$`,tag:`hooke-law`,feedback:`A spring pulls harder the more it is stretched, so the force grows with $x$: $kx$.`},{text:`$kx^2$`,tag:`hooke-law`,feedback:`$\\frac{1}{2}kx^2$ is the work to stretch it. The force itself is $kx$.`},{text:`$k$`,tag:`hooke-law`,feedback:`The force is not constant: it is proportional to the stretch, $kx$.`}]},{id:`work-3`,level:2,kind:`numeric`,status:`unverified`,prompt:`A force of 6 N holds a spring stretched 0.2 m beyond its natural length. How much work, in joules, does it take to stretch it from its natural length to 0.5 m beyond?`,answer:3.75,integral:{of:`30x`,from:0,to:.5},hint:`First find $k$ from $6 = k \\cdot 0.2$, then integrate $kx$ from 0 to 0.5.`,solutionSteps:[`Find $k$ from Hooke's law: $6 = k(0.2)$, so $k = 30$ N/m.`,`The stretch goes from 0 to 0.5 m: $W = \\int_0^{0.5} 30x\\,dx$.`,`$15x^2\\Big|_0^{0.5} = 15(0.25) = 3.75$ J.`],mistakes:[{answer:.75,tag:`hooke-find-k`,feedback:`That uses $k = 6$. The 6 N is the force at 0.2 m, so $k = \\frac{6}{0.2} = 30$.`},{answer:7.5,tag:`work-antiderivative`,feedback:`The antiderivative of $30x$ is $15x^2$, not $30x^2$.`}]},{id:`work-4`,level:2,kind:`numeric`,status:`unverified`,prompt:`The same spring ($k = 30$ N/m) is already stretched 0.2 m beyond its natural length. How much work, in joules, does it take to stretch it to 0.5 m beyond?`,answer:3.15,integral:{of:`30x`,from:.2,to:.5},hint:`The limits are the two stretches: integrate $30x$ from 0.2 to 0.5.`,solutionSteps:[`The stretch now goes from 0.2 m to 0.5 m, so those are the limits.`,`$W = \\int_{0.2}^{0.5} 30x\\,dx = 15x^2\\Big|_{0.2}^{0.5}$.`,`$15(0.25 - 0.04) = 15(0.21) = 3.15$ J.`],mistakes:[{answer:1.35,tag:`spring-limits`,feedback:`That integrates from 0 to 0.3. The spring starts 0.2 m stretched, so the limits are 0.2 and 0.5.`},{answer:3.75,tag:`spring-limits`,feedback:`That is the work from the natural length. The first 0.2 m is already done, so start at 0.2.`}]},{id:`work-5`,level:3,kind:`numeric`,status:`unverified`,prompt:`A 10 m cable weighing 2 N per meter hangs from the top of a building. How much work, in joules, does it take to pull the whole cable up to the top?`,answer:100,integral:{of:`2x`,from:0,to:10},hint:`A piece of cable $y$ meters below the top weighs $2\\,dy$ and is lifted $y$ meters.`,solutionSteps:[`Measure $y$ down from the top. A piece of cable of length $dy$ at depth $y$ weighs $2\\,dy$ newtons.`,`That piece is lifted $y$ meters, so its work is $2y\\,dy$.`,`$W = \\int_0^{10} 2y\\,dy = y^2\\Big|_0^{10} = 100$ J.`],mistakes:[{answer:200,tag:`work-constant-distance`,feedback:`That lifts the whole 20 N cable the full 10 m. Pieces near the top move only a little, so integrate weight times each piece's distance.`},{answer:20,tag:`work-weight-only`,feedback:`20 N is the cable's weight. Work is weight times the distance each piece is lifted.`}]},{id:`work-6`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`A full cylindrical tank of water has radius 1 m and height 4 m. Water weighs 9800 N per cubic meter. With $y$ measured down from the top, which integral gives the work to pump all the water out over the top?`,solutionSteps:[`Slice the water into thin horizontal disks. A slice at depth $y$ has volume $\\pi \\cdot 1^2\\,dy$.`,`Its weight is $9800\\pi\\,dy$ newtons.`,`It is lifted $y$ meters to the top, so its work is $9800\\pi\\,y\\,dy$.`,`Add the slices from the top ($y = 0$) to the bottom ($y = 4$): $W = \\int_0^4 9800\\pi\\,y\\,dy$.`],options:[{text:`$\\int_0^4 9800\\pi\\,y\\,dy$`,correct:!0},{text:`$\\int_0^4 9800\\pi\\,(4 - y)\\,dy$`,tag:`pumping-distance`,feedback:`$4 - y$ is the distance to the bottom. With $y$ measured down from the top, a slice at depth $y$ is lifted $y$ meters.`},{text:`$\\int_0^4 9800\\pi\\,dy$`,tag:`pumping-distance`,feedback:`That is the weight of all the water. Each slice's weight must be multiplied by how far it is lifted.`},{text:`$\\int_0^4 9800\\pi\\,y^2\\,dy$`,tag:`pumping-distance`,feedback:`The slice's volume is $\\pi r^2\\,dy$ with $r = 1$, so it does not depend on $y$. Only the distance, $y$, does.`}]}]},{id:`average-value`,title:`Average value of a function`,objective:`Find the average value of a function on an interval and a point where the function equals it.`,prerequisites:[],source:{title:`OpenStax Calculus Volume 1`,section:`5.2 The Definite Integral`,url:`https://openstax.org/books/calculus-volume-1/pages/5-2-the-definite-integral`},status:`unverified`,explanation:[`The average of a list of numbers is their sum divided by how many there are. For a function, the integral plays the part of the sum and the length of the interval the part of the count.`,`The average value of $f$ on $[a, b]$ is $f_{\\text{avg}} = \\frac{1}{b - a}\\int_a^b f(x)\\,dx$.`,`As a picture: a rectangle of height $f_{\\text{avg}}$ on $[a, b]$ has the same area as the region under $f$.`,`The Mean Value Theorem for Integrals (OpenStax 5.3) says that if $f$ is continuous, there is at least one $c$ in $[a, b]$ with $f(c) = f_{\\text{avg}}$.`],takeaways:[`$f_{\\text{avg}} = \\frac{1}{b - a}\\int_a^b f(x)\\,dx$`,`Divide by the length of the interval, $b - a$.`,`To find $c$, solve $f(c) = f_{\\text{avg}}$.`],example:{problem:`Find the average value of $f(x) = x^2$ on $[0, 3]$.`,steps:[`$\\int_0^3 x^2\\,dx = \\frac{x^3}{3}\\Big|_0^3 = 9$.`,`The interval has length 3, so $f_{\\text{avg}} = \\frac{9}{3} = 3$.`]},questions:[{id:`average-value-1`,level:1,kind:`numeric`,status:`unverified`,prompt:`Find the average value of $f(x) = 2x$ on $[0, 4]$.`,answer:4,integral:{of:`2x / 4`,from:0,to:4},hint:`Integrate $2x$ from 0 to 4, then divide by the length of the interval.`,solutionSteps:[`Average value: $f_{\\text{avg}} = \\frac{1}{b - a}\\int_a^b f(x)\\,dx$.`,`$\\int_0^4 2x\\,dx = x^2\\Big|_0^4 = 16$.`,`Divide by the length of the interval, 4: $\\frac{16}{4} = 4$.`],mistakes:[{answer:16,tag:`average-value-no-divide`,feedback:`16 is the integral. The average divides it by the length of the interval, 4.`}]},{id:`average-value-2`,level:1,kind:`multiple-choice`,status:`unverified`,prompt:`Which formula gives the average value of $f$ on $[a, b]$?`,solutionSteps:[`For finitely many values, the average is their sum divided by how many there are.`,`For a function, the integral plays the role of the sum and the length $b - a$ plays the role of the count.`,`$f_{\\text{avg}} = \\frac{1}{b - a}\\int_a^b f(x)\\,dx$.`],options:[{text:`$\\frac{1}{b - a}\\int_a^b f(x)\\,dx$`,correct:!0},{text:`$\\int_a^b f(x)\\,dx$`,tag:`average-value-no-divide`,feedback:`That is the total, like the sum of a list. Divide by the length of the interval to average it.`},{text:`$\\frac{f(a) + f(b)}{2}$`,tag:`average-value-endpoints`,feedback:`That averages only the two endpoint values. The average value uses every value of $f$ on the interval.`},{text:`$\\frac{f(b) - f(a)}{b - a}$`,tag:`average-value-rate`,feedback:`That is the average rate of change, the slope of the secant line, not the average value.`}]},{id:`average-value-3`,level:2,kind:`numeric`,status:`unverified`,prompt:`Find the average value of $f(x) = \\sin x$ on $[0, \\pi]$.`,answer:.6366197723675814,integral:{of:`sin(x) / pi`,from:0,to:3.141592653589793},hint:`$\\int_0^\\pi \\sin x\\,dx = 2$. Divide by the length of the interval.`,solutionSteps:[`$\\int_0^\\pi \\sin x\\,dx = -\\cos x\\Big|_0^\\pi = -(-1) - (-1) = 2$.`,`The interval has length $\\pi$.`,`$f_{\\text{avg}} = \\frac{2}{\\pi} \\approx 0.637$.`],mistakes:[{answer:2,tag:`average-value-no-divide`,feedback:`2 is the integral. Divide by the length of the interval, $\\pi$.`}]},{id:`average-value-4`,level:2,kind:`numeric`,status:`unverified`,prompt:`Find the average value of $f(x) = 3x^2 - 2x$ on $[1, 3]$.`,answer:9,integral:{of:`(3x^2 - 2x) / 2`,from:1,to:3},hint:`The antiderivative is $x^3 - x^2$. The interval has length $3 - 1 = 2$.`,solutionSteps:[`Antiderivative: $x^3 - x^2$.`,`$\\int_1^3 (3x^2 - 2x)\\,dx = (27 - 9) - (1 - 1) = 18$.`,`Divide by the length of the interval, 2: $f_{\\text{avg}} = \\frac{18}{2} = 9$.`],mistakes:[{answer:18,tag:`average-value-no-divide`,feedback:`18 is the integral. Divide by the length of the interval, 2.`},{answer:6,tag:`average-value-wrong-length`,feedback:`That divides by 3. The interval runs from 1 to 3, so its length is $3 - 1 = 2$.`}]},{id:`average-value-5`,level:3,kind:`numeric`,status:`unverified`,prompt:`The average value of $f(x) = x^2$ on $[0, 3]$ is 3. Find the $c$ in $[0, 3]$ with $f(c)$ equal to that average.`,answer:1.7320508075688772,hint:`Solve $c^2 = 3$ and keep the solution inside $[0, 3]$.`,solutionSteps:[`Set $f(c)$ equal to the average: $c^2 = 3$.`,`$c = \\pm\\sqrt{3}$.`,`Only $c = \\sqrt{3} \\approx 1.732$ is in $[0, 3]$.`],mistakes:[{answer:3,tag:`average-value-c`,feedback:`3 is the average value itself. The question asks for the $x$-value $c$ where $f(c) = 3$.`},{answer:1.5,tag:`average-value-c`,feedback:`1.5 is the middle of the interval. Solve $c^2 = 3$ instead.`},{answer:-1.7320508075688772,tag:`average-value-c`,feedback:`$-\\sqrt{3}$ solves $c^2 = 3$ but is not in $[0, 3]$.`}]},{id:`average-value-6`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`$T(t)$ is the temperature $t$ hours after midnight. What does $\\frac{1}{24}\\int_0^{24} T(t)\\,dt$ give?`,solutionSteps:[`The expression is the integral of $T$ divided by the length of the interval, 24 hours.`,`That is the average value formula for $T$ on $[0, 24]$.`,`So it gives the average temperature over the day.`],options:[{text:`The average temperature over the day`,correct:!0},{text:`The change in temperature over the day`,tag:`average-value-meaning`,feedback:`The change would be $T(24) - T(0)$. Dividing the integral by 24 gives an average.`},{text:`The temperature at noon`,tag:`average-value-meaning`,feedback:`The Mean Value Theorem says the average is reached at some time, but not necessarily at noon.`},{text:`The total temperature for the day`,tag:`average-value-no-divide`,feedback:`That would be the integral alone. The $\\frac{1}{24}$ turns it into an average.`}]}]}]},r={id:`derivatives`,courseId:`calculus-1`,courseTitle:`Calculus I`,title:`Derivatives`,concepts:[{id:`power-rule`,title:`Power rule`,objective:`Differentiate powers of x, including roots and reciprocals rewritten as powers.`,prerequisites:[],source:{title:`OpenStax Calculus Volume 1`,section:`3.3 Differentiation Rules`,url:`https://openstax.org/books/calculus-volume-1/pages/3-3-differentiation-rules`},status:`unverified`,explanation:[`For a constant exponent $n$, the derivative of $x^n$ is $nx^{n-1}$. Bring the exponent down in front as a coefficient, then lower the exponent by one.`,`Roots and fractions follow the same rule once they are written as powers. For example, $\\sqrt{x} = x^{1/2}$ and $\\frac{1}{x^2} = x^{-2}$.`],takeaways:[`$\\frac{d}{dx}x^n = nx^{n-1}$`,`Rewrite roots and fractions as powers of $x$ before differentiating.`,`The derivative of $x$ is $1$, because $x = x^1$ and $1 \\cdot x^0 = 1$.`],example:{problem:`Find $f'(x)$ for $f(x) = \\sqrt{x}$.`,steps:[`Rewrite the root as a power: $f(x) = x^{1/2}$.`,`Apply the power rule: $f'(x) = \\frac{1}{2}x^{1/2 - 1} = \\frac{1}{2}x^{-1/2}$.`,`Rewrite without a negative exponent: $f'(x) = \\frac{1}{2\\sqrt{x}}$.`]},questions:[{id:`power-rule-1`,level:1,kind:`expression`,status:`unverified`,prompt:`Find $f'(x)$ for $f(x) = x^5$.`,answer:`5x^4`,derivativeOf:`x^5`,hint:`Bring the exponent down as a coefficient, then subtract one from the exponent.`,solutionSteps:[`The power rule: $\\frac{d}{dx}x^n = nx^{n-1}$. Here $n = 5$.`,`Bring the 5 down and lower the exponent by 1: $5x^{5-1}$.`,`$f'(x) = 5x^4$.`],mistakes:[{answer:`5x^5`,tag:`power-rule-kept-exponent`,feedback:`You brought the 5 down but left the exponent at 5. Lower it by one: $x^5$ becomes $5x^4$.`},{answer:`x^4`,tag:`power-rule-forgot-coefficient`,feedback:`The exponent dropped correctly, but the old exponent, 5, also comes down in front as a coefficient.`},{answer:`5x^6`,tag:`power-rule-raised-exponent`,feedback:`The exponent goes down by one, not up. Raising the exponent is what happens when integrating.`}]},{id:`power-rule-2`,level:1,kind:`multiple-choice`,status:`unverified`,prompt:`What is the derivative of $x^8$?`,solutionSteps:[`Use the power rule with $n = 8$.`,`Bring the 8 down and lower the exponent to 7.`,`The derivative is $8x^7$.`],options:[{text:`$8x^7$`,correct:!0},{text:`$7x^8$`,tag:`power-rule-swapped-numbers`,feedback:`The coefficient is the original exponent, 8, and the new exponent is one less, 7.`},{text:`$8x^9$`,tag:`power-rule-raised-exponent`,feedback:`The exponent goes down by one, not up.`},{text:`$x^7$`,tag:`power-rule-forgot-coefficient`,feedback:`The exponent dropped correctly, but the 8 must also come down in front.`}]},{id:`power-rule-3`,level:1,kind:`expression`,status:`unverified`,prompt:`Find $f'(x)$ for $f(x) = x$.`,answer:`1`,derivativeOf:`x`,hint:`Write $x$ as a power of $x$ first.`,solutionSteps:[`Write $x$ as a power: $x = x^1$.`,`Power rule: $f'(x) = 1 \\cdot x^0$.`,`$x^0 = 1$, so $f'(x) = 1$. The line $y = x$ has slope 1 everywhere.`],mistakes:[{answer:`0`,tag:`power-rule-x-treated-as-constant`,feedback:`$x$ is not a constant. It is $x^1$, so its derivative is $1 \\cdot x^0 = 1$.`},{answer:`x`,tag:`power-rule-forgot-to-differentiate`,feedback:`That is the original function. Apply the power rule to $x^1$.`}]},{id:`power-rule-4`,level:2,kind:`expression`,status:`unverified`,prompt:`Find $f'(x)$ for $f(x) = \\sqrt[3]{x}$. Fractional and negative exponents are fine, for example x^(-1/2).`,answer:`(1/3)x^(-2/3)`,derivativeOf:`x^(1/3)`,hint:`Rewrite the cube root as $x^{1/3}$, then use the power rule.`,solutionSteps:[`Rewrite the root as a power: $\\sqrt[3]{x} = x^{1/3}$.`,`Power rule: $f'(x) = \\frac{1}{3}x^{1/3 - 1}$.`,`$\\frac{1}{3} - 1 = -\\frac{2}{3}$, so $f'(x) = \\frac{1}{3}x^{-2/3}$.`],mistakes:[{answer:`(1/3)x^(2/3)`,tag:`power-rule-fraction-subtraction`,feedback:`Check the new exponent: $\\frac{1}{3} - 1 = -\\frac{2}{3}$, not $\\frac{2}{3}$.`},{answer:`(1/3)x^(-1/3)`,tag:`power-rule-fraction-subtraction`,feedback:`Check the new exponent: $\\frac{1}{3} - 1 = -\\frac{2}{3}$.`}]},{id:`power-rule-5`,level:2,kind:`expression`,status:`unverified`,prompt:`Find $f'(x)$ for $f(x) = \\frac{1}{x^3}$.`,answer:`-3x^(-4)`,derivativeOf:`1/x^3`,hint:`Rewrite $\\frac{1}{x^3}$ as $x^{-3}$ first.`,solutionSteps:[`Rewrite the fraction as a power: $\\frac{1}{x^3} = x^{-3}$.`,`Power rule: $f'(x) = -3x^{-3-1}$.`,`$f'(x) = -3x^{-4}$, which is $-\\frac{3}{x^4}$.`],mistakes:[{answer:`-3x^(-2)`,tag:`power-rule-negative-exponent-subtraction`,feedback:`With a negative exponent, subtracting one makes it more negative: $-3 - 1 = -4$.`},{answer:`3x^(-4)`,tag:`power-rule-dropped-negative`,feedback:`The exponent $-3$ comes down as the coefficient, so the result is negative.`},{answer:`1/(3x^2)`,tag:`power-rule-differentiated-denominator`,feedback:`You cannot differentiate the denominator by itself. Rewrite $\\frac{1}{x^3}$ as $x^{-3}$, then use the power rule.`}]},{id:`power-rule-6`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`Why can't the power rule be used on $2^x$?`,solutionSteps:[`The power rule covers $x^n$: a variable base raised to a constant exponent.`,`In $2^x$ the base is the constant 2 and the variable is in the exponent.`,`So it needs the rule for exponential functions (Section 3.9), not the power rule.`],options:[{text:`The variable is in the exponent. The power rule needs a variable base with a constant exponent, $x^n$.`,correct:!0},{text:`It can be used: the derivative is $x \\cdot 2^{x-1}$.`,tag:`power-rule-applied-to-exponential`,feedback:`That applies the power rule where it does not fit. The derivative of $2^x$ is $2^x \\ln 2$, from Section 3.9.`},{text:`It can be used after rewriting $2^x$ as $x^2$.`,tag:`power-rule-applied-to-exponential`,feedback:`$2^x$ and $x^2$ are different functions. At $x = 3$ they equal 8 and 9.`}]}]},{id:`sum-and-constant-rules`,title:`Constants, sums and constant multiples`,objective:`Differentiate polynomials term by term using the constant, constant multiple and sum rules.`,prerequisites:[`power-rule`],source:{title:`OpenStax Calculus Volume 1`,section:`3.3 Differentiation Rules`,url:`https://openstax.org/books/calculus-volume-1/pages/3-3-differentiation-rules`},status:`unverified`,explanation:[`The derivative of a constant is 0, because a constant function has a flat graph with slope 0 everywhere.`,`A constant factor stays in front: $\\frac{d}{dx}[k f(x)] = k f'(x)$. Sums and differences are differentiated term by term: $\\frac{d}{dx}[f(x) \\pm g(x)] = f'(x) \\pm g'(x)$.`,`Together with the power rule, these rules differentiate any polynomial.`],takeaways:[`$\\frac{d}{dx}c = 0$ for any constant $c$.`,`$\\frac{d}{dx}[k f(x)] = k f'(x)$`,`Differentiate a sum or difference one term at a time.`],example:{problem:`Find $f'(x)$ for $f(x) = 4x^3 - 5x^2 + 7x - 2$.`,steps:[`Differentiate each term: $\\frac{d}{dx}4x^3 = 12x^2$, $\\frac{d}{dx}(-5x^2) = -10x$, $\\frac{d}{dx}7x = 7$ and $\\frac{d}{dx}(-2) = 0$.`,`Combine the results: $f'(x) = 12x^2 - 10x + 7$.`]},questions:[{id:`sum-and-constant-rules-1`,level:1,kind:`expression`,status:`unverified`,prompt:`Find $f'(x)$ for $f(x) = 7$.`,answer:`0`,derivativeOf:`7`,hint:`What is the slope of a horizontal line?`,solutionSteps:[`$f(x) = 7$ is the same number for every $x$.`,`A function that never changes has slope 0 everywhere.`,`$f'(x) = 0$.`],mistakes:[{answer:`7`,tag:`constant-derivative-nonzero`,feedback:`A constant does not change, so its rate of change is 0.`},{answer:`1`,tag:`constant-derivative-nonzero`,feedback:`A constant does not change, so its rate of change is 0. The derivative of $x$ is 1, but 7 has no $x$.`}]},{id:`sum-and-constant-rules-2`,level:1,kind:`expression`,status:`unverified`,prompt:`Find $f'(x)$ for $f(x) = 6x^4$.`,answer:`24x^3`,derivativeOf:`6x^4`,hint:`Keep the 6 in front and differentiate $x^4$.`,solutionSteps:[`The constant 6 stays in front: $f'(x) = 6 \\cdot \\frac{d}{dx}x^4$.`,`Power rule: $\\frac{d}{dx}x^4 = 4x^3$.`,`$f'(x) = 6 \\cdot 4x^3 = 24x^3$.`],mistakes:[{answer:`4x^3`,tag:`dropped-constant-multiple`,feedback:`The constant 6 stays as a factor: $6 \\cdot 4x^3 = 24x^3$.`},{answer:`24x^4`,tag:`power-rule-kept-exponent`,feedback:`The coefficient is right, but the exponent should drop from 4 to 3.`}]},{id:`sum-and-constant-rules-3`,level:1,kind:`expression`,status:`unverified`,prompt:`Find $f'(x)$ for $f(x) = x^3 + x^2$.`,answer:`3x^2 + 2x`,derivativeOf:`x^3 + x^2`,hint:`Differentiate each term separately and add the results.`,solutionSteps:[`The derivative of a sum is the sum of the derivatives: $\\frac{d}{dx}x^3 + \\frac{d}{dx}x^2$.`,`Power rule on each term: $3x^2$ and $2x$.`,`$f'(x) = 3x^2 + 2x$.`],mistakes:[{answer:`6x^3`,tag:`sum-rule-multiplied-terms`,feedback:`The derivatives of the two terms are added, not multiplied: $3x^2 + 2x$.`}]},{id:`sum-and-constant-rules-4`,level:2,kind:`expression`,status:`unverified`,prompt:`Find $f'(x)$ for $f(x) = 2x^5 - 3x^2 + x - 8$.`,answer:`10x^4 - 6x + 1`,derivativeOf:`2x^5 - 3x^2 + x - 8`,hint:`Work term by term. Watch the $x$ term and the constant.`,solutionSteps:[`Differentiate term by term.`,`$\\frac{d}{dx}2x^5 = 10x^4$, $\\frac{d}{dx}(-3x^2) = -6x$, $\\frac{d}{dx}x = 1$, $\\frac{d}{dx}(-8) = 0$.`,`$f'(x) = 10x^4 - 6x + 1$.`],mistakes:[{answer:`10x^4 - 6x - 7`,tag:`constant-derivative-nonzero`,feedback:`The derivative of the constant $-8$ is 0, so it drops out instead of combining with the 1.`},{answer:`10x^4 - 6x`,tag:`power-rule-x-treated-as-constant`,feedback:`The derivative of $x$ is 1, not 0.`}]},{id:`sum-and-constant-rules-5`,level:2,kind:`numeric`,status:`unverified`,prompt:`For $f(x) = 3x^2 - 4x + 1$, find $f'(2)$.`,answer:8,derivativeOf:`3x^2 - 4x + 1`,at:2,hint:`Find $f'(x)$ first, then substitute $x = 2$.`,solutionSteps:[`Differentiate first: $f'(x) = 6x - 4$.`,`Then substitute $x = 2$: $f'(2) = 6(2) - 4$.`,`$f'(2) = 12 - 4 = 8$.`],mistakes:[{answer:5,tag:`evaluated-function-not-derivative`,feedback:`5 is $f(2)$, the value of the function. Differentiate first, then substitute $x = 2$.`},{answer:6,tag:`constant-derivative-nonzero`,feedback:`Check the constant term: the derivative of 1 is 0, so $f'(x) = 6x - 4$.`}]},{id:`sum-and-constant-rules-6`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`If $g(x) = f(x) + 10$, how do $f'(x)$ and $g'(x)$ compare?`,solutionSteps:[`Differentiate both sides: $g'(x) = f'(x) + \\frac{d}{dx}10$.`,`The derivative of the constant 10 is 0.`,`So $g'(x) = f'(x)$. Adding 10 shifts the graph up without changing any slope.`],options:[{text:`They are equal, because adding a constant does not change any slopes.`,correct:!0},{text:`$g'(x) = f'(x) + 10$`,tag:`constant-derivative-nonzero`,feedback:`Shifting a graph up moves every point by 10 but keeps every slope the same. The derivative of 10 is 0.`},{text:`$g'(x) = 10 f'(x)$`,tag:`confused-sum-with-multiple`,feedback:`Multiplying by 10 would scale the slopes, but here 10 is added, not multiplied.`}]}]},{id:`product-rule`,title:`Product rule`,objective:`Differentiate a product of two functions with the product rule.`,prerequisites:[`sum-and-constant-rules`],source:{title:`OpenStax Calculus Volume 1`,section:`3.3 Differentiation Rules`,url:`https://openstax.org/books/calculus-volume-1/pages/3-3-differentiation-rules`},status:`unverified`,explanation:[`The derivative of a product is not the product of the derivatives. Instead, $\\frac{d}{dx}[f(x)g(x)] = f'(x)g(x) + f(x)g'(x)$.`,`In words: the derivative of the first times the second, plus the first times the derivative of the second.`],takeaways:[`$(fg)' = f'g + fg'$`,`$(fg)'$ is usually not equal to $f'g'$.`,`Expanding the product first and using the power rule gives the same answer, which is a useful check.`],example:{problem:`Find $h'(x)$ for $h(x) = (x^2 + 1)(x^3 - 2x)$.`,steps:[`Let $f(x) = x^2 + 1$ and $g(x) = x^3 - 2x$. Then $f'(x) = 2x$ and $g'(x) = 3x^2 - 2$.`,`Apply the rule: $h'(x) = 2x(x^3 - 2x) + (x^2 + 1)(3x^2 - 2)$.`,`Simplify: $h'(x) = 5x^4 - 3x^2 - 2$.`,`Check by expanding: $h(x) = x^5 - x^3 - 2x$, so $h'(x) = 5x^4 - 3x^2 - 2$.`]},questions:[{id:`product-rule-1`,level:1,kind:`multiple-choice`,status:`unverified`,prompt:`Which formula is the product rule for $\\frac{d}{dx}[f(x)g(x)]$?`,solutionSteps:[`The product rule takes the derivative of one factor at a time and adds the results.`,`Derivative of the first times the second: $f'(x)g(x)$.`,`Plus the first times the derivative of the second: $f'(x)g(x) + f(x)g'(x)$.`],options:[{text:`$f'(x)g(x) + f(x)g'(x)$`,correct:!0},{text:`$f'(x)g'(x)$`,tag:`product-of-derivatives`,feedback:`Multiplying the derivatives is the most common product rule mistake. Test it with $f = g = x$: $x^2$ has derivative $2x$, but $f'g' = 1$.`},{text:`$f'(x)g(x) - f(x)g'(x)$`,tag:`confused-product-and-quotient`,feedback:`The minus sign belongs to the quotient rule. The product rule adds the two terms.`}]},{id:`product-rule-2`,level:1,kind:`expression`,status:`unverified`,prompt:`Use the product rule to find $h'(x)$ for $h(x) = x^2(x + 3)$.`,answer:`3x^2 + 6x`,derivativeOf:`x^2 (x + 3)`,hint:`Let $f(x) = x^2$ and $g(x) = x + 3$. Then $h' = f'g + fg'$.`,solutionSteps:[`Let $f = x^2$ and $g = x + 3$, so $f' = 2x$ and $g' = 1$.`,`Product rule: $h'(x) = 2x(x + 3) + x^2(1)$.`,`Expand and combine: $2x^2 + 6x + x^2 = 3x^2 + 6x$.`],mistakes:[{answer:`2x`,tag:`product-of-derivatives`,feedback:`You multiplied the derivatives, $(2x)(1)$. The product rule adds two terms: $f'g + fg'$.`}]},{id:`product-rule-3`,level:1,kind:`expression`,status:`unverified`,prompt:`Use the product rule to find $h'(x)$ for $h(x) = (x + 1)(x - 1)$.`,answer:`2x`,derivativeOf:`(x + 1)(x - 1)`,hint:`Both factors have derivative 1.`,solutionSteps:[`Let $f = x + 1$ and $g = x - 1$, so $f' = 1$ and $g' = 1$.`,`Product rule: $h'(x) = 1 \\cdot (x - 1) + (x + 1) \\cdot 1$.`,`Combine: $h'(x) = 2x$.`,`Check: $h(x) = x^2 - 1$, whose derivative is $2x$.`],mistakes:[{answer:`1`,tag:`product-of-derivatives`,feedback:`You multiplied the derivatives, $1 \\cdot 1$. The product rule adds two terms: $f'g + fg'$.`}]},{id:`product-rule-4`,level:2,kind:`expression`,status:`unverified`,prompt:`Find $h'(x)$ for $h(x) = (2x^3 + 1)(x^2 - 4)$.`,answer:`10x^4 - 24x^2 + 2x`,derivativeOf:`(2x^3 + 1)(x^2 - 4)`,hint:`$f(x) = 2x^3 + 1$ and $g(x) = x^2 - 4$. Find $f'$ and $g'$, then use $f'g + fg'$.`,solutionSteps:[`Let $f = 2x^3 + 1$ and $g = x^2 - 4$, so $f' = 6x^2$ and $g' = 2x$.`,`Product rule: $h'(x) = 6x^2(x^2 - 4) + (2x^3 + 1)(2x)$.`,`Expand: $6x^4 - 24x^2 + 4x^4 + 2x$.`,`Combine: $h'(x) = 10x^4 - 24x^2 + 2x$. The unsimplified form is also accepted.`],mistakes:[{answer:`12x^3`,tag:`product-of-derivatives`,feedback:`You multiplied the derivatives, $(6x^2)(2x)$. The product rule adds two terms: $f'g + fg'$.`},{answer:`6x^2 (x^2 - 4) - (2x^3 + 1)(2x)`,tag:`confused-product-and-quotient`,feedback:`The product rule adds the two terms. The minus sign belongs to the quotient rule.`}]},{id:`product-rule-5`,level:2,kind:`numeric`,status:`unverified`,prompt:`For $h(x) = x^3(2x - 5)$, find $h'(1)$.`,answer:-7,derivativeOf:`x^3 (2x - 5)`,at:1,hint:`Find $h'(x)$ with the product rule, then substitute $x = 1$.`,solutionSteps:[`Let $f = x^3$ and $g = 2x - 5$, so $f' = 3x^2$ and $g' = 2$.`,`Product rule: $h'(x) = 3x^2(2x - 5) + x^3 \\cdot 2$.`,`Substitute $x = 1$: $h'(1) = 3(1)(-3) + (1)(2)$.`,`$h'(1) = -9 + 2 = -7$.`],mistakes:[{answer:6,tag:`product-of-derivatives`,feedback:`That is $f'(1)g'(1) = 3 \\cdot 2$. The product rule adds two terms: $f'g + fg'$.`},{answer:-3,tag:`evaluated-function-not-derivative`,feedback:`$-3$ is $h(1)$, the value of the function. Differentiate first, then substitute.`}]},{id:`product-rule-6`,level:3,kind:`numeric`,status:`unverified`,prompt:`Suppose $f(2) = 3$, $f'(2) = -1$, $g(2) = 4$ and $g'(2) = 5$. What is the derivative of $f(x)g(x)$ at $x = 2$?`,answer:11,hint:`Substitute the given values into $f'g + fg'$.`,solutionSteps:[`Product rule at $x = 2$: $f'(2)g(2) + f(2)g'(2)$.`,`Substitute the given values: $(-1)(4) + (3)(5)$.`,`$-4 + 15 = 11$.`],mistakes:[{answer:-5,tag:`product-of-derivatives`,feedback:`That is $f'(2)g'(2)$. The product rule is $f'g + fg'$.`},{answer:12,tag:`evaluated-function-not-derivative`,feedback:`12 is $f(2)g(2)$, the value of the product. The question asks for its derivative.`},{answer:-19,tag:`confused-product-and-quotient`,feedback:`That is $f'g - fg'$. The product rule adds the two terms.`}]}]},{id:`quotient-rule`,title:`Quotient rule`,objective:`Differentiate a quotient of two functions with the quotient rule.`,prerequisites:[`product-rule`],source:{title:`OpenStax Calculus Volume 1`,section:`3.3 Differentiation Rules`,url:`https://openstax.org/books/calculus-volume-1/pages/3-3-differentiation-rules`},status:`unverified`,explanation:[`For a quotient where $g(x) \\neq 0$: $\\frac{d}{dx}\\left[\\frac{f(x)}{g(x)}\\right] = \\frac{f'(x)g(x) - f(x)g'(x)}{[g(x)]^2}$.`,`Order matters in the numerator because of the minus sign. Start with the derivative of the top. Swapping the two terms flips the sign of the answer.`],takeaways:[`$\\left(\\frac{f}{g}\\right)' = \\frac{f'g - fg'}{g^2}$`,`The numerator starts with $f'g$, the derivative of the top.`,`If a fraction simplifies first, simplifying can avoid the quotient rule entirely.`],example:{problem:`Find $h'(x)$ for $h(x) = \\frac{x^2}{x + 1}$.`,steps:[`Let $f(x) = x^2$ and $g(x) = x + 1$. Then $f'(x) = 2x$ and $g'(x) = 1$.`,`Apply the rule: $h'(x) = \\frac{2x(x + 1) - x^2 \\cdot 1}{(x + 1)^2}$.`,`Simplify the numerator: $h'(x) = \\frac{x^2 + 2x}{(x + 1)^2}$.`]},questions:[{id:`quotient-rule-1`,level:1,kind:`multiple-choice`,status:`unverified`,prompt:`Which formula is the quotient rule for $\\frac{d}{dx}\\left[\\frac{f(x)}{g(x)}\\right]$?`,solutionSteps:[`The quotient rule puts the square of the bottom in the denominator: $g^2$.`,`The numerator is derivative of the top times the bottom, minus the top times the derivative of the bottom: $f'g - fg'$.`,`$\\left(\\frac{f}{g}\\right)' = \\frac{f'g - fg'}{g^2}$. The order in the numerator matters because of the minus sign.`],options:[{text:`$\\frac{f'g - fg'}{g^2}$`,correct:!0},{text:`$\\frac{fg' - f'g}{g^2}$`,tag:`quotient-rule-numerator-order`,feedback:`The numerator terms are in the wrong order, which flips the sign of the result. Start with $f'g$.`},{text:`$\\frac{f'}{g'}$`,tag:`quotient-of-derivatives`,feedback:`Dividing the derivatives does not give the derivative of the quotient.`},{text:`$\\frac{f'g - fg'}{g}$`,tag:`quotient-rule-denominator-not-squared`,feedback:`The numerator is right, but the denominator is squared: $g^2$.`}]},{id:`quotient-rule-2`,level:1,kind:`expression`,status:`unverified`,prompt:`Use the quotient rule to find $h'(x)$ for $h(x) = \\frac{1}{x + 2}$.`,answer:`-1/(x + 2)^2`,derivativeOf:`1/(x + 2)`,hint:`The top is $f(x) = 1$, so $f'(x) = 0$.`,solutionSteps:[`Top $f = 1$, bottom $g = x + 2$, so $f' = 0$ and $g' = 1$.`,`Quotient rule: $h'(x) = \\frac{0 \\cdot (x + 2) - 1 \\cdot 1}{(x + 2)^2}$.`,`Simplify: $h'(x) = -\\frac{1}{(x + 2)^2}$.`],mistakes:[{answer:`1/(x + 2)^2`,tag:`quotient-rule-numerator-order`,feedback:`Check the sign. The numerator is $f'g - fg' = 0 \\cdot (x + 2) - 1 \\cdot 1 = -1$.`},{answer:`0`,tag:`quotient-of-derivatives`,feedback:`That is $\\frac{f'}{g'} = \\frac{0}{1}$. Dividing the derivatives does not work; use $\\frac{f'g - fg'}{g^2}$.`}]},{id:`quotient-rule-3`,level:1,kind:`expression`,status:`unverified`,prompt:`Find $h'(x)$ for $h(x) = \\frac{x}{x + 1}$.`,answer:`1/(x + 1)^2`,derivativeOf:`x/(x + 1)`,hint:`$f(x) = x$ and $g(x) = x + 1$, and both have derivative 1.`,solutionSteps:[`Top $f = x$, bottom $g = x + 1$, so $f' = 1$ and $g' = 1$.`,`Quotient rule: $h'(x) = \\frac{1 \\cdot (x + 1) - x \\cdot 1}{(x + 1)^2}$.`,`The numerator is $x + 1 - x = 1$, so $h'(x) = \\frac{1}{(x + 1)^2}$.`],mistakes:[{answer:`-1/(x + 1)^2`,tag:`quotient-rule-numerator-order`,feedback:`The sign is flipped. The numerator starts with $f'g$: $1 \\cdot (x + 1) - x \\cdot 1 = 1$.`},{answer:`1`,tag:`quotient-of-derivatives`,feedback:`That is $\\frac{f'}{g'} = \\frac{1}{1}$. Use $\\frac{f'g - fg'}{g^2}$ instead.`}]},{id:`quotient-rule-4`,level:2,kind:`expression`,status:`unverified`,prompt:`Find $h'(x)$ for $h(x) = \\frac{x^2 + 1}{x - 3}$.`,answer:`(x^2 - 6x - 1)/(x - 3)^2`,derivativeOf:`(x^2 + 1)/(x - 3)`,hint:`$f(x) = x^2 + 1$ and $g(x) = x - 3$. You do not need to simplify.`,solutionSteps:[`Top $f = x^2 + 1$, bottom $g = x - 3$, so $f' = 2x$ and $g' = 1$.`,`Quotient rule: $h'(x) = \\frac{2x(x - 3) - (x^2 + 1)(1)}{(x - 3)^2}$.`,`Expand the numerator: $2x^2 - 6x - x^2 - 1 = x^2 - 6x - 1$.`,`$h'(x) = \\frac{x^2 - 6x - 1}{(x - 3)^2}$.`],mistakes:[{answer:`((x^2 + 1) - 2x(x - 3))/(x - 3)^2`,tag:`quotient-rule-numerator-order`,feedback:`The numerator terms are swapped, which flips the sign. Start with $f'g = 2x(x - 3)$.`},{answer:`2x`,tag:`quotient-of-derivatives`,feedback:`That is $\\frac{f'}{g'} = \\frac{2x}{1}$. Use $\\frac{f'g - fg'}{g^2}$ instead.`},{answer:`(2x(x - 3) - (x^2 + 1))/(x - 3)`,tag:`quotient-rule-denominator-not-squared`,feedback:`The numerator is right, but the denominator should be squared: $(x - 3)^2$.`}]},{id:`quotient-rule-5`,level:2,kind:`numeric`,status:`unverified`,prompt:`For $h(x) = \\frac{2x}{x^2 + 1}$, find $h'(2)$. A fraction such as -3/4 or a decimal is fine.`,answer:-.24,derivativeOf:`2x/(x^2 + 1)`,at:2,hint:`Find $h'(x)$ with the quotient rule, then substitute $x = 2$.`,solutionSteps:[`Top $f = 2x$, bottom $g = x^2 + 1$, so $f' = 2$ and $g' = 2x$.`,`Quotient rule: $h'(x) = \\frac{2(x^2 + 1) - 2x \\cdot 2x}{(x^2 + 1)^2} = \\frac{2 - 2x^2}{(x^2 + 1)^2}$.`,`Substitute $x = 2$: $h'(2) = \\frac{2 - 8}{(4 + 1)^2} = \\frac{-6}{25}$.`,`$h'(2) = -0.24$.`],mistakes:[{answer:.24,tag:`quotient-rule-numerator-order`,feedback:`The sign is flipped. The numerator starts with $f'g$, the derivative of the top times the bottom.`},{answer:.5,tag:`quotient-of-derivatives`,feedback:`That is $\\frac{f'(2)}{g'(2)} = \\frac{2}{4}$. Use $\\frac{f'g - fg'}{g^2}$ instead.`},{answer:.8,tag:`evaluated-function-not-derivative`,feedback:`0.8 is $h(2)$, the value of the function. Differentiate first, then substitute.`}]},{id:`quotient-rule-6`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`You need the derivative of $\\frac{x^3}{x}$ for $x \\neq 0$. What is the most efficient approach?`,solutionSteps:[`Look for a simplification first: $\\frac{x^3}{x} = x^2$ for $x \\neq 0$.`,`Power rule: $\\frac{d}{dx}x^2 = 2x$.`,`The quotient rule gives the same $2x$, with more work.`],options:[{text:`Simplify to $x^2$ first, then use the power rule to get $2x$.`,correct:!0},{text:`Divide the derivatives: $\\frac{3x^2}{1} = 3x^2$.`,tag:`quotient-of-derivatives`,feedback:`Dividing derivatives is not valid, and $3x^2$ does not match the correct derivative, $2x$.`},{text:`There is no shortcut. Every fraction requires the quotient rule.`,tag:`missed-simplification`,feedback:`Any valid method gives the same derivative. Simplifying first often saves work and avoids sign mistakes.`}]}]},{id:`trig-derivatives`,title:`Derivatives of trigonometric functions`,objective:`Differentiate the six trigonometric functions, alone and combined with the other rules.`,prerequisites:[`quotient-rule`],source:{title:`OpenStax Calculus Volume 1`,section:`3.5 Derivatives of Trigonometric Functions`,url:`https://openstax.org/books/calculus-volume-1/pages/3-5-derivatives-of-trigonometric-functions`},status:`unverified`,explanation:[`$\\frac{d}{dx} \\sin x = \\cos x$ and $\\frac{d}{dx} \\cos x = -\\sin x$.`,`The other four follow from these with the quotient rule: $\\frac{d}{dx} \\tan x = \\sec^2 x$, $\\frac{d}{dx} \\sec x = \\sec x \\tan x$, $\\frac{d}{dx} \\cot x = -\\csc^2 x$ and $\\frac{d}{dx} \\csc x = -\\csc x \\cot x$.`,`The functions that start with "co" (cosine, cotangent, cosecant) all have a minus sign in their derivative.`,`These rules assume $x$ is in radians.`],takeaways:[`$\\sin x \\to \\cos x$ and $\\cos x \\to -\\sin x$.`,`$\\tan x \\to \\sec^2 x$ and $\\sec x \\to \\sec x \\tan x$.`,`The "co" functions get a minus sign.`],example:{problem:`Find $f'(x)$ for $f(x) = x^2 \\sin x$.`,steps:[`It is a product, so use the product rule: $f' = (x^2)' \\sin x + x^2 (\\sin x)'$.`,`$f'(x) = 2x \\sin x + x^2 \\cos x$.`]},questions:[{id:`trig-derivatives-1`,level:1,kind:`expression`,status:`unverified`,prompt:`Find $f'(x)$ for $f(x) = 3 \\sin x - 2 \\cos x$.`,answer:`3cos(x) + 2sin(x)`,derivativeOf:`3sin(x) - 2cos(x)`,hint:`Differentiate each term: $\\sin x \\to \\cos x$ and $\\cos x \\to -\\sin x$.`,solutionSteps:[`$\\frac{d}{dx} 3 \\sin x = 3 \\cos x$.`,`$\\frac{d}{dx} (-2 \\cos x) = -2(-\\sin x) = 2 \\sin x$.`,`$f'(x) = 3 \\cos x + 2 \\sin x$.`],mistakes:[{answer:`3cos(x) - 2sin(x)`,tag:`cos-derivative-sign`,feedback:`The derivative of $\\cos x$ is $-\\sin x$, so $-2 \\cos x$ becomes $+2 \\sin x$.`}]},{id:`trig-derivatives-2`,level:1,kind:`multiple-choice`,status:`unverified`,prompt:`What is $\\frac{d}{dx} \\tan x$?`,solutionSteps:[`Write $\\tan x = \\frac{\\sin x}{\\cos x}$ and use the quotient rule.`,`$\\frac{\\cos x \\cos x - \\sin x (-\\sin x)}{\\cos^2 x} = \\frac{1}{\\cos^2 x} = \\sec^2 x$.`],options:[{text:`$\\sec^2 x$`,correct:!0},{text:`$-\\csc^2 x$`,tag:`trig-derivative-mixup`,feedback:`That is the derivative of $\\cot x$, the "co" function, which has the minus sign.`},{text:`$\\sec x \\tan x$`,tag:`trig-derivative-mixup`,feedback:`That is the derivative of $\\sec x$.`},{text:`$\\cot x$`,tag:`trig-derivative-mixup`,feedback:`$\\cot x$ is the reciprocal of $\\tan x$, not its derivative. Use the quotient rule on $\\frac{\\sin x}{\\cos x}$.`}]},{id:`trig-derivatives-3`,level:2,kind:`expression`,status:`unverified`,prompt:`Find $f'(x)$ for $f(x) = x^2 \\cos x$.`,answer:`2x cos(x) - x^2 sin(x)`,derivativeOf:`x^2 cos(x)`,hint:`Use the product rule: $(x^2)' \\cos x + x^2 (\\cos x)'$.`,solutionSteps:[`Product rule: $f' = (x^2)' \\cos x + x^2 (\\cos x)'$.`,`$(x^2)' = 2x$ and $(\\cos x)' = -\\sin x$.`,`$f'(x) = 2x \\cos x - x^2 \\sin x$.`],mistakes:[{answer:`-2x sin(x)`,tag:`product-of-derivatives`,feedback:`The derivative of a product is not the product of the derivatives. Use $f'g + fg'$.`},{answer:`2x cos(x) + x^2 sin(x)`,tag:`cos-derivative-sign`,feedback:`The derivative of $\\cos x$ is $-\\sin x$, so the second term is negative.`}]},{id:`trig-derivatives-4`,level:2,kind:`numeric`,status:`unverified`,prompt:`Find $f'\\left(\\frac{\\pi}{4}\\right)$ for $f(x) = x \\tan x$.`,answer:2.5707963267948966,derivativeOf:`x tan(x)`,at:.7853981633974483,hint:`Product rule: $f'(x) = \\tan x + x \\sec^2 x$. At $\\frac{\\pi}{4}$, $\\tan = 1$ and $\\sec^2 = 2$.`,solutionSteps:[`Product rule: $f'(x) = \\tan x + x \\sec^2 x$.`,`At $x = \\frac{\\pi}{4}$: $\\tan \\frac{\\pi}{4} = 1$ and $\\sec^2 \\frac{\\pi}{4} = \\frac{1}{\\cos^2 (\\pi/4)} = \\frac{1}{1/2} = 2$.`,`$f'\\left(\\frac{\\pi}{4}\\right) = 1 + \\frac{\\pi}{4} \\cdot 2 = 1 + \\frac{\\pi}{2} \\approx 2.571$.`],mistakes:[{answer:1,tag:`product-rule-missing-term`,feedback:`That is only $\\tan x$. The product rule also gives $x \\sec^2 x$.`},{answer:1.7853981633974483,tag:`sec-squared-value`,feedback:`$\\sec^2 \\frac{\\pi}{4}$ is 2, not 1: $\\cos \\frac{\\pi}{4} = \\frac{\\sqrt{2}}{2}$, so $\\cos^2 = \\frac{1}{2}$.`}]},{id:`trig-derivatives-5`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`Where does the graph of $y = \\sin x$ have a horizontal tangent line?`,solutionSteps:[`A horizontal tangent means slope 0, so set the derivative to 0.`,`$\\frac{d}{dx} \\sin x = \\cos x = 0$ at $x = \\frac{\\pi}{2} + k\\pi$.`,`These are the peaks and valleys of the sine wave.`],options:[{text:`Where $\\cos x = 0$, at $x = \\frac{\\pi}{2} + k\\pi$`,correct:!0},{text:`Where $\\sin x = 0$, at $x = k\\pi$`,tag:`slope-vs-value`,feedback:`There $\\sin x$ crosses zero with slope $\\pm 1$. A horizontal tangent needs the derivative, $\\cos x$, to be 0.`},{text:`Only at $x = 0$`,tag:`slope-vs-value`,feedback:`At $x = 0$ the slope is $\\cos 0 = 1$, the steepest the sine wave gets.`},{text:`Nowhere, because $\\sin x$ keeps changing`,tag:`slope-vs-value`,feedback:`It changes direction at its peaks and valleys, and the tangent is flat there.`}]},{id:`trig-derivatives-6`,level:3,kind:`numeric`,status:`unverified`,prompt:`Let $f(x) = \\sin x$. Find $f^{(99)}(0)$, the 99th derivative at 0.`,answer:-1,derivativeOf:`-sin(x)`,at:0,hint:`The derivatives of $\\sin x$ repeat every 4: $\\cos x, -\\sin x, -\\cos x, \\sin x$. Find where 99 lands.`,solutionSteps:[`The derivatives cycle with period 4: $f' = \\cos x$, $f'' = -\\sin x$, $f''' = -\\cos x$, $f^{(4)} = \\sin x$.`,`$99 = 4 \\cdot 24 + 3$, so $f^{(99)} = f''' = -\\cos x$.`,`$f^{(99)}(0) = -\\cos 0 = -1$.`],mistakes:[{answer:1,tag:`trig-cycle-count`,feedback:`99 leaves remainder 3 when divided by 4, so the 99th derivative matches the third: $-\\cos x$.`},{answer:0,tag:`trig-cycle-count`,feedback:`The even derivatives are $\\pm \\sin x$, which are 0 at 0. 99 is odd, so it is $\\pm \\cos x$.`}]}]},{id:`chain-rule`,title:`Chain rule`,objective:`Differentiate a composition of functions, such as a power of a polynomial, with the chain rule.`,prerequisites:[`power-rule`],source:{title:`OpenStax Calculus Volume 1`,section:`3.6 The Chain Rule`,url:`https://openstax.org/books/calculus-volume-1/pages/3-6-the-chain-rule`},status:`unverified`,explanation:[`A composition $f(g(x))$ has an outer function $f$ and an inner function $g$. Its derivative is $f'(g(x)) \\cdot g'(x)$.`,`Differentiate the outer function and leave the inner function unchanged inside it, then multiply by the derivative of the inner function.`,`For powers this becomes $\\frac{d}{dx}[g(x)]^n = n[g(x)]^{n-1} \\cdot g'(x)$.`],takeaways:[`$\\frac{d}{dx}f(g(x)) = f'(g(x)) \\cdot g'(x)$`,`Keep the inner function unchanged in the outer derivative.`,`Do not forget to multiply by the derivative of the inner function.`],example:{problem:`Find $h'(x)$ for $h(x) = (3x^2 + 1)^4$.`,steps:[`The outer function is $u^4$ and the inner function is $u = 3x^2 + 1$.`,`Differentiate the outer function and keep the inside: $4(3x^2 + 1)^3$.`,`Multiply by the derivative of the inside, $6x$: $h'(x) = 4(3x^2 + 1)^3 \\cdot 6x = 24x(3x^2 + 1)^3$.`]},questions:[{id:`chain-rule-1`,level:1,kind:`multiple-choice`,status:`unverified`,prompt:`In $h(x) = (5x - 2)^3$, what is the inner function?`,solutionSteps:[`Ask what you compute first when you evaluate $h(x)$ for a number $x$.`,`First you compute $5x - 2$, then you cube the result.`,`So the inner function is $5x - 2$ and the outer function is $u^3$.`],options:[{text:`$5x - 2$`,correct:!0},{text:`$u^3$`,tag:`chain-rule-swapped-inner-outer`,feedback:`That is the outer function, the step done last. The inner function goes inside it.`},{text:`$5x$`,tag:`chain-rule-partial-inner`,feedback:`The inner function is everything inside the parentheses, including the $-2$.`}]},{id:`chain-rule-2`,level:1,kind:`expression`,status:`unverified`,prompt:`Find $h'(x)$ for $h(x) = (2x + 1)^3$.`,answer:`6(2x + 1)^2`,derivativeOf:`(2x + 1)^3`,hint:`Differentiate the cube, keep $2x + 1$ inside, then multiply by the derivative of $2x + 1$.`,solutionSteps:[`Outer function $u^3$, inner function $u = 2x + 1$.`,`Derivative of the outer, inner left alone: $3(2x + 1)^2$.`,`Times the derivative of the inner, $2$: $h'(x) = 3(2x + 1)^2 \\cdot 2$.`,`$h'(x) = 6(2x + 1)^2$.`],mistakes:[{answer:`3(2x + 1)^2`,tag:`chain-rule-forgot-inner-derivative`,feedback:`You differentiated the outer power but did not multiply by the derivative of the inner function, $2x + 1$, which is 2.`}]},{id:`chain-rule-3`,level:1,kind:`expression`,status:`unverified`,prompt:`Find $h'(x)$ for $h(x) = (x^2 + 1)^2$.`,answer:`4x(x^2 + 1)`,derivativeOf:`(x^2 + 1)^2`,hint:`The outer function is $u^2$ and the inner function is $x^2 + 1$.`,solutionSteps:[`Outer function $u^2$, inner function $u = x^2 + 1$.`,`Derivative of the outer: $2(x^2 + 1)$.`,`Times the derivative of the inner, $2x$: $h'(x) = 2(x^2 + 1) \\cdot 2x$.`,`$h'(x) = 4x(x^2 + 1)$.`],mistakes:[{answer:`2(x^2 + 1)`,tag:`chain-rule-forgot-inner-derivative`,feedback:`Multiply by the derivative of the inner function, $2x$.`},{answer:`4x`,tag:`chain-rule-replaced-inner`,feedback:`You replaced the inside with its derivative. Keep $x^2 + 1$ unchanged in the outer derivative, then multiply by $2x$.`}]},{id:`chain-rule-4`,level:2,kind:`expression`,status:`unverified`,prompt:`Find $h'(x)$ for $h(x) = \\sqrt{x^2 + 4}$.`,answer:`x/sqrt(x^2 + 4)`,derivativeOf:`sqrt(x^2 + 4)`,hint:`Write $h(x) = (x^2 + 4)^{1/2}$.`,solutionSteps:[`Rewrite the root as a power: $h(x) = (x^2 + 4)^{1/2}$.`,`Derivative of the outer: $\\frac{1}{2}(x^2 + 4)^{-1/2}$.`,`Times the derivative of the inner, $2x$: $h'(x) = \\frac{1}{2}(x^2 + 4)^{-1/2} \\cdot 2x$.`,`Simplify: $h'(x) = \\frac{x}{\\sqrt{x^2 + 4}}$.`],mistakes:[{answer:`1/(2sqrt(x^2 + 4))`,tag:`chain-rule-forgot-inner-derivative`,feedback:`Multiply by the derivative of the inner function, $x^2 + 4$, which is $2x$.`}]},{id:`chain-rule-5`,level:2,kind:`numeric`,status:`unverified`,prompt:`For $h(x) = (x^3 - 2)^2$, find $h'(1)$.`,answer:-6,derivativeOf:`(x^3 - 2)^2`,at:1,hint:`Find $h'(x)$ with the chain rule, then substitute $x = 1$.`,solutionSteps:[`Outer function $u^2$, inner function $u = x^3 - 2$ with derivative $3x^2$.`,`Chain rule: $h'(x) = 2(x^3 - 2) \\cdot 3x^2$.`,`Substitute $x = 1$: $h'(1) = 2(1 - 2) \\cdot 3(1)$.`,`$h'(1) = 2(-1)(3) = -6$.`],mistakes:[{answer:-2,tag:`chain-rule-forgot-inner-derivative`,feedback:`That is $2(x^3 - 2)$ at $x = 1$. Multiply by the derivative of the inner function, $3x^2$.`},{answer:1,tag:`evaluated-function-not-derivative`,feedback:`1 is $h(1)$, the value of the function. Differentiate first, then substitute.`}]},{id:`chain-rule-6`,level:3,kind:`numeric`,status:`unverified`,prompt:`Suppose $g(1) = 2$, $g'(1) = 3$ and $f'(2) = 5$. If $h(x) = f(g(x))$, what is $h'(1)$?`,answer:15,hint:`$h'(1) = f'(g(1)) \\cdot g'(1)$. Find $g(1)$ first.`,solutionSteps:[`Chain rule: $h'(x) = f'(g(x)) \\cdot g'(x)$.`,`At $x = 1$: $h'(1) = f'(g(1)) \\cdot g'(1)$.`,`$g(1) = 2$, so this is $f'(2) \\cdot g'(1) = 5 \\cdot 3$.`,`$h'(1) = 15$.`],mistakes:[{answer:5,tag:`chain-rule-forgot-inner-derivative`,feedback:`That is $f'(g(1))$ alone. Multiply by the derivative of the inner function, $g'(1) = 3$.`},{answer:3,tag:`chain-rule-forgot-outer-derivative`,feedback:`That is $g'(1)$ alone. Multiply it by the outer derivative, $f'(g(1)) = f'(2) = 5$.`}]}]},{id:`implicit-differentiation`,title:`Implicit differentiation`,objective:`Find dy/dx for a curve given by an equation in x and y, and the slope at a point on it.`,prerequisites:[`chain-rule`],source:{title:`OpenStax Calculus Volume 1`,section:`3.8 Implicit Differentiation`,url:`https://openstax.org/books/calculus-volume-1/pages/3-8-implicit-differentiation`},status:`unverified`,explanation:[`Some curves, such as the circle $x^2 + y^2 = 25$, are not written as $y = f(x)$. Implicit differentiation finds $\\frac{dy}{dx}$ anyway.`,`Differentiate both sides with respect to $x$, treating $y$ as a function of $x$. By the chain rule, each term in $y$ picks up a factor $\\frac{dy}{dx}$: $\\frac{d}{dx} y^2 = 2y \\frac{dy}{dx}$.`,`Then move every $\\frac{dy}{dx}$ term to one side and solve for $\\frac{dy}{dx}$.`,`The answer usually has both $x$ and $y$ in it. For the slope at a point, substitute both coordinates.`],takeaways:[`Treat $y$ as a function of $x$.`,`Each $y$ term gets a factor $\\frac{dy}{dx}$.`,`Solve for $\\frac{dy}{dx}$, then substitute the point.`],example:{problem:`Find the slope of $x^2 + y^2 = 25$ at $(3, 4)$.`,steps:[`Differentiate both sides: $2x + 2y \\frac{dy}{dx} = 0$.`,`Solve: $\\frac{dy}{dx} = -\\frac{x}{y}$.`,`At $(3, 4)$: $\\frac{dy}{dx} = -\\frac{3}{4}$.`]},questions:[{id:`implicit-differentiation-1`,level:1,kind:`multiple-choice`,status:`unverified`,prompt:`If $y$ is a function of $x$, what is $\\frac{d}{dx}\\left(y^3\\right)$?`,solutionSteps:[`$y^3$ is a function inside a function: the outside is cubing, the inside is $y(x)$.`,`Chain rule: $3y^2$ times the derivative of the inside, $\\frac{dy}{dx}$.`],options:[{text:`$3y^2 \\frac{dy}{dx}$`,correct:!0},{text:`$3y^2$`,tag:`implicit-missing-dydx`,feedback:`$y$ depends on $x$, so the chain rule adds a factor $\\frac{dy}{dx}$.`},{text:`$3x^2$`,tag:`implicit-missing-dydx`,feedback:`The variable is $y$, not $x$. Differentiate $y^3$ and add the factor $\\frac{dy}{dx}$.`},{text:`$3y^2 + \\frac{dy}{dx}$`,tag:`implicit-missing-dydx`,feedback:`The chain rule multiplies by the inside derivative; it does not add it.`}]},{id:`implicit-differentiation-2`,level:1,kind:`numeric`,status:`unverified`,prompt:`Find the slope of $x^2 + y^2 = 169$ at the point $(5, 12)$.`,answer:-.4166666666666667,implicitSlope:{of:`x^2 + y^2 - 169`,x:5,y:12},hint:`Differentiate: $2x + 2y \\frac{dy}{dx} = 0$, so $\\frac{dy}{dx} = -\\frac{x}{y}$.`,solutionSteps:[`Differentiate both sides: $2x + 2y \\frac{dy}{dx} = 0$.`,`Solve: $\\frac{dy}{dx} = -\\frac{x}{y}$.`,`At $(5, 12)$: $-\\frac{5}{12} \\approx -0.417$.`],mistakes:[{answer:-2.4,tag:`implicit-flipped`,feedback:`Solving $2x + 2y \\frac{dy}{dx} = 0$ gives $-\\frac{x}{y}$, with $x$ on top.`},{answer:.4166666666666667,tag:`implicit-sign`,feedback:`Moving $2x$ to the other side makes it negative: $\\frac{dy}{dx} = -\\frac{x}{y}$.`}]},{id:`implicit-differentiation-3`,level:2,kind:`numeric`,status:`unverified`,prompt:`Find the slope of $xy = 6$ at the point $(2, 3)$.`,answer:-1.5,implicitSlope:{of:`x*y - 6`,x:2,y:3},hint:`$xy$ is a product: its derivative is $y + x \\frac{dy}{dx}$.`,solutionSteps:[`Product rule on the left: $\\frac{d}{dx}(xy) = 1 \\cdot y + x \\frac{dy}{dx}$. The right side, 6, gives 0.`,`$y + x \\frac{dy}{dx} = 0$, so $\\frac{dy}{dx} = -\\frac{y}{x}$.`,`At $(2, 3)$: $-\\frac{3}{2}$.`],mistakes:[{answer:-.6666666666666666,tag:`implicit-flipped`,feedback:`Solving $y + x \\frac{dy}{dx} = 0$ gives $-\\frac{y}{x}$, with $y$ on top.`},{answer:0,tag:`implicit-product-rule`,feedback:`$xy$ is a product of two functions of $x$, so it needs the product rule: $y + x \\frac{dy}{dx}$.`}]},{id:`implicit-differentiation-4`,level:2,kind:`numeric`,status:`unverified`,prompt:`Find the slope of $x^3 + y^3 = 9$ at the point $(1, 2)$.`,answer:-.25,implicitSlope:{of:`x^3 + y^3 - 9`,x:1,y:2},hint:`Differentiate: $3x^2 + 3y^2 \\frac{dy}{dx} = 0$.`,solutionSteps:[`Differentiate both sides: $3x^2 + 3y^2 \\frac{dy}{dx} = 0$.`,`Solve: $\\frac{dy}{dx} = -\\frac{x^2}{y^2}$.`,`At $(1, 2)$: $-\\frac{1}{4}$.`],mistakes:[{answer:-4,tag:`implicit-flipped`,feedback:`Solving gives $-\\frac{x^2}{y^2}$, with $x$ on top.`},{answer:-.5,tag:`implicit-dropped-power`,feedback:`Both squares stay: $\\frac{dy}{dx} = -\\frac{x^2}{y^2} = -\\frac{1}{4}$, not $-\\frac{x}{y}$.`}]},{id:`implicit-differentiation-5`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`For the circle $x^2 + y^2 = 25$, $\\frac{dy}{dx} = -\\frac{x}{y}$. Where is the tangent line vertical?`,solutionSteps:[`A vertical tangent has an undefined slope, which happens when the bottom of $-\\frac{x}{y}$ is 0.`,`$y = 0$ on the circle at $x = \\pm 5$.`,`So the tangent is vertical at $(5, 0)$ and $(-5, 0)$, the left and right edges of the circle.`],options:[{text:`At $(5, 0)$ and $(-5, 0)$, where $y = 0$`,correct:!0},{text:`At $(0, 5)$ and $(0, -5)$, where $x = 0$`,tag:`horizontal-vs-vertical`,feedback:`There the slope is $-\\frac{0}{y} = 0$: those tangents are horizontal.`},{text:`Nowhere, a circle is smooth`,tag:`horizontal-vs-vertical`,feedback:`Smooth curves can still have vertical tangents. Look for where the slope's bottom is 0.`},{text:`At $(3, 4)$`,tag:`horizontal-vs-vertical`,feedback:`There the slope is $-\\frac{3}{4}$, a regular slope.`}]},{id:`implicit-differentiation-6`,level:3,kind:`numeric`,status:`unverified`,prompt:`Find the slope of $x^2 + xy + y^2 = 7$ at the point $(1, 2)$.`,answer:-.8,implicitSlope:{of:`x^2 + x*y + y^2 - 7`,x:1,y:2},hint:`The middle term $xy$ needs the product rule. Collect the $\\frac{dy}{dx}$ terms before solving.`,solutionSteps:[`Differentiate: $2x + \\left(y + x \\frac{dy}{dx}\\right) + 2y \\frac{dy}{dx} = 0$.`,`Collect: $(x + 2y) \\frac{dy}{dx} = -(2x + y)$, so $\\frac{dy}{dx} = -\\frac{2x + y}{x + 2y}$.`,`At $(1, 2)$: $-\\frac{2 + 2}{1 + 4} = -\\frac{4}{5}$.`],mistakes:[{answer:-.5,tag:`implicit-product-rule`,feedback:`$xy$ also changes. Its derivative, $y + x \\frac{dy}{dx}$, adds to both sides of the collected equation.`},{answer:-1.25,tag:`implicit-flipped`,feedback:`The $\\frac{dy}{dx}$ factor is $x + 2y = 5$, and it goes on the bottom: $-\\frac{4}{5}$.`}]}]},{id:`log-derivatives`,title:`Derivatives of logarithms and exponentials`,objective:`Differentiate logarithms and exponentials of any base, and use logarithmic differentiation.`,prerequisites:[`chain-rule`],source:{title:`OpenStax Calculus Volume 1`,section:`3.9 Derivatives of Exponential and Logarithmic Functions`,url:`https://openstax.org/books/calculus-volume-1/pages/3-9-derivatives-of-exponential-and-logarithmic-functions`},status:`unverified`,explanation:[`$\\frac{d}{dx} \\ln x = \\frac{1}{x}$ for $x > 0$. More generally, $\\frac{d}{dx} \\ln |x| = \\frac{1}{x}$ for any $x \\ne 0$.`,`With the chain rule: $\\frac{d}{dx} \\ln(g(x)) = \\frac{g'(x)}{g(x)}$.`,`Other bases bring in a $\\ln b$: $\\frac{d}{dx} b^x = b^x \\ln b$ and $\\frac{d}{dx} \\log_b x = \\frac{1}{x \\ln b}$.`,`Logarithmic differentiation handles a variable in both the base and the exponent, as in $y = x^x$: take $\\ln$ of both sides, bring the exponent down with log rules, then differentiate implicitly.`],takeaways:[`$\\ln x \\to \\frac{1}{x}$, and $\\ln(g) \\to \\frac{g'}{g}$.`,`$b^x \\to b^x \\ln b$.`,`Simplify with log rules before differentiating.`],example:{problem:`Find $f'(x)$ for $f(x) = \\ln(x^2 + 1)$.`,steps:[`The inside is $g(x) = x^2 + 1$, with $g'(x) = 2x$.`,`$f'(x) = \\frac{g'(x)}{g(x)} = \\frac{2x}{x^2 + 1}$.`]},questions:[{id:`log-derivatives-1`,level:1,kind:`expression`,status:`unverified`,prompt:`Find $f'(x)$ for $f(x) = \\ln(5x)$.`,answer:`1/x`,derivativeOf:`ln(5x)`,hint:`Use $\\frac{g'}{g}$ with $g(x) = 5x$, or rewrite $\\ln(5x) = \\ln 5 + \\ln x$.`,solutionSteps:[`By the chain rule, $f'(x) = \\frac{(5x)'}{5x} = \\frac{5}{5x}$.`,`The 5s cancel: $f'(x) = \\frac{1}{x}$.`,`Check: $\\ln(5x) = \\ln 5 + \\ln x$, and $\\ln 5$ is a constant with derivative 0.`],mistakes:[{answer:`1/(5x)`,tag:`log-chain-missing`,feedback:`The chain rule multiplies by the inside's derivative, 5, which cancels the 5 on the bottom.`},{answer:`5/x`,tag:`log-chain-missing`,feedback:`The inside, $5x$, goes on the bottom: $\\frac{5}{5x}$.`}]},{id:`log-derivatives-2`,level:1,kind:`multiple-choice`,status:`unverified`,prompt:`What is $\\frac{d}{dx} 2^x$?`,solutionSteps:[`For an exponential $b^x$, the variable is in the exponent, so the power rule does not apply.`,`$\\frac{d}{dx} b^x = b^x \\ln b$, so $\\frac{d}{dx} 2^x = 2^x \\ln 2$.`],options:[{text:`$2^x \\ln 2$`,correct:!0},{text:`$x \\cdot 2^{x - 1}$`,tag:`power-rule-on-exponential`,feedback:`The power rule is for $x^n$, a variable base. Here the variable is in the exponent.`},{text:`$2^x$`,tag:`exponential-missing-ln`,feedback:`Only $e^x$ is its own derivative. Other bases pick up a factor $\\ln b$.`},{text:`$\\frac{2^x}{\\ln 2}$`,tag:`exponential-missing-ln`,feedback:`The $\\ln 2$ multiplies. Dividing by $\\ln b$ is the rule for $\\log_b x$.`}]},{id:`log-derivatives-3`,level:2,kind:`expression`,status:`unverified`,prompt:`Find $f'(x)$ for $f(x) = \\ln(x^3 + 2x)$.`,answer:`(3x^2 + 2)/(x^3 + 2x)`,derivativeOf:`ln(x^3 + 2x)`,hint:`Use $\\frac{g'}{g}$ with $g(x) = x^3 + 2x$.`,solutionSteps:[`The inside is $g(x) = x^3 + 2x$, with $g'(x) = 3x^2 + 2$.`,`$f'(x) = \\frac{g'(x)}{g(x)} = \\frac{3x^2 + 2}{x^3 + 2x}$.`],mistakes:[{answer:`1/(x^3 + 2x)`,tag:`log-chain-missing`,feedback:`The chain rule multiplies by the inside's derivative, $3x^2 + 2$.`},{answer:`1/(3x^2 + 2)`,tag:`log-chain-missing`,feedback:`The derivative of $\\ln(g)$ is $\\frac{g'}{g}$: the original inside goes on the bottom.`}]},{id:`log-derivatives-4`,level:2,kind:`expression`,status:`unverified`,prompt:`Find $f'(x)$ for $f(x) = x^2 \\ln x$.`,answer:`2x ln(x) + x`,derivativeOf:`x^2 ln(x)`,hint:`Use the product rule: $(x^2)' \\ln x + x^2 (\\ln x)'$.`,solutionSteps:[`Product rule: $f' = 2x \\ln x + x^2 \\cdot \\frac{1}{x}$.`,`Simplify: $f'(x) = 2x \\ln x + x$.`],mistakes:[{answer:`2x ln(x)`,tag:`product-rule-missing-term`,feedback:`The product rule has two terms. The second is $x^2 \\cdot \\frac{1}{x} = x$.`},{answer:`2`,tag:`product-of-derivatives`,feedback:`$2x \\cdot \\frac{1}{x} = 2$ multiplies the derivatives. Use $f'g + fg'$.`}]},{id:`log-derivatives-5`,level:3,kind:`numeric`,status:`unverified`,prompt:`Find $f'(2)$ for $f(x) = x^x$.`,answer:6.772588722239782,derivativeOf:`x^x`,at:2,hint:`Take $\\ln$ of both sides: $\\ln y = x \\ln x$. Differentiate both sides implicitly.`,solutionSteps:[`Let $y = x^x$. Take $\\ln$: $\\ln y = x \\ln x$.`,`Differentiate: $\\frac{1}{y} \\frac{dy}{dx} = \\ln x + 1$, so $\\frac{dy}{dx} = x^x (\\ln x + 1)$.`,`At $x = 2$: $4(\\ln 2 + 1) = 4 + 4 \\ln 2 \\approx 6.773$.`],mistakes:[{answer:4,tag:`power-rule-on-variable-exponent`,feedback:`The power rule needs a constant exponent. Here the exponent is $x$, so use logarithmic differentiation.`},{answer:2.772588722239781,tag:`exponential-rule-on-variable-base`,feedback:`$b^x \\ln b$ needs a constant base. Logarithmic differentiation gives $x^x(\\ln x + 1)$, with a $+1$ from the base.`}]},{id:`log-derivatives-6`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`$\\frac{d}{dx} \\ln(kx) = \\frac{1}{x}$ for every positive constant $k$. Why?`,solutionSteps:[`Log rules split the product: $\\ln(kx) = \\ln k + \\ln x$.`,`$\\ln k$ is a constant, so its derivative is 0, and only $\\frac{1}{x}$ is left.`,`Multiplying $x$ by $k$ shifts the graph of $\\ln$ up by $\\ln k$, which does not change its slope.`],options:[{text:`$\\ln(kx) = \\ln k + \\ln x$, and $\\ln k$ is a constant`,correct:!0},{text:`The derivative of $\\ln$ of anything is $\\frac{1}{x}$`,tag:`log-chain-missing`,feedback:`Not in general: $\\frac{d}{dx} \\ln(x^2) = \\frac{2}{x}$. It works for $kx$ because of the log rule.`},{text:`It is not true: the derivative is $\\frac{k}{x}$`,tag:`log-chain-missing`,feedback:`The chain rule gives $\\frac{k}{kx}$, and the $k$ cancels.`},{text:`Because $k$ cancels in the quotient rule`,tag:`log-chain-missing`,feedback:`There is no quotient here. The $k$ cancels in $\\frac{g'}{g} = \\frac{k}{kx}$, or vanishes as the constant $\\ln k$.`}]}]},{id:`related-rates`,title:`Related rates`,objective:`Find how fast one quantity changes from how fast a related quantity changes.`,prerequisites:[`implicit-differentiation`],source:{title:`OpenStax Calculus Volume 1`,section:`4.1 Related Rates`,url:`https://openstax.org/books/calculus-volume-1/pages/4-1-related-rates`},status:`unverified`,explanation:[`In a related rates problem, two or more quantities change over time and an equation links them. Knowing how fast one changes tells you how fast another does.`,`Steps: name the quantities, write the equation that links them, differentiate both sides with respect to time $t$ (each changing quantity picks up its own rate, such as $\\frac{dr}{dt}$), then substitute the values at the moment asked about.`,`Substitute numbers only after differentiating. A quantity that is changing has to stay a variable until then, or its rate disappears.`,`Keep the units: a rate is an amount per unit of time, such as cm²/s.`],takeaways:[`Write the equation, then differentiate with respect to $t$.`,`Every changing quantity gets its own rate.`,`Substitute numbers last.`],example:{problem:`A circle's radius grows at 2 cm/s. How fast is its area growing when $r = 5$ cm?`,steps:[`The equation: $A = \\pi r^2$.`,`Differentiate with respect to $t$: $\\frac{dA}{dt} = 2\\pi r \\frac{dr}{dt}$.`,`Substitute $r = 5$ and $\\frac{dr}{dt} = 2$: $\\frac{dA}{dt} = 2\\pi (5)(2) = 20\\pi$ cm²/s.`]},questions:[{id:`related-rates-1`,level:1,kind:`multiple-choice`,status:`unverified`,prompt:`A cube's side $s$ changes over time, and its volume is $V = s^3$. What is $\\frac{dV}{dt}$?`,solutionSteps:[`Differentiate both sides with respect to $t$. $s$ depends on $t$, so the chain rule applies.`,`$\\frac{dV}{dt} = 3s^2 \\frac{ds}{dt}$.`],options:[{text:`$3s^2 \\frac{ds}{dt}$`,correct:!0},{text:`$3s^2$`,tag:`related-rates-missing-rate`,feedback:`That is $\\frac{dV}{ds}$. Differentiating with respect to $t$ adds the factor $\\frac{ds}{dt}$.`},{text:`$\\left(\\frac{ds}{dt}\\right)^3$`,tag:`related-rates-missing-rate`,feedback:`Differentiate $s^3$ first with the power rule, then multiply by $\\frac{ds}{dt}$.`},{text:`$3 \\frac{ds}{dt}$`,tag:`related-rates-missing-rate`,feedback:`The power rule gives $3s^2$, and the chain rule multiplies it by $\\frac{ds}{dt}$.`}]},{id:`related-rates-2`,level:1,kind:`numeric`,status:`unverified`,prompt:`A square's side grows at 3 cm/s. How fast is its area growing, in cm²/s, when the side is 4 cm?`,answer:24,derivativeTimes:{of:`x^2`,at:4,factor:3},hint:`$A = s^2$, so $\\frac{dA}{dt} = 2s \\frac{ds}{dt}$.`,solutionSteps:[`The equation: $A = s^2$.`,`Differentiate with respect to $t$: $\\frac{dA}{dt} = 2s \\frac{ds}{dt}$.`,`Substitute $s = 4$ and $\\frac{ds}{dt} = 3$: $2(4)(3) = 24$ cm²/s.`],mistakes:[{answer:8,tag:`related-rates-missing-rate`,feedback:`$2s = 8$ is $\\frac{dA}{ds}$. Multiply by $\\frac{ds}{dt} = 3$.`},{answer:0,tag:`substituted-too-early`,feedback:`Substituting $s = 4$ first makes $A = 16$, a constant. Differentiate first, then substitute.`}]},{id:`related-rates-3`,level:2,kind:`numeric`,status:`unverified`,prompt:`A spherical balloon's radius grows at 0.5 cm/s. How fast is its volume growing, in cm³/s, when the radius is 10 cm? Answer in terms of pi.`,answer:628.3185307179587,derivativeTimes:{of:`4/3 * pi * x^3`,at:10,factor:.5},hint:`$V = \\frac{4}{3}\\pi r^3$, so $\\frac{dV}{dt} = 4\\pi r^2 \\frac{dr}{dt}$.`,solutionSteps:[`The equation: $V = \\frac{4}{3}\\pi r^3$.`,`Differentiate with respect to $t$: $\\frac{dV}{dt} = 4\\pi r^2 \\frac{dr}{dt}$.`,`Substitute $r = 10$ and $\\frac{dr}{dt} = 0.5$: $4\\pi (100)(0.5) = 200\\pi$ cm³/s.`],mistakes:[{answer:1256.6370614359173,tag:`related-rates-missing-rate`,feedback:`$4\\pi r^2 = 400\\pi$ is $\\frac{dV}{dr}$. Multiply by $\\frac{dr}{dt} = 0.5$.`},{answer:200,tag:`dropped-pi`,feedback:`The volume formula has a $\\pi$ in it, so the answer does too: $200\\pi$.`}]},{id:`related-rates-4`,level:2,kind:`numeric`,status:`unverified`,prompt:`A 10 ft ladder leans against a wall. Its bottom slides away from the wall at 2 ft/s. How fast is its top moving, in ft/s, when the bottom is 6 ft from the wall? (Negative means down.)`,answer:-1.5,derivativeTimes:{of:`sqrt(100 - x^2)`,at:6,factor:2},hint:`With $x$ the bottom's distance and $y$ the top's height, $x^2 + y^2 = 100$. When $x = 6$, $y = 8$.`,solutionSteps:[`The equation: $x^2 + y^2 = 100$. When $x = 6$, $y = \\sqrt{100 - 36} = 8$.`,`Differentiate with respect to $t$: $2x \\frac{dx}{dt} + 2y \\frac{dy}{dt} = 0$, so $\\frac{dy}{dt} = -\\frac{x}{y} \\frac{dx}{dt}$.`,`Substitute: $-\\frac{6}{8} \\cdot 2 = -1.5$ ft/s. The top slides down at 1.5 ft/s.`],mistakes:[{answer:1.5,tag:`related-rates-sign`,feedback:`The top is sliding down, so its height is decreasing and the rate is negative.`},{answer:-2.6666666666666665,tag:`implicit-flipped`,feedback:`Solving gives $\\frac{dy}{dt} = -\\frac{x}{y} \\frac{dx}{dt}$, with $x = 6$ on top.`}]},{id:`related-rates-5`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`To find $\\frac{dA}{dt}$ for a growing circle when $r = 5$, why must you differentiate $A = \\pi r^2$ before substituting $r = 5$?`,solutionSteps:[`$r$ is changing, so it is a function of $t$.`,`Substituting first gives $A = 25\\pi$, a constant, whose derivative is 0, which loses the rate.`,`Differentiating first keeps $\\frac{dr}{dt}$ in the equation, and then the values at that moment go in.`],options:[{text:`$r$ is changing; substituting first makes it a constant, so its rate is lost`,correct:!0},{text:`Derivatives cannot be taken of numbers`,tag:`substituted-too-early`,feedback:`They can: the derivative of a number is 0. That is exactly the problem, because $r$ is not fixed.`},{text:`The order does not matter`,tag:`substituted-too-early`,feedback:`It does. $A = 25\\pi$ gives $\\frac{dA}{dt} = 0$, but the area is growing.`},{text:`The answer must be written in terms of $r$`,tag:`substituted-too-early`,feedback:`The answer is a number at that moment. The point is to keep $\\frac{dr}{dt}$ until after differentiating.`}]},{id:`related-rates-6`,level:3,kind:`numeric`,status:`unverified`,prompt:`Two cars leave the same point at the same time, one driving north at 60 mph and one east at 80 mph. How fast, in mph, is the distance between them growing after 1 hour?`,answer:100,derivativeTimes:{of:`sqrt((60x)^2 + (80x)^2)`,at:1,factor:1},hint:`With $a$ and $b$ the distances driven, $D^2 = a^2 + b^2$. After 1 hour, $a = 60$, $b = 80$ and $D = 100$.`,solutionSteps:[`The equation: $D^2 = a^2 + b^2$. After 1 hour, $a = 60$, $b = 80$, and $D = \\sqrt{3600 + 6400} = 100$.`,`Differentiate: $2D \\frac{dD}{dt} = 2a \\frac{da}{dt} + 2b \\frac{db}{dt}$.`,`Substitute: $\\frac{dD}{dt} = \\frac{60 \\cdot 60 + 80 \\cdot 80}{100} = 100$ mph.`],mistakes:[{answer:140,tag:`related-rates-add-speeds`,feedback:`The cars move at right angles, so their speeds do not simply add. Use $D^2 = a^2 + b^2$.`},{answer:20,tag:`related-rates-add-speeds`,feedback:`The difference of the speeds would apply to cars on the same road. These move at right angles.`}]}]},{id:`linear-approximation`,title:`Linear approximation and differentials`,objective:`Estimate function values with the tangent line, and estimate changes with differentials.`,prerequisites:[`power-rule`],source:{title:`OpenStax Calculus Volume 1`,section:`4.2 Linear Approximations and Differentials`,url:`https://openstax.org/books/calculus-volume-1/pages/4-2-linear-approximations-and-differentials`},status:`unverified`,explanation:[`Close to a point $a$, a differentiable function is nearly its tangent line. The linear approximation is $L(x) = f(a) + f'(a)(x - a)$.`,`Choose $a$ close to $x$ where $f(a)$ and $f'(a)$ are easy to find, such as a perfect square for $\\sqrt{x}$.`,`The differential $dy = f'(x) \\, dx$ estimates how much $y$ changes when $x$ changes by $dx$.`,`If the graph curves down near $a$, the tangent line lies above it and the estimate is too high; if it curves up, the estimate is too low.`],takeaways:[`$L(x) = f(a) + f'(a)(x - a)$.`,`Pick an $a$ where the function is easy to evaluate.`,`$dy = f'(x) \\, dx$ estimates a change.`],example:{problem:`Estimate $\\sqrt{4.1}$.`,steps:[`Use $f(x) = \\sqrt{x}$ at $a = 4$: $f(4) = 2$ and $f'(x) = \\frac{1}{2\\sqrt{x}}$, so $f'(4) = \\frac{1}{4}$.`,`$L(4.1) = 2 + \\frac{1}{4}(0.1) = 2.025$.`]},questions:[{id:`linear-approximation-1`,level:1,kind:`multiple-choice`,status:`unverified`,prompt:`What is the linear approximation of $f$ near $x = a$?`,solutionSteps:[`It is the tangent line at $a$: it passes through $(a, f(a))$ with slope $f'(a)$.`,`In point-slope form: $L(x) = f(a) + f'(a)(x - a)$.`],options:[{text:`$L(x) = f(a) + f'(a)(x - a)$`,correct:!0},{text:`$L(x) = f'(a)(x - a)$`,tag:`linear-approximation-missing-value`,feedback:`That is only the change. The line has to start at the height $f(a)$.`},{text:`$L(x) = f(a) + f(a)(x - a)$`,tag:`linear-approximation-slope`,feedback:`The slope of the tangent line is the derivative, $f'(a)$.`},{text:`$L(x) = f(x) + f'(x)(x - a)$`,tag:`linear-approximation-point`,feedback:`Everything is evaluated at the known point $a$; $f(x)$ is what is being estimated.`}]},{id:`linear-approximation-2`,level:1,kind:`numeric`,status:`unverified`,prompt:`Use the linear approximation of $f(x) = x^2$ at $a = 3$ to estimate $f(3.1)$.`,answer:9.6,linearApproximation:{of:`x^2`,at:3,x:3.1},hint:`$f(3) = 9$ and $f'(3) = 6$. Then $L(3.1) = 9 + 6(0.1)$.`,solutionSteps:[`$f(3) = 9$, and $f'(x) = 2x$ gives $f'(3) = 6$.`,`$L(3.1) = 9 + 6(3.1 - 3) = 9 + 0.6 = 9.6$.`,`The exact value is $9.61$, so the estimate is close.`],mistakes:[{answer:9.61,tag:`exact-not-approximation`,feedback:`That is the exact value of $3.1^2$. The question asks for the tangent line estimate, $9 + 6(0.1)$.`},{answer:.6,tag:`linear-approximation-missing-value`,feedback:`$0.6$ is the estimated change. Add it to $f(3) = 9$.`}]},{id:`linear-approximation-3`,level:2,kind:`numeric`,status:`unverified`,prompt:`Use a linear approximation to estimate $\\sqrt{9.2}$. Give four decimal places.`,answer:3.033333333333333,linearApproximation:{of:`sqrt(x)`,at:9,x:9.2},hint:`Use $a = 9$: $f(9) = 3$ and $f'(9) = \\frac{1}{2\\sqrt{9}} = \\frac{1}{6}$.`,solutionSteps:[`Use $f(x) = \\sqrt{x}$ at $a = 9$: $f(9) = 3$.`,`$f'(x) = \\frac{1}{2\\sqrt{x}}$, so $f'(9) = \\frac{1}{6}$.`,`$L(9.2) = 3 + \\frac{1}{6}(0.2) \\approx 3.0333$.`],mistakes:[{answer:3.1,tag:`linear-approximation-slope`,feedback:`The slope is $f'(9) = \\frac{1}{2\\sqrt{9}} = \\frac{1}{6}$, not $\\frac{1}{2}$.`},{answer:3.2,tag:`linear-approximation-slope`,feedback:`The slope of $\\sqrt{x}$ at 9 is $\\frac{1}{6}$, not 1: the square root grows slowly there.`}]},{id:`linear-approximation-4`,level:2,kind:`numeric`,status:`unverified`,prompt:`Use a linear approximation to estimate $\\sqrt[3]{8.12}$.`,answer:2.01,linearApproximation:{of:`cbrt(x)`,at:8,x:8.12},hint:`Use $a = 8$: $f(8) = 2$ and $f'(8) = \\frac{1}{3 \\cdot 8^{2/3}} = \\frac{1}{12}$.`,solutionSteps:[`Use $f(x) = x^{1/3}$ at $a = 8$: $f(8) = 2$.`,`$f'(x) = \\frac{1}{3} x^{-2/3}$, so $f'(8) = \\frac{1}{3 \\cdot 4} = \\frac{1}{12}$.`,`$L(8.12) = 2 + \\frac{1}{12}(0.12) = 2.01$.`],mistakes:[{answer:2.04,tag:`linear-approximation-slope`,feedback:`$f'(8) = \\frac{1}{3} \\cdot 8^{-2/3} = \\frac{1}{12}$. The $8^{-2/3} = \\frac{1}{4}$ factor is missing.`},{answer:2.12,tag:`linear-approximation-slope`,feedback:`The change in $x$ is multiplied by the slope, $\\frac{1}{12}$, before it is added.`}]},{id:`linear-approximation-5`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`The linear approximation of $\\sqrt{x}$ at $a = 4$ gives $\\sqrt{4.5} \\approx 2.125$. Is that estimate too high or too low?`,solutionSteps:[`$f(x) = \\sqrt{x}$ has $f''(x) = -\\frac{1}{4} x^{-3/2} < 0$, so its graph curves down.`,`A graph that curves down lies below its tangent lines.`,`So the tangent line estimate is too high. (The true value is about 2.121.)`],options:[{text:`Too high, because the graph curves down and lies below its tangent line`,correct:!0},{text:`Too low, because $\\sqrt{x}$ is increasing`,tag:`concavity-vs-increasing`,feedback:`Increasing does not decide it; curving does. $\\sqrt{x}$ curves down, so the tangent line is above the graph.`},{text:`Exact, because the tangent line touches the graph`,tag:`concavity-vs-increasing`,feedback:`It touches only at $x = 4$. At 4.5 the graph has already bent away.`},{text:`There is no way to tell without a calculator`,tag:`concavity-vs-increasing`,feedback:`The sign of $f''$ tells you: negative means the graph curves down, below the tangent.`}]},{id:`linear-approximation-6`,level:3,kind:`numeric`,status:`unverified`,prompt:`A sphere's radius is measured as 5 cm, with a possible error of 0.1 cm. Use a differential to estimate the largest error in its volume, in cm³. Answer in terms of pi.`,answer:31.41592653589793,derivativeTimes:{of:`4/3 * pi * x^3`,at:5,factor:.1},hint:`$V = \\frac{4}{3}\\pi r^3$, so $dV = 4\\pi r^2 \\, dr$ with $r = 5$ and $dr = 0.1$.`,solutionSteps:[`$V = \\frac{4}{3}\\pi r^3$, so $dV = 4\\pi r^2 \\, dr$.`,`Substitute $r = 5$ and $dr = 0.1$: $dV = 4\\pi (25)(0.1) = 10\\pi$.`,`The volume could be off by about $10\\pi \\approx 31.4$ cm³.`],mistakes:[{answer:314.1592653589793,tag:`differential-missing-dx`,feedback:`$4\\pi r^2 = 100\\pi$ is $\\frac{dV}{dr}$. Multiply by the error $dr = 0.1$.`},{answer:10,tag:`dropped-pi`,feedback:`The volume formula has a $\\pi$ in it, so the answer does too: $10\\pi$.`}]}]}]},i={id:`integrals`,courseId:`calculus-1`,courseTitle:`Calculus I`,title:`Integrals`,concepts:[{id:`antiderivatives`,title:`Antiderivatives and indefinite integrals`,objective:`Find antiderivatives of powers, constants, sine and cosine, and write them as indefinite integrals with + C.`,prerequisites:[],source:{title:`OpenStax Calculus Volume 1`,section:`4.10 Antiderivatives`,url:`https://openstax.org/books/calculus-volume-1/pages/4-10-antiderivatives`},status:`unverified`,explanation:[`A function $F$ is an antiderivative of $f$ when $F'(x) = f(x)$. Finding one runs differentiation backward.`,`Antiderivatives are never unique: if $F$ works, so does $F(x) + C$ for any constant $C$, because the derivative of a constant is 0. The indefinite integral $\\int f(x)\\,dx = F(x) + C$ names all of them at once.`,`The power rule runs backward: $\\int x^n\\,dx = \\frac{x^{n+1}}{n+1} + C$ for $n \\neq -1$. Raise the exponent by one, then divide by the new exponent. Also $\\int \\cos x\\,dx = \\sin x + C$ and $\\int \\sin x\\,dx = -\\cos x + C$.`,`Constant factors stay in front and sums are integrated term by term. You can always check an answer by differentiating it.`],takeaways:[`$\\int x^n\\,dx = \\frac{x^{n+1}}{n+1} + C$ for $n \\neq -1$`,`$\\int k\\,dx = kx + C$`,`$\\int \\cos x\\,dx = \\sin x + C$ and $\\int \\sin x\\,dx = -\\cos x + C$`,`Check an antiderivative by differentiating it.`],example:{problem:`Find $\\int (6x^2 - 4x + 3)\\,dx$.`,steps:[`Integrate term by term: $\\int 6x^2\\,dx = 6 \\cdot \\frac{x^3}{3} = 2x^3$, $\\int -4x\\,dx = -4 \\cdot \\frac{x^2}{2} = -2x^2$ and $\\int 3\\,dx = 3x$.`,`Add one constant for the whole answer: $2x^3 - 2x^2 + 3x + C$.`,`Check: $\\frac{d}{dx}(2x^3 - 2x^2 + 3x + C) = 6x^2 - 4x + 3$.`]},questions:[{id:`antiderivatives-1`,level:1,kind:`expression`,status:`unverified`,prompt:`Find $\\int x^2\\,dx$.`,answer:`x^3/3`,upToConstant:!0,antiderivativeOf:`x^2`,hint:`Raise the exponent by one, then divide by the new exponent.`,solutionSteps:[`Reverse power rule: raise the exponent by 1 and divide by the new exponent.`,`$\\int x^2\\,dx = \\frac{x^3}{3} + C$.`,`Check: $\\frac{d}{dx}\\frac{x^3}{3} = x^2$.`],mistakes:[{answer:`x^3`,tag:`integral-power-rule-no-divide`,feedback:`The exponent is right, but the derivative of $x^3$ is $3x^2$. Divide by the new exponent: $\\frac{x^3}{3}$.`},{answer:`2x`,tag:`differentiated-instead`,feedback:`$2x$ is the derivative of $x^2$. Integration goes the other way: find a function whose derivative is $x^2$.`},{answer:`x^3/2`,tag:`integral-power-rule-wrong-divisor`,feedback:`Divide by the new exponent, 3, not the old one.`}]},{id:`antiderivatives-2`,level:1,kind:`expression`,status:`unverified`,prompt:`Find $\\int 5\\,dx$.`,answer:`5x`,upToConstant:!0,antiderivativeOf:`5`,hint:`Which function has a derivative of 5 everywhere?`,solutionSteps:[`Ask which function has derivative 5.`,`$\\frac{d}{dx}5x = 5$.`,`$\\int 5\\,dx = 5x + C$.`],mistakes:[{answer:`5`,tag:`integral-of-constant`,feedback:`A constant has derivative 0, not 5. The function with slope 5 everywhere is $5x$.`}]},{id:`antiderivatives-3`,level:1,kind:`expression`,status:`unverified`,prompt:`Find $\\int \\cos x\\,dx$.`,answer:`sin(x)`,upToConstant:!0,antiderivativeOf:`cos(x)`,hint:`Which trigonometric function has $\\cos x$ as its derivative?`,solutionSteps:[`Ask which function has derivative $\\cos x$.`,`$\\frac{d}{dx}\\sin x = \\cos x$.`,`$\\int \\cos x\\,dx = \\sin x + C$.`],mistakes:[{answer:`-sin(x)`,tag:`trig-antiderivative-sign`,feedback:`$-\\sin x$ is the derivative of $\\cos x$. You need the function whose derivative is $\\cos x$, which is $\\sin x$.`}]},{id:`antiderivatives-4`,level:2,kind:`expression`,status:`unverified`,prompt:`Find $\\int (4x^3 + 6x - 2)\\,dx$.`,answer:`x^4 + 3x^2 - 2x`,upToConstant:!0,antiderivativeOf:`4x^3 + 6x - 2`,hint:`Integrate one term at a time, including the constant $-2$.`,solutionSteps:[`Integrate term by term.`,`$\\int 4x^3\\,dx = x^4$, $\\int 6x\\,dx = 3x^2$, $\\int (-2)\\,dx = -2x$.`,`$x^4 + 3x^2 - 2x + C$.`],mistakes:[{answer:`12x^2 + 6`,tag:`differentiated-instead`,feedback:`That is the derivative. Integrate instead: raise each exponent by one and divide.`},{answer:`x^4 + 3x^2`,tag:`integral-of-constant`,feedback:`The constant term $-2$ integrates to $-2x$. It does not drop out the way it would in a derivative.`}]},{id:`antiderivatives-5`,level:2,kind:`expression`,status:`unverified`,prompt:`Find $\\int \\left(\\sqrt{x} + \\frac{1}{x^2}\\right)dx$.`,answer:`(2/3)x^(3/2) - 1/x`,upToConstant:!0,antiderivativeOf:`sqrt(x) + 1/x^2`,hint:`Rewrite both terms as powers first: $x^{1/2}$ and $x^{-2}$.`,solutionSteps:[`Rewrite as powers: $\\sqrt{x} = x^{1/2}$ and $\\frac{1}{x^2} = x^{-2}$.`,`$\\int x^{1/2}\\,dx = \\frac{x^{3/2}}{3/2} = \\frac{2}{3}x^{3/2}$.`,`$\\int x^{-2}\\,dx = \\frac{x^{-1}}{-1} = -\\frac{1}{x}$.`,`$\\frac{2}{3}x^{3/2} - \\frac{1}{x} + C$.`],mistakes:[{answer:`(2/3)x^(3/2) + 1/x`,tag:`integral-power-rule-negative-exponent`,feedback:`For $x^{-2}$ the new exponent is $-1$, and dividing by $-1$ makes the term negative: $-\\frac{1}{x}$.`},{answer:`(3/2)x^(3/2) - 1/x`,tag:`integral-power-rule-wrong-divisor`,feedback:`Dividing by $\\frac{3}{2}$ means multiplying by $\\frac{2}{3}$, so the first term is $\\frac{2}{3}x^{3/2}$.`}]},{id:`antiderivatives-6`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`Which of these is not an antiderivative of $2x$?`,solutionSteps:[`Differentiate each option and look for the one that is not $2x$.`,`$\\frac{d}{dx}(x + 1)^2 = 2(x + 1) = 2x + 2$.`,`The other options are $x^2$ plus a constant, so each has derivative $2x$.`,`So $(x + 1)^2$ is not an antiderivative of $2x$.`],options:[{text:`$x^2 + 7$`,tag:`antiderivative-constant-confusion`,feedback:`$x^2 + 7$ differs from $x^2$ by a constant, so its derivative is $2x$. It is an antiderivative.`},{text:`$x^2 - 100$`,tag:`antiderivative-constant-confusion`,feedback:`Subtracting a constant does not change the derivative, so $x^2 - 100$ is an antiderivative of $2x$.`},{text:`$(x + 1)^2$`,correct:!0},{text:`$x^2$`,tag:`antiderivative-constant-confusion`,feedback:`$\\frac{d}{dx}x^2 = 2x$, so $x^2$ is an antiderivative.`}]}]},{id:`riemann-sums`,title:`Areas and Riemann sums`,objective:`Estimate the area under a curve with left, right and midpoint rectangles.`,prerequisites:[],source:{title:`OpenStax Calculus Volume 1`,section:`5.1 Approximating Areas`,url:`https://openstax.org/books/calculus-volume-1/pages/5-1-approximating-areas`},status:`unverified`,explanation:[`To estimate the area under $f$ from $x = a$ to $x = b$, split the interval into $n$ equal pieces of width $\\Delta x = \\frac{b - a}{n}$ and stand a rectangle on each piece.`,`Each rectangle's height is $f$ at one point of its piece: the left endpoint, the right endpoint or the midpoint. The estimate is the sum of the areas, $\\sum f(x_i)\\,\\Delta x$, called a Riemann sum.`,`For an increasing function, left endpoints give rectangles that sit under the curve, so the left sum underestimates and the right sum overestimates. More rectangles give a better estimate.`],takeaways:[`$\\Delta x = \\frac{b - a}{n}$`,`Riemann sum: add $f(x_i)\\,\\Delta x$ over all $n$ rectangles.`,`Left endpoints run from $a$ to $b - \\Delta x$; right endpoints from $a + \\Delta x$ to $b$.`],example:{problem:`Estimate the area under $f(x) = x^2$ from 0 to 2 with 4 rectangles and right endpoints.`,steps:[`$\\Delta x = \\frac{2 - 0}{4} = 0.5$, so the right endpoints are $0.5, 1, 1.5, 2$.`,`The heights are $f(0.5) = 0.25$, $f(1) = 1$, $f(1.5) = 2.25$ and $f(2) = 4$, which add to $7.5$.`,`Multiply by the width: $7.5 \\times 0.5 = 3.75$.`]},questions:[{id:`riemann-sums-1`,level:1,kind:`numeric`,status:`unverified`,prompt:`The interval $[1, 7]$ is split into 3 equal pieces. What is $\\Delta x$?`,answer:2,hint:`Divide the length of the interval by the number of pieces.`,solutionSteps:[`$\\Delta x = \\frac{b - a}{n}$.`,`Here $a = 1$, $b = 7$ and $n = 3$.`,`$\\Delta x = \\frac{7 - 1}{3} = 2$.`],mistakes:[{answer:6,tag:`riemann-width-not-divided`,feedback:`6 is the length of the whole interval. Divide it by the 3 pieces.`},{answer:2.3333,tag:`riemann-width-wrong-length`,feedback:`Use the length $7 - 1 = 6$, not 7.`}]},{id:`riemann-sums-2`,level:1,kind:`numeric`,status:`unverified`,prompt:`Estimate the area under $f(x) = 2x$ from 0 to 3 with 3 rectangles and left endpoints.`,answer:6,riemannSum:{of:`2x`,from:0,to:3,n:3,rule:`left`},hint:`$\\Delta x = 1$, and the left endpoints are 0, 1 and 2.`,solutionSteps:[`$\\Delta x = \\frac{3 - 0}{3} = 1$, so the left endpoints are 0, 1 and 2.`,`Heights: $f(0) = 0$, $f(1) = 2$, $f(2) = 4$.`,`Sum of height times width: $(0 + 2 + 4) \\cdot 1 = 6$.`],mistakes:[{answer:12,tag:`riemann-wrong-endpoints`,feedback:`12 uses the right endpoints 1, 2 and 3. Left endpoints start at 0.`},{answer:9,tag:`riemann-exact-area`,feedback:`9 is the exact area of the triangle. The question asks for the rectangle estimate.`}]},{id:`riemann-sums-3`,level:1,kind:`numeric`,status:`unverified`,prompt:`Estimate the area under $f(x) = x^2$ from 0 to 2 with 2 rectangles and midpoints.`,answer:2.5,riemannSum:{of:`x^2`,from:0,to:2,n:2,rule:`midpoint`},hint:`$\\Delta x = 1$, so the midpoints are 0.5 and 1.5.`,solutionSteps:[`$\\Delta x = \\frac{2 - 0}{2} = 1$, so the midpoints are 0.5 and 1.5.`,`Heights: $f(0.5) = 0.25$ and $f(1.5) = 2.25$.`,`Sum of height times width: $(0.25 + 2.25) \\cdot 1 = 2.5$.`],mistakes:[{answer:5,tag:`riemann-wrong-endpoints`,feedback:`5 uses the right endpoints 1 and 2. Use the middle of each piece: 0.5 and 1.5.`},{answer:1,tag:`riemann-wrong-endpoints`,feedback:`1 uses the left endpoints 0 and 1. Use the middle of each piece: 0.5 and 1.5.`}]},{id:`riemann-sums-4`,level:2,kind:`numeric`,status:`unverified`,prompt:`Estimate the area under $f(x) = x^3$ from 0 to 2 with 4 rectangles and right endpoints.`,answer:6.25,riemannSum:{of:`x^3`,from:0,to:2,n:4,rule:`right`},hint:`$\\Delta x = 0.5$. Add $f(0.5) + f(1) + f(1.5) + f(2)$, then multiply by the width.`,solutionSteps:[`$\\Delta x = \\frac{2 - 0}{4} = 0.5$, so the right endpoints are 0.5, 1, 1.5 and 2.`,`Heights: $0.125$, $1$, $3.375$, $8$, which add to $12.5$.`,`Times the width: $12.5 \\times 0.5 = 6.25$.`],mistakes:[{answer:12.5,tag:`riemann-forgot-width`,feedback:`That is the sum of the heights. Multiply by the width $\\Delta x = 0.5$.`},{answer:2.25,tag:`riemann-wrong-endpoints`,feedback:`2.25 uses the left endpoints. Right endpoints are 0.5, 1, 1.5 and 2.`}]},{id:`riemann-sums-5`,level:2,kind:`numeric`,status:`unverified`,prompt:`Estimate the area under $f(x) = \\frac{1}{x}$ from 1 to 3 with 2 rectangles and left endpoints.`,answer:1.5,riemannSum:{of:`1/x`,from:1,to:3,n:2,rule:`left`},hint:`$\\Delta x = 1$, and the left endpoints are 1 and 2.`,solutionSteps:[`$\\Delta x = \\frac{3 - 1}{2} = 1$, so the left endpoints are 1 and 2.`,`Heights: $f(1) = 1$ and $f(2) = 0.5$.`,`Sum of height times width: $(1 + 0.5) \\cdot 1 = 1.5$.`],mistakes:[{answer:.8333,tag:`riemann-wrong-endpoints`,feedback:`That uses the right endpoints 2 and 3. Left endpoints start at 1.`}]},{id:`riemann-sums-6`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`$f$ is increasing on $[a, b]$. How does the left Riemann sum compare with the true area under $f$?`,solutionSteps:[`On each piece, an increasing function is lowest at the left endpoint.`,`So every left rectangle sits under the curve.`,`The left sum is smaller than the true area: an underestimate.`],options:[{text:`It is smaller (an underestimate)`,correct:!0},{text:`It is larger (an overestimate)`,tag:`riemann-over-under`,feedback:`That is true of the right sum. On each piece an increasing function is lowest at the left end.`},{text:`It is exactly equal`,tag:`riemann-over-under`,feedback:`Rectangles match the curve exactly only for a constant function.`},{text:`It depends on the number of rectangles`,tag:`riemann-over-under`,feedback:`More rectangles make the error smaller, but every left rectangle still sits under an increasing curve.`}]}]},{id:`definite-integral`,title:`The definite integral`,objective:`Read a definite integral as net signed area and use its properties.`,prerequisites:[`riemann-sums`],source:{title:`OpenStax Calculus Volume 1`,section:`5.2 The Definite Integral`,url:`https://openstax.org/books/calculus-volume-1/pages/5-2-the-definite-integral`},status:`unverified`,explanation:[`As the number of rectangles grows without bound, Riemann sums approach one number: the definite integral $\\int_a^b f(x)\\,dx$.`,`It measures net signed area. Area above the $x$-axis counts as positive and area below counts as negative, so they can cancel.`,`Useful properties: $\\int_a^a f(x)\\,dx = 0$, reversing the limits flips the sign, $\\int_b^a f(x)\\,dx = -\\int_a^b f(x)\\,dx$, and intervals add: $\\int_a^b f(x)\\,dx + \\int_b^c f(x)\\,dx = \\int_a^c f(x)\\,dx$.`,`For simple shapes such as rectangles and triangles you can find the integral from geometry.`],takeaways:[`$\\int_a^b f(x)\\,dx$ is net signed area: above the axis minus below.`,`$\\int_b^a f(x)\\,dx = -\\int_a^b f(x)\\,dx$`,`$\\int_a^b f(x)\\,dx + \\int_b^c f(x)\\,dx = \\int_a^c f(x)\\,dx$`],example:{problem:`Find $\\int_0^4 2x\\,dx$ using geometry.`,steps:[`The region under $y = 2x$ from 0 to 4 is a triangle with base 4 and height $2 \\cdot 4 = 8$.`,`Its area is $\\frac{1}{2} \\cdot 4 \\cdot 8 = 16$, and it lies above the axis, so $\\int_0^4 2x\\,dx = 16$.`]},questions:[{id:`definite-integral-1`,level:1,kind:`numeric`,status:`unverified`,prompt:`Find $\\int_0^3 4\\,dx$.`,answer:12,integral:{of:`4`,from:0,to:3},hint:`The region is a rectangle. What are its height and width?`,solutionSteps:[`The graph of $y = 4$ from 0 to 3 is a horizontal line above the axis.`,`The region under it is a rectangle with height 4 and width 3.`,`Area: $4 \\cdot 3 = 12$.`],mistakes:[{answer:4,tag:`definite-integral-height-only`,feedback:`4 is the height. Multiply by the width, $3 - 0 = 3$.`}]},{id:`definite-integral-2`,level:1,kind:`numeric`,status:`unverified`,prompt:`Find $\\int_0^2 x\\,dx$.`,answer:2,integral:{of:`x`,from:0,to:2},hint:`The region is a triangle with base 2 and height 2.`,solutionSteps:[`The region under $y = x$ from 0 to 2 is a triangle.`,`Its base is 2 and its height is $f(2) = 2$.`,`Area: $\\frac{1}{2} \\cdot 2 \\cdot 2 = 2$.`],mistakes:[{answer:4,tag:`triangle-area-no-half`,feedback:`4 is the area of the full square. The region is a triangle, so take half.`}]},{id:`definite-integral-3`,level:1,kind:`numeric`,status:`unverified`,prompt:`If $\\int_1^5 f(x)\\,dx = 8$, what is $\\int_5^1 f(x)\\,dx$?`,answer:-8,hint:`What happens to a definite integral when the limits are swapped?`,solutionSteps:[`Reversing the limits of integration flips the sign: $\\int_b^a f\\,dx = -\\int_a^b f\\,dx$.`,`$\\int_5^1 f(x)\\,dx = -\\int_1^5 f(x)\\,dx$.`,`$= -8$.`],mistakes:[{answer:8,tag:`reversed-limits-sign`,feedback:`Swapping the limits changes the sign of the integral.`}]},{id:`definite-integral-4`,level:2,kind:`numeric`,status:`unverified`,prompt:`If $\\int_0^6 f(x)\\,dx = 10$ and $\\int_0^2 f(x)\\,dx = 3$, find $\\int_2^6 f(x)\\,dx$.`,answer:7,hint:`The integral from 0 to 6 is the integral from 0 to 2 plus the integral from 2 to 6.`,solutionSteps:[`Integrals over adjoining intervals add: $\\int_0^6 f = \\int_0^2 f + \\int_2^6 f$.`,`Substitute: $10 = 3 + \\int_2^6 f(x)\\,dx$.`,`$\\int_2^6 f(x)\\,dx = 7$.`],mistakes:[{answer:13,tag:`interval-additivity`,feedback:`The two smaller intervals add up to the larger one, so subtract: $10 - 3$.`}]},{id:`definite-integral-5`,level:2,kind:`numeric`,status:`unverified`,prompt:`Find $\\int_{-2}^{2} x\\,dx$.`,answer:0,integral:{of:`x`,from:-2,to:2},hint:`Sketch $y = x$. Which part is above the axis and which is below?`,solutionSteps:[`From 0 to 2 the graph of $y = x$ is above the axis: a triangle of area 2, counted positive.`,`From $-2$ to 0 it is below the axis: a triangle of area 2, counted negative.`,`$2 + (-2) = 0$.`],mistakes:[{answer:4,tag:`signed-area`,feedback:`4 is the total area. Area below the axis counts as negative in a definite integral.`}]},{id:`definite-integral-6`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`A car's velocity $v(t)$ is negative for part of the time from $t = 0$ to $t = 10$. What does $\\int_0^{10} v(t)\\,dt$ give?`,solutionSteps:[`The integral of a rate gives the net change of the quantity.`,`Times when $v(t) < 0$ count negatively, as motion backward.`,`So the integral is the net change in position: the displacement, not the total distance.`],options:[{text:`The displacement (net change in position)`,correct:!0},{text:`The total distance traveled`,tag:`signed-area`,feedback:`Total distance counts backward motion as positive. The integral counts it as negative, so it gives displacement.`},{text:`The average velocity`,tag:`definite-integral-meaning`,feedback:`Average velocity is the integral divided by the time, 10.`},{text:`The velocity at $t = 10$`,tag:`definite-integral-meaning`,feedback:`The integral adds up velocity times time over the whole interval; it is not a single value of $v$.`}]}]},{id:`fundamental-theorem`,title:`The Fundamental Theorem of Calculus`,objective:`Evaluate definite integrals with antiderivatives, and differentiate an integral with a variable limit.`,prerequisites:[`antiderivatives`,`definite-integral`],source:{title:`OpenStax Calculus Volume 1`,section:`5.3 The Fundamental Theorem of Calculus`,url:`https://openstax.org/books/calculus-volume-1/pages/5-3-the-fundamental-theorem-of-calculus`},status:`unverified`,explanation:[`Part 1: if $F(x) = \\int_a^x f(t)\\,dt$, then $F'(x) = f(x)$. Differentiating an integral with respect to its upper limit gives back the integrand at that limit.`,`When the upper limit is a function $g(x)$, the chain rule adds a factor: $\\frac{d}{dx}\\int_a^{g(x)} f(t)\\,dt = f(g(x))\\,g'(x)$. The lower limit is a constant, so it contributes nothing.`,`Part 2: if $F$ is any antiderivative of $f$, then $\\int_a^b f(x)\\,dx = F(b) - F(a)$. This replaces the limit of Riemann sums with a subtraction.`,`The $+ C$ cancels in $F(b) - F(a)$, so it is left out of definite integrals.`],takeaways:[`$\\frac{d}{dx}\\int_a^x f(t)\\,dt = f(x)$`,`$\\frac{d}{dx}\\int_a^{g(x)} f(t)\\,dt = f(g(x))\\,g'(x)$`,`$\\int_a^b f(x)\\,dx = F(b) - F(a)$ for any antiderivative $F$`],example:{problem:`Evaluate $\\int_1^3 x^2\\,dx$.`,steps:[`An antiderivative of $x^2$ is $F(x) = \\frac{x^3}{3}$.`,`$F(3) - F(1) = \\frac{27}{3} - \\frac{1}{3} = \\frac{26}{3}$.`]},questions:[{id:`fundamental-theorem-1`,level:1,kind:`numeric`,status:`unverified`,prompt:`Evaluate $\\int_0^2 3x^2\\,dx$.`,answer:8,integral:{of:`3x^2`,from:0,to:2},hint:`An antiderivative of $3x^2$ is $x^3$. Compute $F(2) - F(0)$.`,solutionSteps:[`Find an antiderivative: $F(x) = x^3$.`,`Evaluate at the limits: $F(2) - F(0)$.`,`$8 - 0 = 8$.`],mistakes:[{answer:12,tag:`evaluated-integrand`,feedback:`12 is the integrand at $x = 2$. Find an antiderivative first, then subtract its values.`}]},{id:`fundamental-theorem-2`,level:1,kind:`expression`,status:`unverified`,prompt:`Find $\\frac{d}{dx}\\int_1^x \\sqrt{1 + t^2}\\,dt$.`,answer:`sqrt(1 + x^2)`,ftcOf:{integrand:`sqrt(1 + x^2)`,lower:1,upper:`x`},hint:`Part 1 of the theorem: put the upper limit into the integrand.`,solutionSteps:[`Part 1 of the Fundamental Theorem: $\\frac{d}{dx}\\int_a^x f(t)\\,dt = f(x)$.`,`The upper limit is just $x$, so no chain rule is needed.`,`Replace $t$ with $x$ in the integrand: $\\sqrt{1 + x^2}$.`],mistakes:[{answer:`sqrt(1 + x^2) - sqrt(2)`,tag:`ftc-lower-limit`,feedback:`The lower limit is a constant, so it adds nothing to the derivative. The answer is just $\\sqrt{1 + x^2}$.`},{answer:`x/sqrt(1 + x^2)`,tag:`ftc-differentiated-integrand`,feedback:`That is the derivative of $\\sqrt{1 + x^2}$. Part 1 says the derivative of the integral is the integrand itself.`}]},{id:`fundamental-theorem-3`,level:1,kind:`numeric`,status:`unverified`,prompt:`Evaluate $\\int_0^{\\pi/2} \\cos x\\,dx$.`,answer:1,integral:{of:`cos(x)`,from:0,to:1.5707963267948966},hint:`An antiderivative of $\\cos x$ is $\\sin x$.`,solutionSteps:[`Find an antiderivative: $F(x) = \\sin x$.`,`Evaluate at the limits: $\\sin\\frac{\\pi}{2} - \\sin 0$.`,`$1 - 0 = 1$.`],mistakes:[{answer:-1,tag:`trig-antiderivative-sign`,feedback:`The antiderivative of $\\cos x$ is $\\sin x$, not $-\\sin x$.`}]},{id:`fundamental-theorem-4`,level:2,kind:`numeric`,status:`unverified`,prompt:`Evaluate $\\int_1^4 (2x + 1)\\,dx$.`,answer:18,integral:{of:`2x + 1`,from:1,to:4},hint:`Use $F(x) = x^2 + x$ and compute $F(4) - F(1)$.`,solutionSteps:[`Find an antiderivative: $F(x) = x^2 + x$.`,`$F(4) = 16 + 4 = 20$ and $F(1) = 1 + 1 = 2$.`,`$F(4) - F(1) = 20 - 2 = 18$.`],mistakes:[{answer:20,tag:`ftc-forgot-lower-limit`,feedback:`20 is $F(4)$. Subtract $F(1) = 2$ as well.`},{answer:22,tag:`ftc-added-limits`,feedback:`Subtract $F(1)$ from $F(4)$ instead of adding it.`}]},{id:`fundamental-theorem-5`,level:2,kind:`expression`,status:`unverified`,prompt:`Find $\\frac{d}{dx}\\int_0^{x^2} \\cos t\\,dt$.`,answer:`2x*cos(x^2)`,ftcOf:{integrand:`cos(x)`,lower:0,upper:`x^2`},hint:`The upper limit is $x^2$, so the chain rule adds a factor of its derivative.`,solutionSteps:[`Part 1 gives the integrand at the upper limit: $\\cos(x^2)$.`,`The upper limit is $x^2$, not $x$, so the chain rule multiplies by its derivative, $2x$.`,`$\\cos(x^2) \\cdot 2x = 2x\\cos(x^2)$.`],mistakes:[{answer:`cos(x^2)`,tag:`ftc-forgot-chain-rule`,feedback:`The upper limit is $x^2$, not $x$, so multiply by its derivative $2x$.`},{answer:`sin(x^2)`,tag:`ftc-evaluated-integral`,feedback:`$\\sin(x^2)$ is the integral itself. The question asks for its derivative.`}]},{id:`fundamental-theorem-6`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`Why is $+ C$ left out when evaluating $\\int_a^b f(x)\\,dx = F(b) - F(a)$?`,solutionSteps:[`Use the antiderivative $F(x) + C$ instead of $F(x)$.`,`$(F(b) + C) - (F(a) + C) = F(b) - F(a)$.`,`The constant cancels, so any antiderivative gives the same number.`],options:[{text:`It cancels in the subtraction`,correct:!0},{text:`$C$ is always 0`,tag:`constant-of-integration`,feedback:`$C$ can be any constant. It is left out because it cancels, not because it is 0.`},{text:`Definite integrals have no antiderivative`,tag:`constant-of-integration`,feedback:`Part 2 uses an antiderivative $F$. The point is that every choice of $F$ gives the same answer.`},{text:`It is added after subtracting`,tag:`constant-of-integration`,feedback:`A definite integral is a number, so no constant is added at all.`}]}]},{id:`substitution`,title:`Substitution`,objective:`Integrate a composite function by substituting u for its inside part.`,prerequisites:[`antiderivatives`,`fundamental-theorem`],source:{title:`OpenStax Calculus Volume 1`,section:`5.5 Substitution`,url:`https://openstax.org/books/calculus-volume-1/pages/5-5-substitution`},status:`unverified`,explanation:[`Substitution undoes the chain rule. When an integrand has the form $f(g(x))\\,g'(x)$, set $u = g(x)$, so $du = g'(x)\\,dx$, and the integral becomes $\\int f(u)\\,du$.`,`Choose $u$ as the inside of a composite function whose derivative, up to a constant factor, also appears. If the factor is off by a constant, divide by it.`,`After integrating in $u$, put $g(x)$ back in for $u$. For a definite integral, change the limits to $u$-values instead, and there is nothing to put back.`],takeaways:[`$\\int f(g(x))\\,g'(x)\\,dx = \\int f(u)\\,du$ with $u = g(x)$`,`Pick $u$ so that $du$, up to a constant, is already in the integrand.`,`Definite integrals: change the limits to $u = g(a)$ and $u = g(b)$.`],example:{problem:`Find $\\int 2x(x^2 + 1)^3\\,dx$.`,steps:[`Let $u = x^2 + 1$, so $du = 2x\\,dx$.`,`The integral becomes $\\int u^3\\,du = \\frac{u^4}{4} + C$.`,`Substitute back: $\\frac{(x^2 + 1)^4}{4} + C$.`]},questions:[{id:`substitution-1`,level:1,kind:`multiple-choice`,status:`unverified`,prompt:`To find $\\int 3x^2 \\cos(x^3)\\,dx$, which substitution works?`,solutionSteps:[`Look for an inner function whose derivative also appears in the integrand.`,`The inner function of $\\cos(x^3)$ is $x^3$, and $\\frac{d}{dx}x^3 = 3x^2$ is the other factor.`,`With $u = x^3$, $du = 3x^2\\,dx$, and the integral becomes $\\int \\cos u\\,du$.`],options:[{text:`$u = x^3$`,correct:!0},{text:`$u = \\cos(x^3)$`,tag:`substitution-choice`,feedback:`Then $du = -3x^2\\sin(x^3)\\,dx$, which is not in the integrand. Choose the inside of the composite function.`},{text:`$u = 3x^2$`,tag:`substitution-choice`,feedback:`$3x^2$ is the factor that becomes $du$. Choose the inside of $\\cos$, whose derivative it is.`},{text:`$u = x$`,tag:`substitution-choice`,feedback:`That changes nothing. Choose the inside of the composite function, $x^3$.`}]},{id:`substitution-2`,level:1,kind:`expression`,status:`unverified`,prompt:`Find $\\int 2x(x^2 + 3)^4\\,dx$.`,answer:`(x^2 + 3)^5/5`,upToConstant:!0,antiderivativeOf:`2x(x^2 + 3)^4`,hint:`Let $u = x^2 + 3$. Then $du = 2x\\,dx$.`,solutionSteps:[`Let $u = x^2 + 3$, so $du = 2x\\,dx$.`,`The integral becomes $\\int u^4\\,du = \\frac{u^5}{5} + C$.`,`Substitute back: $\\frac{(x^2 + 3)^5}{5} + C$.`],mistakes:[{answer:`(x^2 + 3)^5`,tag:`integral-power-rule-no-divide`,feedback:`After substituting, $\\int u^4\\,du = \\frac{u^5}{5}$. Divide by the new exponent.`}]},{id:`substitution-3`,level:1,kind:`expression`,status:`unverified`,prompt:`Find $\\int \\cos(5x)\\,dx$.`,answer:`sin(5x)/5`,upToConstant:!0,antiderivativeOf:`cos(5x)`,hint:`Let $u = 5x$, so $dx = \\frac{du}{5}$.`,solutionSteps:[`Let $u = 5x$, so $du = 5\\,dx$ and $dx = \\frac{1}{5}du$.`,`The integral becomes $\\frac{1}{5}\\int \\cos u\\,du = \\frac{1}{5}\\sin u + C$.`,`Substitute back: $\\frac{\\sin(5x)}{5} + C$.`,`Check: $\\frac{d}{dx}\\frac{\\sin(5x)}{5} = \\cos(5x)$.`],mistakes:[{answer:`sin(5x)`,tag:`substitution-missing-factor`,feedback:`The derivative of $\\sin(5x)$ is $5\\cos(5x)$, which is 5 times too big. Divide by 5.`},{answer:`5sin(5x)`,tag:`substitution-factor-inverted`,feedback:`Since $du = 5\\,dx$, you divide by 5, not multiply.`}]},{id:`substitution-4`,level:2,kind:`expression`,status:`unverified`,prompt:`Find $\\int \\frac{x}{x^2 + 1}\\,dx$.`,answer:`ln(x^2 + 1)/2`,upToConstant:!0,antiderivativeOf:`x/(x^2 + 1)`,hint:`Let $u = x^2 + 1$. Then $du = 2x\\,dx$, so $x\\,dx = \\frac{du}{2}$. Recall $\\int \\frac{1}{u}\\,du = \\ln|u| + C$.`,solutionSteps:[`Let $u = x^2 + 1$, so $du = 2x\\,dx$ and $x\\,dx = \\frac{1}{2}du$.`,`The integral becomes $\\frac{1}{2}\\int \\frac{1}{u}\\,du = \\frac{1}{2}\\ln|u| + C$.`,`Substitute back: $\\frac{1}{2}\\ln(x^2 + 1) + C$. No absolute value is needed, since $x^2 + 1 > 0$.`],mistakes:[{answer:`ln(x^2 + 1)`,tag:`substitution-missing-factor`,feedback:`The derivative of $\\ln(x^2 + 1)$ is $\\frac{2x}{x^2 + 1}$, twice the integrand. Divide by 2.`},{answer:`2ln(x^2 + 1)`,tag:`substitution-factor-inverted`,feedback:`Since $x\\,dx = \\frac{du}{2}$, the factor is $\\frac{1}{2}$, not 2.`}]},{id:`substitution-5`,level:2,kind:`numeric`,status:`unverified`,prompt:`Evaluate $\\int_0^1 2x(x^2 + 1)^3\\,dx$.`,answer:3.75,integral:{of:`2x(x^2 + 1)^3`,from:0,to:1},hint:`With $u = x^2 + 1$, the limits change: $x = 0$ gives $u = 1$ and $x = 1$ gives $u = 2$.`,solutionSteps:[`Let $u = x^2 + 1$, so $du = 2x\\,dx$.`,`Convert the limits: $x = 0$ gives $u = 1$ and $x = 1$ gives $u = 2$.`,`The integral becomes $\\int_1^2 u^3\\,du = \\frac{u^4}{4}\\Big|_1^2$.`,`$\\frac{16}{4} - \\frac{1}{4} = 4 - 0.25 = 3.75$.`],mistakes:[{answer:.25,tag:`substitution-limits-not-changed`,feedback:`That keeps the $x$-limits 0 and 1 for $u$. Change them: $u$ runs from 1 to 2.`},{answer:4,tag:`ftc-forgot-lower-limit`,feedback:`4 is the value at the upper limit $u = 2$. Subtract the value at $u = 1$, which is $\\frac{1}{4}$.`}]},{id:`substitution-6`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`In $\\int_0^2 x\\,e^{x^2}\\,dx$ you substitute $u = x^2$. What are the new limits?`,solutionSteps:[`The limits 0 and 2 are values of $x$, and the new integral is in $u$.`,`Convert each limit with $u = x^2$: $u = 0^2 = 0$ and $u = 2^2 = 4$.`,`So $u$ runs from 0 to 4.`],options:[{text:`$u$ from 0 to 4`,correct:!0},{text:`$u$ from 0 to 2`,tag:`substitution-limits-not-changed`,feedback:`0 and 2 are the $x$-limits. Put each into $u = x^2$.`},{text:`$u$ from 1 to $e^4$`,tag:`substitution-limits-wrong-function`,feedback:`The limits come from $u = x^2$, not from $e^{x^2}$.`},{text:`The limits stay the same`,tag:`substitution-limits-not-changed`,feedback:`The integral is now in terms of $u$, so the limits must be $u$-values.`}]}]}]},a={id:`limits`,courseId:`calculus-1`,courseTitle:`Calculus I`,title:`Limits and the derivative`,concepts:[{id:`limit-of-function`,title:`The limit of a function`,objective:`Read limits and one-sided limits from values near a point, and tell when a limit does not exist.`,prerequisites:[],source:{title:`OpenStax Calculus Volume 1`,section:`2.2 The Limit of a Function`,url:`https://openstax.org/books/calculus-volume-1/pages/2-2-the-limit-of-a-function`},status:`unverified`,explanation:[`$\\lim_{x \\to a} f(x) = L$ means $f(x)$ gets as close to $L$ as we like when $x$ is close enough to $a$, from either side.`,`A limit is about values near $a$, not at $a$. $f(a)$ can differ from the limit, or not be defined at all.`,`One-sided limits: $\\lim_{x \\to a^-}$ uses only $x < a$ and $\\lim_{x \\to a^+}$ only $x > a$. The two-sided limit exists only when both one-sided limits exist and are equal.`,`If $f(x)$ grows without bound as $x \\to a$, we write $\\lim_{x \\to a} f(x) = \\infty$. The limit is not a number, and the line $x = a$ is a vertical asymptote.`],takeaways:[`Near $a$, not at $a$.`,`Two-sided limit exists only when the left and right limits agree.`,`$\\infty$ means unbounded growth: a vertical asymptote.`],example:{problem:`Find $\\lim_{x \\to 1} \\frac{x^2 - 1}{x - 1}$.`,steps:[`At $x = 1$ the function is not defined ($\\frac{0}{0}$), but the limit only needs nearby values.`,`For $x \\ne 1$, $\\frac{x^2 - 1}{x - 1} = \\frac{(x - 1)(x + 1)}{x - 1} = x + 1$.`,`As $x \\to 1$, $x + 1 \\to 2$, so the limit is 2.`]},questions:[{id:`limit-of-function-1`,level:1,kind:`multiple-choice`,status:`unverified`,prompt:`$f(3) = 7$, but as $x$ gets close to 3 from both sides, $f(x)$ gets close to 5. What is $\\lim_{x \\to 3} f(x)$?`,solutionSteps:[`The limit depends only on values of $f$ near 3, not at 3.`,`Those values approach 5 from both sides, so the limit is 5. The value $f(3) = 7$ does not change it.`],options:[{text:`5`,correct:!0},{text:`7`,tag:`limit-vs-value`,feedback:`7 is $f(3)$, the value at the point. The limit is about the values nearby.`},{text:`It does not exist`,tag:`limit-vs-value`,feedback:`Both sides approach 5, so the limit exists. A different $f(3)$ makes $f$ discontinuous, not the limit undefined.`},{text:`6`,tag:`limit-vs-value`,feedback:`Limits are not averaged with the value at the point. The nearby values approach 5.`}]},{id:`limit-of-function-2`,level:1,kind:`numeric`,status:`unverified`,prompt:`A table of values of $\\frac{\\sin x}{x}$ for $x$ close to 0 (in radians) shows $0.99833$ at $x = \\pm 0.1$ and $0.99998$ at $x = \\pm 0.01$. What is $\\lim_{x \\to 0} \\frac{\\sin x}{x}$?`,answer:1,limit:{of:`sin(x) / x`,at:0},hint:`Look at what the values approach as $x$ gets closer to 0 from both sides.`,solutionSteps:[`The values $0.99833$, then $0.99998$, get closer and closer to 1 as $x$ shrinks.`,`They do so from both sides, since $\\frac{\\sin x}{x}$ is the same at $x$ and $-x$.`,`So $\\lim_{x \\to 0} \\frac{\\sin x}{x} = 1$, even though $\\frac{\\sin 0}{0}$ is not defined.`],mistakes:[{answer:0,tag:`zero-over-zero-is-zero`,feedback:`$\\frac{0}{0}$ is not 0; it is undetermined. Read the limit from the nearby values instead.`}]},{id:`limit-of-function-3`,level:2,kind:`numeric`,status:`unverified`,prompt:`Find $\\lim_{x \\to 0^-} \\frac{|x|}{x}$.`,answer:-1,limit:{of:`abs(x) / x`,at:0,side:`left`},hint:`For $x < 0$, $|x| = -x$.`,solutionSteps:[`The limit from the left uses only $x < 0$.`,`There $|x| = -x$, so $\\frac{|x|}{x} = \\frac{-x}{x} = -1$.`,`The function is $-1$ all the way to 0, so the left limit is $-1$.`],mistakes:[{answer:1,tag:`one-sided-wrong-side`,feedback:`That is the limit from the right, where $|x| = x$. From the left, $|x| = -x$.`},{answer:0,tag:`zero-over-zero-is-zero`,feedback:`The function is never close to 0: for every $x < 0$ it equals $-1$.`}]},{id:`limit-of-function-4`,level:2,kind:`numeric`,status:`unverified`,prompt:`Let $f(x) = x^2$ for $x < 1$ and $f(x) = 2x + 1$ for $x \\ge 1$. Find $\\lim_{x \\to 1^+} f(x)$.`,answer:3,limit:{of:`2x + 1`,at:1,side:`right`},hint:`From the right, $x > 1$, so use the piece $2x + 1$.`,solutionSteps:[`The limit from the right uses $x > 1$, where $f(x) = 2x + 1$.`,`As $x \\to 1$, $2x + 1 \\to 3$.`,`(From the left the limit is $1^2 = 1$, so the two-sided limit does not exist.)`],mistakes:[{answer:1,tag:`one-sided-wrong-side`,feedback:`That is the limit from the left, using $x^2$. From the right, $x > 1$ uses $2x + 1$.`}]},{id:`limit-of-function-5`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`Does $\\lim_{x \\to 0} \\frac{|x|}{x}$ exist?`,solutionSteps:[`From the left, $\\frac{|x|}{x} = -1$; from the right, it is $1$.`,`The one-sided limits are different, so the two-sided limit does not exist.`],options:[{text:`No, because the left limit is $-1$ and the right limit is $1$`,correct:!0},{text:`Yes, it is 0, the average of $-1$ and $1$`,tag:`one-sided-disagree`,feedback:`Limits are not averaged. When the two sides disagree, the two-sided limit does not exist.`},{text:`No, because the function is not defined at 0`,tag:`limit-vs-value`,feedback:`Being undefined at 0 does not stop a limit; $\\frac{x^2 - 1}{x - 1}$ has one at 1. Here the sides disagree.`},{text:`Yes, it is 1`,tag:`one-sided-disagree`,feedback:`1 is only the limit from the right. From the left the function is $-1$.`}]},{id:`limit-of-function-6`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`What is $\\lim_{x \\to 0} \\frac{1}{x^2}$?`,solutionSteps:[`As $x \\to 0$ from either side, $x^2$ is a small positive number.`,`So $\\frac{1}{x^2}$ grows without bound: the limit is $\\infty$.`,`It is not a number, and $x = 0$ is a vertical asymptote.`],options:[{text:`$\\infty$: it grows without bound, with a vertical asymptote at $x = 0$`,correct:!0},{text:`0`,tag:`limit-infinite`,feedback:`The bottom goes to 0, so the fraction gets larger, not smaller: $\\frac{1}{0.01^2} = 10{,}000$.`},{text:`1`,tag:`limit-infinite`,feedback:`Try $x = 0.1$: $\\frac{1}{0.01} = 100$. The values keep growing.`},{text:`$-\\infty$ from the left and $\\infty$ from the right`,tag:`limit-infinite`,feedback:`That is $\\frac{1}{x}$. Here $x^2$ is positive on both sides, so both sides go to $\\infty$.`}]}]},{id:`limit-laws`,title:`Calculating limits with the limit laws`,objective:`Evaluate limits by substitution, by simplifying a 0/0 form, and with the squeeze theorem.`,prerequisites:[`limit-of-function`],source:{title:`OpenStax Calculus Volume 1`,section:`2.3 The Limit Laws`,url:`https://openstax.org/books/calculus-volume-1/pages/2-3-the-limit-laws`},status:`unverified`,explanation:[`The limit of a sum, difference, product or quotient is the sum, difference, product or quotient of the limits, as long as those limits exist (and the bottom's limit is not 0).`,`For a polynomial, or a rational function defined at $a$, the limit is the value: substitute $x = a$.`,`If substituting gives $\\frac{0}{0}$, simplify first: factor and cancel, combine fractions, or multiply by the conjugate of a square root. Then substitute.`,`Squeeze theorem: if $g(x) \\le f(x) \\le h(x)$ near $a$ and $g$ and $h$ have the same limit $L$, then $f$ has limit $L$ too.`],takeaways:[`Try substituting first.`,`$\\frac{0}{0}$ means simplify, then substitute.`,`Trap an oscillating function between two that agree.`],example:{problem:`Find $\\lim_{x \\to 3} \\frac{x^2 - 9}{x - 3}$.`,steps:[`Substituting gives $\\frac{0}{0}$, so simplify.`,`Factor: $\\frac{(x - 3)(x + 3)}{x - 3} = x + 3$ for $x \\ne 3$.`,`Substitute: $3 + 3 = 6$.`]},questions:[{id:`limit-laws-1`,level:1,kind:`numeric`,status:`unverified`,prompt:`Find $\\lim_{x \\to -2} (x^2 - 3x)$.`,answer:10,limit:{of:`x^2 - 3x`,at:-2},hint:`A polynomial: substitute $x = -2$, keeping track of the signs.`,solutionSteps:[`Polynomials are continuous, so substitute $x = -2$.`,`$(-2)^2 - 3(-2) = 4 + 6 = 10$.`],mistakes:[{answer:-2,tag:`substitution-sign`,feedback:`$-3 \\cdot (-2) = +6$, so the two terms add: $4 + 6$.`},{answer:-10,tag:`substitution-sign`,feedback:`$(-2)^2 = 4$ is positive, and $-3(-2) = 6$ is too.`}]},{id:`limit-laws-2`,level:1,kind:`numeric`,status:`unverified`,prompt:`As $x \\to a$, $f(x) \\to 4$ and $g(x) \\to -2$. Find $\\lim_{x \\to a} \\left(f(x) g(x) + \\frac{f(x)}{g(x)}\\right)$.`,answer:-10,hint:`By the limit laws, replace $f$ by 4 and $g$ by $-2$.`,solutionSteps:[`The limit laws let you use the limits in place of the functions, since both exist and $-2 \\ne 0$.`,`$4 \\cdot (-2) + \\frac{4}{-2} = -8 - 2 = -10$.`],mistakes:[{answer:-6,tag:`substitution-sign`,feedback:`$\\frac{4}{-2} = -2$, so it subtracts: $-8 - 2$.`},{answer:-8.5,tag:`limit-law-quotient`,feedback:`The quotient is $\\frac{f}{g} = \\frac{4}{-2} = -2$, not $\\frac{g}{f} = -\\frac{1}{2}$.`}]},{id:`limit-laws-3`,level:2,kind:`numeric`,status:`unverified`,prompt:`Find $\\lim_{x \\to 4} \\frac{x^2 - x - 12}{x - 4}$.`,answer:7,limit:{of:`(x^2 - x - 12) / (x - 4)`,at:4},hint:`Substituting gives $\\frac{0}{0}$. Factor the top: $x^2 - x - 12 = (x - 4)(x + 3)$.`,solutionSteps:[`Substituting gives $\\frac{16 - 4 - 12}{0} = \\frac{0}{0}$, so simplify.`,`Factor: $\\frac{(x - 4)(x + 3)}{x - 4} = x + 3$ for $x \\ne 4$.`,`Substitute: $4 + 3 = 7$.`],mistakes:[{answer:0,tag:`zero-over-zero-is-zero`,feedback:`$\\frac{0}{0}$ is not 0; it means simplify first. Factor the top and cancel $x - 4$.`},{answer:-1,tag:`factoring`,feedback:`The top factors as $(x - 4)(x + 3)$; check by expanding. After cancelling, $x + 3 \\to 7$.`}]},{id:`limit-laws-4`,level:2,kind:`numeric`,status:`unverified`,prompt:`Find $\\lim_{x \\to 0} \\frac{\\sqrt{x + 9} - 3}{x}$.`,answer:.16666666666666666,limit:{of:`(sqrt(x + 9) - 3) / x`,at:0},hint:`Multiply the top and bottom by the conjugate, $\\sqrt{x + 9} + 3$.`,solutionSteps:[`Substituting gives $\\frac{0}{0}$. Multiply by $\\frac{\\sqrt{x + 9} + 3}{\\sqrt{x + 9} + 3}$.`,`The top becomes $(x + 9) - 9 = x$, so the fraction is $\\frac{x}{x(\\sqrt{x + 9} + 3)} = \\frac{1}{\\sqrt{x + 9} + 3}$.`,`Substitute: $\\frac{1}{3 + 3} = \\frac{1}{6}$.`],mistakes:[{answer:0,tag:`zero-over-zero-is-zero`,feedback:`$\\frac{0}{0}$ is not 0. Multiply by the conjugate to cancel the $x$.`},{answer:6,tag:`conjugate-flipped`,feedback:`After cancelling, the $\\sqrt{x + 9} + 3$ is on the bottom: $\\frac{1}{6}$.`}]},{id:`limit-laws-5`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`What is $\\lim_{x \\to 0} x^2 \\sin\\left(\\frac{1}{x}\\right)$?`,solutionSteps:[`$\\sin\\left(\\frac{1}{x}\\right)$ stays between $-1$ and $1$, so $-x^2 \\le x^2 \\sin\\left(\\frac{1}{x}\\right) \\le x^2$.`,`Both $-x^2$ and $x^2$ go to 0 as $x \\to 0$.`,`By the squeeze theorem, the limit is 0.`],options:[{text:`0, by the squeeze theorem`,correct:!0},{text:`It does not exist, because $\\sin\\left(\\frac{1}{x}\\right)$ oscillates`,tag:`squeeze`,feedback:`The oscillation is trapped between $-x^2$ and $x^2$, which both shrink to 0.`},{text:`0, by the product law: $0 \\cdot \\lim \\sin\\left(\\frac{1}{x}\\right)$`,tag:`squeeze`,feedback:`The answer is right, but the product law needs both limits to exist, and $\\lim \\sin\\left(\\frac{1}{x}\\right)$ does not. Use the squeeze theorem.`},{text:`1`,tag:`squeeze`,feedback:`That is $\\lim \\frac{\\sin x}{x}$. Here the $x^2$ factor shrinks everything to 0.`}]},{id:`limit-laws-6`,level:3,kind:`numeric`,status:`unverified`,prompt:`Find $\\lim_{x \\to 1} \\left(\\frac{1}{x - 1} - \\frac{2}{x^2 - 1}\\right)$.`,answer:.5,limit:{of:`1/(x - 1) - 2/(x^2 - 1)`,at:1},hint:`Combine into one fraction over $x^2 - 1 = (x - 1)(x + 1)$ before substituting.`,solutionSteps:[`Common bottom: $\\frac{x + 1}{(x - 1)(x + 1)} - \\frac{2}{(x - 1)(x + 1)} = \\frac{x - 1}{(x - 1)(x + 1)}$.`,`Cancel: $\\frac{1}{x + 1}$ for $x \\ne 1$.`,`Substitute: $\\frac{1}{2}$.`],mistakes:[{answer:0,tag:`infinity-minus-infinity`,feedback:`Both terms blow up, and $\\infty - \\infty$ is undetermined, not 0. Combine the fractions first.`},{answer:-1,tag:`factoring`,feedback:`$x^2 - 1 = (x - 1)(x + 1)$, so the first fraction needs a factor $x + 1$ on top, giving $\\frac{x - 1}{x^2 - 1}$.`}]}]},{id:`continuity`,title:`Continuity`,objective:`Test continuity at a point, classify discontinuities, and use the Intermediate Value Theorem.`,prerequisites:[`limit-laws`],source:{title:`OpenStax Calculus Volume 1`,section:`2.4 Continuity`,url:`https://openstax.org/books/calculus-volume-1/pages/2-4-continuity`},status:`unverified`,explanation:[`$f$ is continuous at $a$ when three things hold: $f(a)$ is defined, $\\lim_{x \\to a} f(x)$ exists, and the two are equal.`,`Polynomials, rational functions, roots, trig, exponential and log functions are continuous wherever they are defined, and so are their sums, products, quotients and compositions.`,`Kinds of discontinuity: removable (a hole: the limit exists but $f(a)$ is missing or different), jump (the one-sided limits differ) and infinite (a vertical asymptote).`,`Intermediate Value Theorem: if $f$ is continuous on $[a, b]$ and $N$ is between $f(a)$ and $f(b)$, then $f(c) = N$ for some $c$ in $(a, b)$. It shows that an equation has a solution.`],takeaways:[`Continuous: defined, limit exists, and they match.`,`Removable, jump or infinite.`,`A sign change on a continuous function means a root in between.`],example:{problem:`Is $f(x) = \\frac{x^2 - 4}{x - 2}$ continuous at $x = 2$?`,steps:[`$f(2)$ is not defined, so $f$ is not continuous at 2.`,`The limit exists: $\\frac{(x - 2)(x + 2)}{x - 2} = x + 2 \\to 4$. So it is a removable discontinuity, a hole.`,`Defining $f(2) = 4$ would make $f$ continuous there.`]},questions:[{id:`continuity-1`,level:1,kind:`multiple-choice`,status:`unverified`,prompt:`Which of these is not needed for $f$ to be continuous at $a$?`,solutionSteps:[`Continuity needs $f(a)$ defined, the limit at $a$ to exist, and the two to be equal.`,`A derivative is not part of it: $|x|$ is continuous at 0 with no derivative there.`],options:[{text:`$f'(a)$ exists`,correct:!0},{text:`$f(a)$ is defined`,tag:`continuity-conditions`,feedback:`This is needed: a function with a hole at $a$ is not continuous there.`},{text:`$\\lim_{x \\to a} f(x)$ exists`,tag:`continuity-conditions`,feedback:`This is needed: a jump, where the sides disagree, breaks continuity.`},{text:`$\\lim_{x \\to a} f(x) = f(a)$`,tag:`continuity-conditions`,feedback:`This is the heart of continuity: the graph has no gap at $a$.`}]},{id:`continuity-2`,level:1,kind:`multiple-choice`,status:`unverified`,prompt:`What kind of discontinuity does $f(x) = \\frac{1}{x - 3}$ have at $x = 3$?`,solutionSteps:[`As $x \\to 3$, the bottom goes to 0 and the top stays 1.`,`So $f$ grows without bound: an infinite discontinuity, with a vertical asymptote at $x = 3$.`],options:[{text:`Infinite: a vertical asymptote`,correct:!0},{text:`Removable: a hole`,tag:`discontinuity-type`,feedback:`A hole needs the limit to exist. Here the values blow up.`},{text:`Jump`,tag:`discontinuity-type`,feedback:`A jump has finite one-sided limits that differ. Here they are $-\\infty$ and $\\infty$.`},{text:`None: it is continuous`,tag:`discontinuity-type`,feedback:`$f(3)$ is not defined, so it cannot be continuous at 3.`}]},{id:`continuity-3`,level:2,kind:`numeric`,status:`unverified`,prompt:`Find $k$ so that $f(x) = x^2 + k$ for $x < 2$ and $f(x) = 3x - 1$ for $x \\ge 2$ is continuous at $x = 2$.`,answer:1,continuityConstant:{left:`x^2 + k`,right:`3x - 1`,at:2},hint:`The two pieces must meet at $x = 2$: set $2^2 + k = 3(2) - 1$.`,solutionSteps:[`The left limit is $4 + k$ and the right limit (and $f(2)$) is $3(2) - 1 = 5$.`,`Continuity needs them equal: $4 + k = 5$.`,`So $k = 1$.`],mistakes:[{answer:5,tag:`continuity-matching`,feedback:`5 is the value of the right piece. The left piece is $4 + k$, so $k = 5 - 4$.`},{answer:-1,tag:`continuity-matching`,feedback:`Solve $4 + k = 5$: $k = 1$.`}]},{id:`continuity-4`,level:2,kind:`numeric`,status:`unverified`,prompt:`$f(x) = \\frac{x^2 - 16}{x - 4}$ for $x \\ne 4$. What value of $f(4)$ makes $f$ continuous at 4?`,answer:8,limit:{of:`(x^2 - 16) / (x - 4)`,at:4},hint:`$f(4)$ must equal the limit. Factor the top as $(x - 4)(x + 4)$.`,solutionSteps:[`For continuity, $f(4)$ must equal $\\lim_{x \\to 4} f(x)$.`,`$\\frac{(x - 4)(x + 4)}{x - 4} = x + 4$ for $x \\ne 4$.`,`The limit is $4 + 4 = 8$, so $f(4) = 8$.`],mistakes:[{answer:0,tag:`zero-over-zero-is-zero`,feedback:`$\\frac{0}{0}$ is not 0. Factor and cancel to find the limit.`},{answer:4,tag:`factoring`,feedback:`After cancelling, $x + 4$ at $x = 4$ is 8.`}]},{id:`continuity-5`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`Why does $x^3 + x - 1 = 0$ have a solution between 0 and 1?`,solutionSteps:[`$f(x) = x^3 + x - 1$ is a polynomial, so it is continuous on $[0, 1]$.`,`$f(0) = -1 < 0$ and $f(1) = 1 > 0$.`,`By the Intermediate Value Theorem, $f(c) = 0$ for some $c$ in $(0, 1)$.`],options:[{text:`$f$ is continuous, $f(0) = -1$ and $f(1) = 1$, so it crosses 0 in between`,correct:!0},{text:`$f(0.5) = 0$`,tag:`ivt`,feedback:`$f(0.5) = 0.125 + 0.5 - 1 = -0.375$. The theorem shows a root exists without finding it.`},{text:`Every polynomial has a root between 0 and 1`,tag:`ivt`,feedback:`$x^2 + 1$ has none at all. The sign change on $[0, 1]$ is what matters.`},{text:`$f$ is increasing`,tag:`ivt`,feedback:`Increasing alone is not enough: $x + 5$ is increasing with no root in $[0, 1]$. It needs a sign change.`}]},{id:`continuity-6`,level:3,kind:`numeric`,status:`unverified`,prompt:`Find $k$ so that $f(x) = kx + 3$ for $x < 1$ and $f(x) = x^2 + 2k$ for $x \\ge 1$ is continuous everywhere.`,answer:2,continuityConstant:{left:`k*x + 3`,right:`x^2 + 2*k`,at:1},hint:`Both pieces are continuous on their own. Make them meet at $x = 1$: $k + 3 = 1 + 2k$.`,solutionSteps:[`Each piece is a polynomial, so the only question is $x = 1$.`,`Left: $k(1) + 3 = k + 3$. Right: $1^2 + 2k = 1 + 2k$.`,`Set them equal: $k + 3 = 1 + 2k$, so $k = 2$.`],mistakes:[{answer:-2,tag:`continuity-matching`,feedback:`From $k + 3 = 1 + 2k$, subtract $k$ and 1 from both sides: $2 = k$.`},{answer:4,tag:`continuity-matching`,feedback:`Check: with $k = 4$ the left gives 7 and the right gives 9. Solve $k + 3 = 1 + 2k$.`}]}]},{id:`limits-at-infinity`,title:`Limits at infinity`,objective:`Find limits as x grows without bound and the horizontal asymptotes they give.`,prerequisites:[`limit-laws`],source:{title:`OpenStax Calculus Volume 1`,section:`4.6 Limits at Infinity and Asymptotes`,url:`https://openstax.org/books/calculus-volume-1/pages/4-6-limits-at-infinity-and-asymptotes`},status:`unverified`,explanation:[`$\\lim_{x \\to \\infty} f(x) = L$ means $f(x)$ gets close to $L$ as $x$ grows without bound. The line $y = L$ is then a horizontal asymptote.`,`$\\frac{1}{x^n} \\to 0$ as $x \\to \\infty$ for any $n > 0$. For a rational function, divide the top and bottom by the highest power of $x$ in the bottom.`,`Comparing degrees: if the top's degree is smaller, the limit is 0; if they are equal, it is the ratio of the leading coefficients; if the top's is larger, the function grows without bound.`,`Exponentials beat powers: $\\frac{x^n}{e^x} \\to 0$ for every $n$.`],takeaways:[`Divide by the highest power in the bottom.`,`Equal degrees: ratio of the leading coefficients.`,`$e^x$ outgrows every power of $x$.`],example:{problem:`Find $\\lim_{x \\to \\infty} \\frac{2x^3 - x}{4x^3 + 7}$.`,steps:[`Divide the top and bottom by $x^3$: $\\frac{2 - 1/x^2}{4 + 7/x^3}$.`,`The small terms go to 0, leaving $\\frac{2}{4} = \\frac{1}{2}$.`]},questions:[{id:`limits-at-infinity-1`,level:1,kind:`numeric`,status:`unverified`,prompt:`Find $\\lim_{x \\to \\infty} \\frac{7x - 2}{2x + 5}$.`,answer:3.5,limit:{of:`(7x - 2) / (2x + 5)`,at:`infinity`},hint:`Equal degrees: the limit is the ratio of the leading coefficients.`,solutionSteps:[`Divide the top and bottom by $x$: $\\frac{7 - 2/x}{2 + 5/x}$.`,`As $x \\to \\infty$ the small terms vanish: $\\frac{7}{2} = 3.5$.`],mistakes:[{answer:-.4,tag:`infinity-constant-terms`,feedback:`For large $x$ the constant terms do not matter; the $x$ terms do. Compare $7x$ and $2x$.`},{answer:0,tag:`infinity-over-infinity`,feedback:`$\\frac{\\infty}{\\infty}$ is undetermined, not 0. Both parts grow like $x$, so compare their coefficients.`}]},{id:`limits-at-infinity-2`,level:1,kind:`multiple-choice`,status:`unverified`,prompt:`What is the horizontal asymptote of $y = \\frac{4x + 1}{x^2 + 3}$?`,solutionSteps:[`The top has degree 1 and the bottom degree 2.`,`The bottom grows faster, so the fraction goes to 0: the asymptote is $y = 0$.`],options:[{text:`$y = 0$`,correct:!0},{text:`$y = 4$`,tag:`infinity-degrees`,feedback:`That would be the answer if both had degree 1. Here the bottom has the higher degree.`},{text:`$y = \\frac{1}{3}$`,tag:`infinity-constant-terms`,feedback:`$\\frac{1}{3}$ is the value at $x = 0$. Far out, the highest powers decide.`},{text:`There is none`,tag:`infinity-degrees`,feedback:`The function approaches 0 far out, so $y = 0$ is an asymptote.`}]},{id:`limits-at-infinity-3`,level:2,kind:`numeric`,status:`unverified`,prompt:`Find $\\lim_{x \\to \\infty} \\frac{\\sqrt{9x^2 + 1}}{x + 2}$.`,answer:3,limit:{of:`sqrt(9x^2 + 1) / (x + 2)`,at:`infinity`},hint:`For large positive $x$, $\\sqrt{9x^2 + 1}$ behaves like $\\sqrt{9x^2} = 3x$.`,solutionSteps:[`Divide the top and bottom by $x$. For $x > 0$, $x = \\sqrt{x^2}$, so the top becomes $\\sqrt{9 + 1/x^2}$.`,`The bottom becomes $1 + 2/x$.`,`As $x \\to \\infty$: $\\frac{\\sqrt{9}}{1} = 3$.`],mistakes:[{answer:9,tag:`infinity-root`,feedback:`The square root applies to the 9 as well: $\\sqrt{9x^2} = 3x$.`},{answer:0,tag:`infinity-over-infinity`,feedback:`$\\frac{\\infty}{\\infty}$ is undetermined, not 0. The top grows like $3x$ and the bottom like $x$.`}]},{id:`limits-at-infinity-4`,level:2,kind:`numeric`,status:`unverified`,prompt:`Find $\\lim_{x \\to \\infty} \\left(\\sqrt{x^2 + 4x} - x\\right)$.`,answer:2,limit:{of:`sqrt(x^2 + 4x) - x`,at:`infinity`},hint:`Multiply and divide by the conjugate, $\\sqrt{x^2 + 4x} + x$.`,solutionSteps:[`Multiply by $\\frac{\\sqrt{x^2 + 4x} + x}{\\sqrt{x^2 + 4x} + x}$: the top becomes $x^2 + 4x - x^2 = 4x$.`,`So the expression is $\\frac{4x}{\\sqrt{x^2 + 4x} + x}$. Divide the top and bottom by $x$: $\\frac{4}{\\sqrt{1 + 4/x} + 1}$.`,`As $x \\to \\infty$: $\\frac{4}{1 + 1} = 2$.`],mistakes:[{answer:0,tag:`infinity-minus-infinity`,feedback:`$\\infty - \\infty$ is undetermined, not 0. Use the conjugate to turn it into a fraction.`},{answer:4,tag:`conjugate-flipped`,feedback:`The bottom becomes $\\sqrt{x^2 + 4x} + x$, which is about $2x$, so the limit is $\\frac{4x}{2x} = 2$.`}]},{id:`limits-at-infinity-5`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`What is $\\lim_{x \\to \\infty} \\frac{x^{100}}{e^x}$?`,solutionSteps:[`Both grow without bound, but exponentials grow faster than any power.`,`Applying L'Hospital's rule 100 times leaves $\\frac{100!}{e^x}$, which goes to 0.`],options:[{text:`0, because $e^x$ grows faster than any power of $x$`,correct:!0},{text:`$\\infty$, because $x^{100}$ is enormous`,tag:`infinity-growth-rates`,feedback:`It is larger for a while, but $e^x$ overtakes every power of $x$ eventually.`},{text:`1, because both go to infinity`,tag:`infinity-over-infinity`,feedback:`$\\frac{\\infty}{\\infty}$ is undetermined; it depends on which grows faster.`},{text:`It does not exist`,tag:`infinity-growth-rates`,feedback:`It exists: the bottom wins, and the fraction shrinks to 0.`}]},{id:`limits-at-infinity-6`,level:3,kind:`numeric`,status:`unverified`,prompt:`Find $\\lim_{x \\to \\infty} x \\sin\\left(\\frac{1}{x}\\right)$.`,answer:1,limit:{of:`x * sin(1/x)`,at:`infinity`},hint:`Let $t = \\frac{1}{x}$. As $x \\to \\infty$, $t \\to 0^+$.`,solutionSteps:[`Let $t = \\frac{1}{x}$, so $x = \\frac{1}{t}$ and $t \\to 0^+$.`,`The expression becomes $\\frac{\\sin t}{t}$.`,`$\\lim_{t \\to 0} \\frac{\\sin t}{t} = 1$.`],mistakes:[{answer:0,tag:`zero-times-infinity`,feedback:`$\\sin\\left(\\frac{1}{x}\\right) \\to 0$, but $x \\to \\infty$ at the same time, and $0 \\cdot \\infty$ is undetermined. Substitute $t = \\frac{1}{x}$.`}]}]},{id:`derivative-definition`,title:`The definition of the derivative`,objective:`Find slopes, rates of change and derivatives from the limit definition.`,prerequisites:[`limit-laws`],source:{title:`OpenStax Calculus Volume 1`,section:`3.1 Defining the Derivative`,url:`https://openstax.org/books/calculus-volume-1/pages/3-1-defining-the-derivative`},status:`unverified`,explanation:[`The slope of the secant line through $(a, f(a))$ and $(a + h, f(a + h))$ is $\\frac{f(a + h) - f(a)}{h}$. As $h \\to 0$ it becomes the slope of the tangent line: $f'(a) = \\lim_{h \\to 0} \\frac{f(a + h) - f(a)}{h}$.`,`The same limit is the instantaneous rate of change. For a position $s(t)$, the average velocity over $[a, b]$ is $\\frac{s(b) - s(a)}{b - a}$, and $s'(t)$ is the velocity.`,`Letting $a$ vary gives the derivative as a function: $f'(x) = \\lim_{h \\to 0} \\frac{f(x + h) - f(x)}{h}$.`,`A function is not differentiable at a corner (like $|x|$ at 0), at a vertical tangent, or where it is not continuous. Differentiable implies continuous, but not the other way around.`],takeaways:[`$f'(a) = \\lim_{h \\to 0} \\frac{f(a + h) - f(a)}{h}$.`,`Secant slope is an average rate; tangent slope is an instantaneous rate.`,`Corners and jumps have no derivative.`],example:{problem:`Use the definition to find $f'(3)$ for $f(x) = x^2$.`,steps:[`$\\frac{f(3 + h) - f(3)}{h} = \\frac{9 + 6h + h^2 - 9}{h} = \\frac{6h + h^2}{h} = 6 + h$.`,`As $h \\to 0$, $6 + h \\to 6$, so $f'(3) = 6$.`]},questions:[{id:`derivative-definition-1`,level:1,kind:`multiple-choice`,status:`unverified`,prompt:`Which limit is $f'(a)$?`,solutionSteps:[`$f'(a)$ is the limit of secant slopes: rise $f(a + h) - f(a)$ over run $h$.`,`So $f'(a) = \\lim_{h \\to 0} \\frac{f(a + h) - f(a)}{h}$.`],options:[{text:`$\\lim_{h \\to 0} \\frac{f(a + h) - f(a)}{h}$`,correct:!0},{text:`$\\lim_{h \\to 0} \\frac{f(a + h) - f(a)}{a}$`,tag:`derivative-definition-run`,feedback:`The run between the two points is $h$, not $a$.`},{text:`$\\lim_{h \\to 0} \\left(f(a + h) - f(a)\\right)$`,tag:`derivative-definition-run`,feedback:`That is only the rise, which goes to 0 for any continuous $f$. Divide by the run $h$.`},{text:`$\\frac{f(a + h) - f(a)}{h}$ with $h = 0$`,tag:`derivative-definition-run`,feedback:`At $h = 0$ that is $\\frac{0}{0}$. The derivative is the limit as $h$ approaches 0.`}]},{id:`derivative-definition-2`,level:1,kind:`numeric`,status:`unverified`,prompt:`An object's position is $s(t) = t^2$ meters at $t$ seconds. Find its average velocity, in m/s, from $t = 1$ to $t = 3$.`,answer:4,hint:`Average velocity is change in position over change in time: $\\frac{s(3) - s(1)}{3 - 1}$.`,solutionSteps:[`$s(3) = 9$ and $s(1) = 1$.`,`Average velocity $= \\frac{9 - 1}{3 - 1} = \\frac{8}{2} = 4$ m/s.`],mistakes:[{answer:8,tag:`average-rate-run`,feedback:`8 m is the change in position. Divide by the 2 seconds it took.`},{answer:6,tag:`average-vs-instant`,feedback:`6 m/s is the velocity at $t = 3$. The average over the interval is the secant slope.`}]},{id:`derivative-definition-3`,level:2,kind:`numeric`,status:`unverified`,prompt:`Use the definition of the derivative to find $f'(2)$ for $f(x) = x^2 + 3x$.`,answer:7,derivativeOf:`x^2 + 3x`,at:2,hint:`Expand $f(2 + h) = (2 + h)^2 + 3(2 + h)$, subtract $f(2) = 10$, and divide by $h$.`,solutionSteps:[`$f(2 + h) = 4 + 4h + h^2 + 6 + 3h = 10 + 7h + h^2$, and $f(2) = 10$.`,`$\\frac{f(2 + h) - f(2)}{h} = \\frac{7h + h^2}{h} = 7 + h$.`,`As $h \\to 0$: $f'(2) = 7$.`],mistakes:[{answer:4,tag:`derivative-dropped-term`,feedback:`That is the slope of $x^2$ alone. The $3x$ term adds 3.`},{answer:10,tag:`value-vs-derivative`,feedback:`10 is $f(2)$, the height. The derivative is the slope.`}]},{id:`derivative-definition-4`,level:2,kind:`expression`,status:`unverified`,prompt:`Use the definition of the derivative to find $f'(x)$ for $f(x) = \\frac{1}{x}$.`,answer:`-1/x^2`,derivativeOf:`1/x`,hint:`Combine $\\frac{1}{x + h} - \\frac{1}{x}$ into one fraction before dividing by $h$.`,solutionSteps:[`$\\frac{1}{x + h} - \\frac{1}{x} = \\frac{x - (x + h)}{x(x + h)} = \\frac{-h}{x(x + h)}$.`,`Divide by $h$: $\\frac{-1}{x(x + h)}$.`,`As $h \\to 0$: $f'(x) = -\\frac{1}{x^2}$.`],mistakes:[{answer:`1/x^2`,tag:`derivative-definition-sign`,feedback:`$x - (x + h) = -h$, so the result is negative.`},{answer:`-1/x`,tag:`derivative-definition-limit`,feedback:`Let $h \\to 0$ in $\\frac{-1}{x(x + h)}$: the bottom becomes $x \\cdot x = x^2$.`}]},{id:`derivative-definition-5`,level:3,kind:`multiple-choice`,status:`unverified`,prompt:`$f(x) = |x|$ at $x = 0$ is:`,solutionSteps:[`$|x|$ is continuous at 0: the limit and the value are both 0.`,`The difference quotient $\\frac{|h|}{h}$ is $-1$ from the left and $1$ from the right, so its limit does not exist.`,`The graph has a corner at 0: continuous, but not differentiable.`],options:[{text:`Continuous but not differentiable`,correct:!0},{text:`Differentiable, with derivative 0`,tag:`corner`,feedback:`The slopes are $-1$ on the left and $1$ on the right. They do not agree, so there is no single slope.`},{text:`Neither continuous nor differentiable`,tag:`corner`,feedback:`There is no gap: $\\lim_{x \\to 0} |x| = 0 = |0|$.`},{text:`Differentiable but not continuous`,tag:`corner`,feedback:`That is impossible: every differentiable function is continuous.`}]},{id:`derivative-definition-6`,level:3,kind:`numeric`,status:`unverified`,prompt:`The limit $\\lim_{h \\to 0} \\frac{(2 + h)^5 - 32}{h}$ is the derivative of some function at some point. Find its value.`,answer:80,derivativeOf:`x^5`,at:2,hint:`It matches $\\frac{f(a + h) - f(a)}{h}$ with $f(x) = x^5$ and $a = 2$, since $2^5 = 32$.`,solutionSteps:[`Compare with $\\frac{f(a + h) - f(a)}{h}$: $f(x) = x^5$ and $a = 2$, since $f(2) = 32$.`,`So the limit is $f'(2)$, and $f'(x) = 5x^4$.`,`$f'(2) = 5 \\cdot 16 = 80$.`],mistakes:[{answer:32,tag:`value-vs-derivative`,feedback:`32 is $f(2) = 2^5$. The limit is the slope there, $f'(2)$.`},{answer:0,tag:`zero-over-zero-is-zero`,feedback:`Substituting $h = 0$ gives $\\frac{0}{0}$, which is not 0. Recognize the limit as a derivative.`}]}]}]},o={1:`Check`,2:`Apply`,3:`Concept`},s=a,c=r,l=t,u=i,d=n,f=[s,c,l,u,d];function p(e){for(let t of f){let n=t.concepts.find(t=>t.id===e);if(n)return{unit:t,concept:n}}}function m(e,t){return e.questions.filter(e=>e.level===t)}function h(e){return e.status!==`verified`||e.questions.some(e=>e.status!==`verified`)}var g=e();function _(){return(0,g.jsx)(`span`,{className:`unreviewed-label`,children:`Not yet reviewed`})}export{c as a,u as c,d as i,s as l,o as n,p as o,l as r,h as s,_ as t,m as u};